                'anchor' => '<h2>The part that matters: it amplifies losses exactly as much as gains</h2>',
                'src'    => $assets . 'leverage-example.png',
                'alt'    => 'Bar chart comparing a $1,000 margin deposit to the $30,000 position it controls at 30:1 leverage',
                'caption'=> '30:1 leverage: a small deposit, a much larger position.',
                'before' => true,
            ),
            array(
                'anchor' => '<h2>Margin calls and stop-outs</h2>',
                'src'    => $assets . 'leverage-caps-chart.png',
                'alt'    => 'Bar chart of maximum leverage for EU retail clients by asset class: 30:1 major FX pairs, 20:1 non-major pairs/gold/indices, 10:1 other commodities, 5:1 equities, 2:1 crypto',
                'caption'=> 'Retail leverage caps under ESMA rules, by asset class.',
                'before' => true,
            ),
        ),
    );

    foreach ( $guides as &$guide ) {
        if ( empty( $body_images[ $guide['slug'] ] ) ) {
            continue;
        }
        foreach ( $body_images[ $guide['slug'] ] as $img ) {
            $figure = '<figure><img src="' . esc_url( $img['src'] ) . '" alt="' . esc_attr( $img['alt'] ) . '" loading="lazy"><figcaption>' . esc_html( $img['caption'] ) . '</figcaption></figure>' . "\n\n";
            $guide['content'] = str_replace( $img['anchor'], $figure . $img['anchor'], $guide['content'] );
        }
    }
    unset( $guide );

    $bylines = array(
        'how-to-start-trading-forex'               => 'markets-editor',
        'understanding-leverage-in-forex-trading'   => 'markets-editor',
        'how-to-read-candlestick-patterns'          => 'technical-writer',
    );

    foreach ( $guides as $guide ) {
        $existing = get_page_by_path( $guide['slug'], OBJECT, 'post' );
        if ( $existing ) {
            $post_id = $existing->ID;
        } else {
            $post_id = wp_insert_post( array(
                'post_title'   => $guide['title'],
                'post_name'    => $guide['slug'],
                'post_excerpt' => $guide['excerpt'],
                'post_content' => $guide['content'],
                'post_status'  => 'publish',
                'post_type'    => 'post',
                'post_category'=> array( $category_id ),
            ) );
            if ( $post_id && ! is_wp_error( $post_id ) && ! empty( $hero_images[ $guide['slug'] ] ) ) {
                update_post_meta( $post_id, '_guide_hero_image', $hero_images[ $guide['slug'] ] );
            }
        }

        if ( $post_id && ! is_wp_error( $post_id ) && ! empty( $bylines[ $guide['slug'] ] )
            && ! get_post_meta( $post_id, '_byline', true ) ) {
            update_post_meta( $post_id, '_byline', $bylines[ $guide['slug'] ] );
        }
    }
}
add_action( 'after_setup_theme', 'globalfxhub_ensure_guides_content' );

/**
 * Pretty URLs for individual broker review pages: /reviews/{slug}/
 * The "Reviews" page itself is auto-created above; this just adds the
 * rewrite rule for the /{slug}/ suffix and the "broker" query var it feeds.
 */
function globalfxhub_review_rewrite_rules() {
    add_rewrite_rule( '^reviews/([^/]+)/?$', 'index.php?pagename=reviews&broker=$matches[1]', 'top' );
}
add_action( 'init', 'globalfxhub_review_rewrite_rules' );

function globalfxhub_review_query_vars( $vars ) {
    $vars[] = 'broker';
    return $vars;
}
add_filter( 'query_vars', 'globalfxhub_review_query_vars' );

add_action( 'after_switch_theme', 'flush_rewrite_rules' );

/**
 * SEO for /reviews/{slug}/ pages.
 *
 * All broker URLs share one underlying "Reviews" Page object (the
 * broker itself is read from the "broker" query var, not a separate
 * post), so without this WordPress's defaults would give every one of
 * them the same <title>, the same canonical link (pointing at /reviews/
 * instead of its own URL), no meta description, and no structured data --
 * any of which can keep Google from indexing them as distinct, rankable
 * pages. This gives each broker's URL its own title, canonical, meta
 * description, and Review schema (using only our own disclosed-methodology
 * score -- never the third-party ratings shown further down the page).
 */
function globalfxhub_review_seo_title( $title_parts ) {
    $slug = get_query_var( 'broker' );
    if ( $slug ) {
        $broker = globalfxhub_get_broker_by_slug( $slug );
        if ( $broker ) {
            $title_parts['title'] = $broker['name'] . ' Review ' . date( 'Y' ) . ': Regulation, Fees & Platforms';
        }
    } elseif ( is_page( 'reviews' ) ) {
        $title_parts['title'] = 'Forex Broker Reviews ' . date( 'Y' ) . ': All CySEC-Regulated Brokers Rated';
    }
    return $title_parts;
}
add_filter( 'document_title_parts', 'globalfxhub_review_seo_title' );

function globalfxhub_review_canonical( $canonical_url ) {
    $slug = get_query_var( 'broker' );
    if ( $slug ) {
        $broker = globalfxhub_get_broker_by_slug( $slug );
        if ( $broker ) {
            return home_url( '/reviews/' . $broker['slug'] . '/' );
        }
    }
    return $canonical_url;
}
add_filter( 'get_canonical_url', 'globalfxhub_review_canonical' );

function globalfxhub_review_seo_head() {
    $slug = get_query_var( 'broker' );
    if ( ! $slug ) {
        if ( is_page( 'reviews' ) ) {
            echo '<meta name="description" content="' . esc_attr( 'In-depth, individually scored reviews of every broker in our rankings -- CySEC-, FCA-, or Seychelles FSA-licensed, or more than one -- covering regulation, cost, platforms, and track record, built from a disclosed methodology.' ) . '">' . "\n";
        }
        return;
    }

    $broker = globalfxhub_get_broker_by_slug( $slug );
    if ( ! $broker ) {
        return;
    }

    $reg_label = globalfxhub_broker_regulation_label( $broker );
    $deposit_label = $broker['min_deposit_display'] ? $broker['min_deposit_display'] . ' minimum deposit' : 'minimum deposit not independently confirmed';
    $spread_label  = null !== $broker['spread_eurusd'] ? $broker['spread_eurusd'] . ' pip average EUR/USD spread' : 'EUR/USD spread not independently confirmed';
    $description = sprintf(
        '%s review: %s, %s, %s. Scored %s/5 overall on regulation, cost, platforms and track record -- see the full breakdown and what other reviewers say.',
        $broker['name'],
        $reg_label,
        $deposit_label,
        $spread_label,
        $broker['scores']['overall']
    );
    echo '<meta name="description" content="' . esc_attr( $description ) . '">' . "\n";

    $schema = array(
        '@context'     => 'https://schema.org',
        '@type'        => 'Review',
        'itemReviewed' => array(
            '@type' => 'FinancialService',
            'name'  => $broker['name'],
        ),
        'reviewRating' => array(
            '@type'       => 'Rating',
            'ratingValue' => (string) $broker['scores']['overall'],
            'bestRating'  => '5',
            'worstRating' => '1',
        ),
        'author'    => array( '@type' => 'Organization', 'name' => 'GlobalFXHub' ),
        'publisher' => array( '@type' => 'Organization', 'name' => 'GlobalFXHub' ),
        'url'       => home_url( '/reviews/' . $broker['slug'] . '/' ),
    );
    echo '<script type="application/ld+json">' . wp_json_encode( $schema ) . '</script>' . "\n";
}
add_action( 'wp_head', 'globalfxhub_review_seo_head', 5 );

function globalfxhub_get_broker_by_slug( $slug ) {
    foreach ( globalfxhub_get_brokers() as $broker ) {
        if ( $broker['slug'] === $slug ) {
            return $broker;
        }
    }
    return null;
}

/**
 * This site isn't CySEC-only -- it also covers brokers whose primary (or
 * only) licence is elsewhere: the UK FCA and the Seychelles FSA so far.
 * A broker's 'cysec' field takes three shapes: a real licence number,
 * '—' (meaning EU-regulated elsewhere via MiFID passporting, no direct
 * CySEC licence), or null (no EU/CySEC regulation at all). 'fca' and
 * 'seychelles' each follow the same two-shape pattern as each other (a
 * licence/FRN number, or null with a matching '..._note' when a licence
 * is confirmed to exist but the number isn't) and are layered on top of
 * cysec independently, since many brokers hold two or all three at once.
 *
 * Centralizing this here (rather than repeating the same branching logic
 * in every template) is what makes it safe to introduce a new regulator
 * without missing a call site.
 */
function globalfxhub_broker_regulation_label( $broker ) {
    $parts = array();
    if ( ! empty( $broker['cysec'] ) && '—' !== $broker['cysec'] ) {
        $parts[] = 'CySEC No. ' . $broker['cysec'];
    } elseif ( '—' === $broker['cysec'] ) {
        $parts[] = 'EU-regulated (MiFID passporting)';
    }
    if ( ! empty( $broker['fca'] ) ) {
        $parts[] = 'FCA No. ' . $broker['fca'];
    } elseif ( ! empty( $broker['fca_note'] ) && array_key_exists( 'fca', $broker ) && null === $broker['fca'] ) {
        $parts[] = 'FCA-licensed (FRN unconfirmed)';
    }
    if ( ! empty( $broker['seychelles'] ) ) {
        $parts[] = 'FSA Seychelles No. ' . $broker['seychelles'];
    } elseif ( ! empty( $broker['seychelles_note'] ) && array_key_exists( 'seychelles', $broker ) && null === $broker['seychelles'] ) {
        $parts[] = 'FSA Seychelles-licensed (licence number unconfirmed)';
    }
    if ( empty( $parts ) ) {
        return 'Regulatory status not independently confirmed';
    }
    return implode( ' + ', $parts );
}

/**
 * Which regulator register(s) to point a "verify" link at, matching
 * whichever licence(s) globalfxhub_broker_regulation_label() actually
 * found -- a Seychelles-only broker no longer gets a CySEC-register link
 * it has no business pointing at.
 */
function globalfxhub_broker_verify_links( $broker ) {
    $links = array();
    if ( ! empty( $broker['cysec'] ) && '—' !== $broker['cysec'] ) {
        $links[] = array( 'label' => 'Verify on CySEC register', 'url' => 'https://www.cysec.gov.cy/en-GB/entities/investment-firms/cypriot/' );
    }
    if ( ! empty( $broker['fca'] ) || ! empty( $broker['fca_note'] ) ) {
        $links[] = array( 'label' => 'Verify on FCA register', 'url' => 'https://register.fca.org.uk/s/' );
    }
    if ( ! empty( $broker['seychelles'] ) || ! empty( $broker['seychelles_note'] ) ) {
        $links[] = array( 'label' => 'Verify on FSA Seychelles register', 'url' => 'https://fsaseychelles.sc/' );
    }
    return $links;
}

/**
 * Pros/cons derived from the same scored data used in the rankings and
 * compare tool, so a review page never asserts anything they don't.
 */
function globalfxhub_broker_pros_cons( $broker ) {
    $pros = array();
    $cons = array();
    $has_mt = in_array( 'MT4', $broker['platforms'], true ) || in_array( 'MT5', $broker['platforms'], true );

    $has_cysec = null !== $broker['cysec'];
    $has_fca = ! empty( $broker['fca'] ) || ! empty( $broker['fca_note'] );
    $has_eu_or_uk_reg = $has_cysec || $has_fca;

    if ( null !== $broker['scores']['regulation'] && $broker['scores']['regulation'] >= 4.0 ) {
        if ( $has_cysec ) {
            $base = ( '—' === $broker['cysec'] ) ? 'EU regulation (MiFID passporting)' : 'CySEC';
            if ( $has_fca ) {
                $base .= ' and FCA';
            }
        } elseif ( $has_fca ) {
            $base = 'FCA';
        } else {
            $base = 'FSA Seychelles licensing';
        }
        $pros[] = 'Wide regulatory footprint -- ' . $base . ' plus ' . $broker['other_reg_count'] . ' other regulator(s), including ' . implode( ', ', array_slice( $broker['other_reg'], 0, 2 ) );
    } elseif ( null !== $broker['scores']['regulation'] ) {
        $cons[] = 'Thinner regulatory footprint than most peers on this list';
    }

    if ( ! $has_eu_or_uk_reg ) {
        $cons[] = 'No EU, UK, or Australian-tier regulator -- its primary licence is offshore (Seychelles FSA), which offers materially less retail investor protection than an EU/MiFID licence.';
    }

    if ( null === $broker['scores']['cost'] ) {
        $cons[] = 'Minimum deposit and/or EUR/USD spread could not be independently confirmed -- check current terms directly with the broker.';
    } elseif ( $broker['scores']['cost'] >= 4.0 ) {
        $pros[] = 'Low cost to start: ' . $broker['min_deposit_display'] . ' minimum deposit, ' . $broker['spread_eurusd'] . ' pip average EUR/USD spread';
    } elseif ( $broker['scores']['cost'] <= 2.5 ) {
        $cons[] = 'Higher cost than most peers on this list (spread and/or minimum deposit)';
    }

    if ( count( $broker['platforms'] ) >= 3 ) {
        $pros[] = 'Broad platform choice: ' . implode( ', ', $broker['platforms'] );
    } elseif ( ! $has_mt ) {
        $cons[] = 'No MetaTrader (MT4/MT5) support -- proprietary platform only';
    }

    if ( null === $broker['scores']['track_record'] ) {
        $cons[] = 'Founding year could not be independently confirmed, so operating history could not be scored.';
    } elseif ( $broker['scores']['track_record'] >= 4.0 ) {
        $pros[] = 'Long operating history, trading since ' . $broker['founded'];
    } elseif ( $broker['scores']['track_record'] <= 2.0 ) {
        $cons[] = 'Shorter operating history than most peers, trading since ' . $broker['founded'];
    }

    if ( empty( $cons ) ) {
        $cons[] = 'No standout weaknesses versus peers in our researched criteria -- still confirm current terms directly with the broker.';
    }

    return array( 'pros' => $pros, 'cons' => $cons );
}

/**
 * Investor compensation coverage, derived purely from which jurisdictions a
 * broker is confirmed to hold (not researched per-broker -- these are the
 * general, publicly documented rules of each regulatory regime), so every
 * broker in the dataset gets an accurate answer to "what happens to my
 * money if this firm fails" with no new research required.
 */
function globalfxhub_broker_investor_protection( $broker ) {
    $parts = array();
    $has_fca = ! empty( $broker['fca'] ) || ! empty( $broker['fca_note'] );
    $has_cysec = null !== $broker['cysec'];
    $has_seychelles = ! empty( $broker['seychelles'] ) || ! empty( $broker['seychelles_note'] );

    if ( $has_fca ) {
        $parts[] = "Via its FCA-regulated UK entity, eligible clients are covered by the UK's Financial Services Compensation Scheme (FSCS) up to £85,000 per person if the firm fails.";
    }
    if ( $has_cysec ) {
        if ( '—' === $broker['cysec'] ) {
            $parts[] = "Via its EU-regulated entity (MiFID passporting), eligible clients are covered by that entity's home EU member state's investor compensation scheme -- typically up to €20,000, though the exact scheme and cap depend on which country licenses the entity.";
        } else {
            $parts[] = "Via its CySEC-regulated Cyprus entity, eligible clients are covered by Cyprus's Investor Compensation Fund (ICF) up to €20,000 per person if the firm fails.";
        }
    }
    if ( $has_seychelles ) {
        $parts[] = 'Via its Seychelles FSA-licensed entity, there is no statutory investor compensation scheme -- if that entity fails, there is no guaranteed fund to recover client money from.';
    }
    if ( empty( $parts ) ) {
        return 'No confirmed Tier-1 or Seychelles FSA licence was found for this broker in our research, so no investor compensation scheme can be stated with confidence -- verify directly with the broker which entity you would be contracting with and what protection, if any, applies.';
    }
    return implode( ' ', $parts );
}

/**
 * "Who this broker suits" / "who should look elsewhere", derived from
 * already-confirmed data fields (deposit minimum, platform breadth,
 * regulatory tier, sub-scores) rather than new research -- every reason
 * given traces back to a fact already disclosed elsewhere on the same
 * review page, so this never asserts anything not already backed by data.
 */
function globalfxhub_broker_who_for( $broker ) {
    $for = array();
    $against = array();

    $has_fca = ! empty( $broker['fca'] ) || ! empty( $broker['fca_note'] );
    $has_cysec = null !== $broker['cysec'];
    $has_seychelles = ! empty( $broker['seychelles'] ) || ! empty( $broker['seychelles_note'] );
    $has_eu_or_uk_reg = $has_cysec || $has_fca;

    if ( null !== $broker['min_deposit_usd'] ) {
        if ( $broker['min_deposit_usd'] <= 50 ) {
            $for[] = 'Beginners or smaller accounts -- the confirmed minimum deposit (' . $broker['min_deposit_display'] . ') is low enough to start with limited capital.';
        } elseif ( $broker['min_deposit_usd'] >= 1000 ) {
            $for[] = 'Well-capitalized or professional-style traders -- the confirmed minimum deposit (' . $broker['min_deposit_display'] . ') is higher than most retail-focused brokers in our researched set.';
            $against[] = 'Beginners or small accounts, given a higher minimum deposit (' . $broker['min_deposit_display'] . ') than most peers.';
        }
    }

    $platform_count = count( $broker['platforms'] );
    $has_mt = in_array( 'MT4', $broker['platforms'], true ) || in_array( 'MT5', $broker['platforms'], true );
    if ( $platform_count >= 3 ) {
        $for[] = 'Traders who want platform choice -- ' . $platform_count . ' platforms are confirmed, including ' . implode( ', ', array_slice( $broker['platforms'], 0, 2 ) ) . '.';
    } elseif ( $platform_count > 0 && ! $has_mt ) {
        $against[] = 'Traders specifically wanting MetaTrader (MT4/MT5) -- not among the platforms confirmed for this broker.';
    }

    if ( ! $has_eu_or_uk_reg && $has_seychelles ) {
        $against[] = 'Traders who need EU- or UK-level regulatory protection and investor compensation -- this broker\'s only confirmed licence is the Seychelles FSA, which carries materially lighter oversight and no compensation scheme (see Investor protection below).';
        $for[] = 'Traders outside the EU/UK who have already done their own due diligence on the offshore entity and are comfortable with that risk profile.';
    } elseif ( $has_eu_or_uk_reg ) {
        $for[] = 'EU- and/or UK-based traders who want the regulatory protections and investor compensation scheme that come with a CySEC and/or FCA licence (see Investor protection below).';
    }

    if ( null !== $broker['scores']['regulation'] && $broker['scores']['regulation'] >= 4.0 ) {
        $for[] = 'Traders who prioritize regulatory breadth -- this broker holds one of the wider confirmed Tier-1 regulatory footprints in our researched set.';
    }

    if ( null !== $broker['scores']['cost'] ) {
        if ( $broker['scores']['cost'] >= 4.0 ) {
            $for[] = 'Cost-sensitive traders -- this broker scores well on our cost factor (low spread and/or low minimum deposit relative to peers).';
        } elseif ( $broker['scores']['cost'] <= 2.5 ) {
            $against[] = 'Cost-sensitive traders -- this broker scores below most peers on our cost factor (higher spread and/or minimum deposit relative to the set).';
        }
    }

    if ( empty( $for ) ) {
        $for[] = 'Not enough independently confirmed data on this broker to characterize who it specifically suits -- verify current terms directly before choosing it.';
    }
    if ( empty( $against ) ) {
        $against[] = 'No specific "not for" signal in our researched criteria -- still confirm current terms directly with the broker.';
    }

    return array( 'for' => $for, 'against' => $against );
}

