        array( 'slug' => 'cfi', 'name' => 'CFI', 'entity' => 'Credit Financier Invest (CFI) Ltd', 'cysec' => '—', 'fca' => '828955', 'fca_note' => 'Held by Credit Financier Invest Limited, a separate UK group entity from the Dubai-headquartered Credit Financier Invest (CFI) Ltd reviewed as this broker\'s primary entity.', 'seychelles' => 'SD107', 'founded' => 1998, 'hq' => 'Dubai, UAE', 'min_deposit_usd' => 0, 'min_deposit_display' => 'No minimum', 'spread_eurusd' => 0.4, 'platforms' => array('MT5', 'cTrader', 'TradingView', 'Proprietary (CFI Trading App)'), 'other_reg' => array('FSCA'), 'other_reg_count' => 1, 'instruments' => '1500+ instruments across forex, stocks, energies, metals, indices, ETFs, crypto, bonds and futures', 'account_types' => 'Two tiers reported: a Zero Commission account (spreads roughly 0.4-1.1 pips) and a Dynamic Trader account (spreads from near 0.0 pips plus a per-trade commission), both with no minimum deposit per some sources. Leverage figures as high as 1:500 are advertised in some group marketing material, which would not apply to CySEC-regulated EU retail clients (capped at 1:30 under ESMA rules) -- a discrepancy worth flagging. Islamic/swap-free account availability is disputed: one source states CFI does not offer one, which would be unusual for a Cyprus-regulated broker with MENA-focused marketing and should be verified directly rather than assumed either way.', 'execution_model' => 'Not independently confirmed -- no explicit market-maker/STP/ECN classification was found for this entity. MT5, cTrader and copy trading are confirmed as available.', 'withdrawal_deposit_note' => 'One comparison source states no withdrawal fees are charged, but this wasn\'t corroborated by a second independent source, and no specific processing times or minimums were found.', 'overnight_financing' => 'Not independently confirmed -- no CFI-specific swap-calculation methodology was found in this research pass.', 'currency_conversion_fee' => 'Not independently confirmed -- no specific figure was found.', 'inactivity_fee' => 'One comparison source states no inactivity fee is charged; this is only provisionally confirmed, as it wasn\'t corroborated by a second independent source.', 'customer_service_note' => 'Sources disagree: one cites a strong Trustpilot rating around 4.7/5 (roughly 2,100 reviews), while another flags unreliable customer support as a drawback. Separately, CFI\'s Cyprus entity settled with CySEC for €150,000 over possible AML/compliance shortcomings -- a confirmed regulatory fact worth disclosing.', 'mobile_note' => 'CFI\'s apps collectively average around 3.7/5 on Google Play across a small portfolio of roughly five finance apps (not isolated to one trading app specifically), with one app showing 500,000+ installs; no single clean App Store rating was isolated for comparison.', 'education_note' => 'Reviews mention copy trading, webinars and other educational resources, though at least one source notes some content is limited to certain accounts or regions; no independent numeric education score was found specifically for CFI.', 'blurb' => 'CFI Financial Group traces its roots to Credit Financier Invest SAL, founded in Beirut in 1998, was reorganized as CFI Financial Group in 2015, and moved its headquarters to Dubai in 2017, and has fully phased out MT4 in favor of MT5, cTrader and TradingView.', 'scores' => array( 'regulation' => 2.6, 'cost' => 4.84, 'platforms' => 4.2, 'track_record' => 3.04, 'overall' => 3.68 ), 'rank' => 8 ),
        array( 'slug' => 'plus500', 'name' => 'Plus500', 'entity' => 'Plus500CY Ltd', 'cysec' => '250/14', 'fca' => '509909', 'seychelles' => 'SD039', 'founded' => 2008, 'hq' => 'Haifa, Israel (EU ops via Cyprus)', 'min_deposit_usd' => 54, 'min_deposit_display' => '€50', 'spread_eurusd' => 1.3, 'platforms' => array('WebTrader (proprietary)'), 'other_reg' => array('ASIC', 'FSCA', 'MAS', 'FMA'), 'other_reg_count' => 4, 'instruments' => '2,800+ CFDs across forex, indices, commodities, shares, ETFs, crypto', 'account_types' => 'Retail CFD (minimum $100, 2,800+ instruments, FX leverage capped at 1:30 under EU/UK retail rules), Professional (minimum $100, higher leverage on some asset classes, but forfeits investor-compensation-scheme protections), Islamic/swap-free (minimum $100), and an unlimited demo account with live pricing. All accounts are CFD-only -- Plus500 does not offer non-CFD or share-dealing accounts.', 'execution_model' => 'Market maker, commission-free -- trading costs are built entirely into the spread (reported from around 0.8 pips on EUR/USD).', 'withdrawal_deposit_note' => 'No deposit fee; deposits as low as $10 are possible per transaction, though $100 is the commonly cited minimum to open an account. Withdrawal processing is reported at 1-3 business days for Plus500\'s internal checks, then a further 3-7 business days (e-wallets) or 5-7 business days (bank transfer) for funds to arrive. Sources disagree on withdrawal fees -- one set cites a 1.75% processing fee (minimum $1, maximum $150) on all methods, which conflicts with Plus500\'s own broader public positioning that it covers most processing fees; verify the current wording on Plus500\'s own Fees & Charges page before relying on either claim.', 'overnight_financing' => 'Overnight funding is charged or credited based on a daily percentage disclosed per instrument within the platform. The Islamic account is swap-free, though the specific substitute mechanism (if any) wasn\'t detailed in this research pass.', 'currency_conversion_fee' => 'Up to 0.7% applied to a trade\'s realized profit/loss when the instrument\'s currency differs from the account\'s base currency, calculated after overnight funding -- confirmed via Plus500\'s own published FAQ.', 'inactivity_fee' => 'Up to $10/month (or the account-currency equivalent) if there\'s been no login for at least 3 months, continuing monthly thereafter and capped at the lesser of $10 or the remaining balance -- confirmed via Plus500\'s own Fees & Charges page.', 'customer_service_note' => 'Trustpilot rates it "Great," 4.0/5 from over 15,000 reviews. Independent commentary is mixed: praise for ease of use and platform design, alongside recurring concerns about withdrawal speed, account restrictions and support responsiveness.', 'mobile_note' => 'Reported around 4.5/5 on Google Play (100,000+ downloads) and 4.4/5 on the App Store (roughly 3,000 reviews).', 'education_note' => 'Reviews disagree on depth: one source describes the research content as thin (a few daily articles, limited market-update videos), while a separate review citation scores its education 4.4/5 -- likely reflecting that "education" and "research/analysis" are scored separately, so both findings are worth noting rather than picking one.', 'blurb' => 'Publicly listed (LSE: PLUS), one of the broadest regulatory footprints here, but no MT4/MT5 support.', 'scores' => array( 'regulation' => 5.0, 'cost' => 4.47, 'platforms' => 1.8, 'track_record' => 2.22, 'overall' => 3.65 ), 'rank' => 9 ),
        array( 'slug' => 'pepperstone', 'name' => 'Pepperstone', 'entity' => 'Pepperstone EU Limited', 'cysec' => '388/20', 'fca' => '684312', 'seychelles' => null, 'seychelles_note' => 'FSA Seychelles-licensed via Pepperstone International Markets Limited; exact SD number not independently confirmed', 'founded' => 2010, 'hq' => 'Melbourne, Australia', 'min_deposit_usd' => 10, 'min_deposit_display' => '$10', 'spread_eurusd' => 1.1, 'platforms' => array('MT4', 'MT5', 'cTrader', 'TradingView'), 'other_reg' => array('ASIC', 'DFSA'), 'other_reg_count' => 2, 'instruments' => '1,300+ instruments across forex, indices, commodities, shares', 'account_types' => 'Standard (spreads from about 1.0 pip, no commission), Razor (raw spreads from 0.0 pips plus roughly $6-7 round-turn commission per lot depending on platform), and Professional (higher leverage, eligibility-gated), with an Islamic/swap-free option on both Standard and Razor.', 'execution_model' => 'Markets itself as no-dealing-desk: Standard is STP-style, Razor is ECN-style, with direct market access (DMA) CFDs also available via cTrader and MT4/5 on both tiers.', 'withdrawal_deposit_note' => 'No fees except roughly $20/£15 on international bank-transfer withdrawals; no minimum on bank transfers, around £10 minimum via card, Apple Pay or Google Pay. Card deposits are instant; bank transfer deposits take up to 2 business days. Withdrawals: card/Apple/Google Pay up to 1 business day, domestic bank up to 2 days, international bank up to 7 days.', 'overnight_financing' => 'Swap is based on the tom-next rate from liquidity providers plus an admin/funding fee; the Standard account instead bakes in roughly a 1-pip markup rather than a separate commission. Islamic/swap-free accounts avoid the daily swap but are charged a reported $100-per-lot admin fee for every 5-day period a position stays open.', 'currency_conversion_fee' => 'No deposit fee from Pepperstone itself, though the sending bank or card network may apply its own conversion markup if the deposit currency differs from the account\'s base currency -- no specific percentage was independently confirmed.', 'inactivity_fee' => 'Multiple independent sources report no inactivity fee, though this wasn\'t independently verified against the EU entity\'s own client agreement directly.', 'customer_service_note' => 'Trustpilot rates it 4.5/5 (around 3,400 reviews), with about 94% of negative reviews answered within a week; one independent review site gives its support a 4.8/5. Support runs 24 hours Monday-Friday plus roughly 18 hours over the weekend. A small number of reviews allege trades blocked or positions threatened with closure without clear explanation.', 'mobile_note' => 'No numeric App Store or Google Play rating was independently confirmed; one review site gives the platform an 8.8/10 expert score for user-friendliness generally, though that isn\'t an app-store rating specifically.', 'education_note' => 'One independent review site rates its education 4.9/5, citing webinars run by experienced traders; broader independent commentary on depth wasn\'t confirmed in this research pass.', 'blurb' => 'Added its CySEC licence in 2020 ahead of Brexit to secure EU client access; strong reputation among active/algo traders for platform choice.', 'scores' => array( 'regulation' => 3.4, 'cost' => 4.56, 'platforms' => 4.2, 'track_record' => 2.06, 'overall' => 3.64 ), 'rank' => 10 ),
        array( 'slug' => 'exness', 'name' => 'Exness', 'entity' => 'Exness (Cy) Ltd', 'cysec' => '178/12', 'seychelles' => 'SD025', 'founded' => 2008, 'hq' => 'Limassol, Cyprus', 'min_deposit_usd' => 10, 'min_deposit_display' => '$10 (varies by payment method; some methods allow as low as $1)', 'spread_eurusd' => 0.2, 'platforms' => array('MT4', 'MT5', 'Proprietary (Exness Terminal)'), 'other_reg' => array('FSCA', 'CMA'), 'other_reg_count' => 2, 'instruments' => '100+ instruments across forex, indices, commodities, stock and crypto CFDs', 'account_types' => 'Standard (no commission), Pro, Raw Spread (commission-based, aimed at experienced traders), and Zero (offered in Standard/Pro/Raw variants with near-zero spreads on majors plus commission), with an Islamic/swap-free option across account types.', 'execution_model' => 'Sources disagree -- some describe Exness as effectively operating a market-maker/dealing-desk model by default, while Exness\'s own marketing and some comparison sites describe STP/no-dealing-desk execution. This is a genuine disagreement between sources rather than a settled fact; Exness\'s own order-execution policy would be the authoritative source to check.', 'withdrawal_deposit_note' => 'Deposits are reported to process within about 30 minutes; minimum deposit figures conflict across sources (as low as $1 on some, $200 for the Pro account per others) and weren\'t reliably confirmed. Many withdrawal methods are reported fee-free, though other (lower-confidence) sources cite card withdrawal costs of 1-4%, bank wire fees of $20-50, and payment-service fees of 0.5-4% -- these should be verified against Exness\'s own current fee page before relying on them.', 'overnight_financing' => 'Exness-specific swap-markup mechanics weren\'t independently confirmed in this research pass -- only generic, non-broker-specific explanations of forex swaps were found. Islamic/swap-free accounts are confirmed available, though the specific substitute fee structure, if any, wasn\'t confirmed.', 'currency_conversion_fee' => 'One lower-confidence source states fees apply on certain payment methods when depositing or withdrawing in a currency other than the one linked to the account, but no percentage was confirmed from a reputable source.', 'inactivity_fee' => 'Multiple independent sources confirm no inactivity fee, no deposit fee, and no internal withdrawal fee on dormant accounts.', 'customer_service_note' => 'Trustpilot rates it 4.5/5 from a very large base of reviews (29,000+), with 24/7 multi-channel support. Praise centers on responsiveness and execution; recurring complaints include withdrawal delays and, in some reviews, slow or unhelpful support.', 'mobile_note' => 'Reported figures vary by source -- Google Play ratings cited range from about 4.5 to 4.8 (review counts from roughly 12,000 to 220,000+ depending on source), and the App Store around 4.6. Source quality for these figures is moderate; treat as indicative rather than definitive.', 'education_note' => 'One independent comparison site specifically critiques Exness\'s educational material as limited for beginner investors. Demo accounts are notably generous (up to 100 MT4 plus 100 MT5 demo accounts), but webinars and articles aren\'t considered a particular strength by that reviewer.', 'blurb' => 'One of the highest-volume retail forex/CFD brokers globally, Exness offers its own proprietary Exness Terminal alongside MT4/MT5 and holds licences from CySEC, the FCA and South Africa\'s FSCA.', 'cysec_note' => 'Exness Group also holds licences in Seychelles (FSA), Mauritius (FSC), BVI (FSC), Curacao (CBCS), Jordan and the UAE, but these are not on the approved Tier-1 list so are excluded here.', 'fca' => null, 'fca_note' => 'FCA-licensed via Exness (UK) Ltd; per Exness\'s own disclosures this entity does not serve retail clients -- confirm current status before relying on it.', 'scores' => array( 'regulation' => 3.4, 'cost' => 4.92, 'platforms' => 3.4, 'track_record' => 2.22, 'overall' => 3.62 ), 'rank' => 11 ),
        array( 'slug' => 'admirals', 'name' => 'Admirals', 'entity' => 'Admirals Europe Ltd', 'cysec' => '201/13', 'seychelles' => 'SD073', 'founded' => 2001, 'hq' => 'Tallinn, Estonia (group HQ; Admirals Europe Ltd is the Cyprus-regulated subsidiary)', 'min_deposit_usd' => 108, 'min_deposit_display' => '€100 (EU/Cyprus entity, Trade.MT5 account)', 'spread_eurusd' => 0.8, 'platforms' => array('MT4', 'MT5', 'TradingView', 'Proprietary (Admirals Platform)'), 'other_reg' => array('FSCA'), 'other_reg_count' => 1, 'instruments' => 'Wide range of CFDs and real assets across forex, stocks, ETFs, indices, commodities and bonds', 'account_types' => 'Trade, Invest, and Zero account types, each offered as MT4 and/or MT5 variants (Zero only on MT5); Zero.MT5 spreads from around 0.1 pip, Trade.MT5 typical EUR/USD spread around 0.6 pip. Standard minimum deposit €100, though Zero.MT5 can be opened from as little as €1/$1. Islamic/swap-free and demo accounts are also offered.', 'execution_model' => 'Markets itself as STP/no-dealing-desk, though independent, broker-specific confirmation of the execution model (beyond generic STP explainer content) wasn\'t found in this research pass.', 'withdrawal_deposit_note' => 'No deposit fee; minimum deposit as low as $1. One free bank-transfer withdrawal per month, taking 3-5 business days; EUR-to-EU or GBP-to-UK transfers cost 1 unit of that currency; processed same business day if requested before 18:00 EET. No stated minimum withdrawal.', 'overnight_financing' => 'Islamic/swap-free accounts are confirmed to avoid overnight swaps; a specific benchmark-plus-markup formula for standard accounts wasn\'t found in this research pass beyond generic swap explainers.', 'currency_conversion_fee' => 'A 0.3% conversion fee (minimum 0.01 unit of the account\'s base currency) applies to stocks, ETFs, and stock/ETF CFDs quoted in a currency other than the account\'s; a separate 1% fee applies to internal transfers between accounts with different base currencies -- confirmed via Admirals\' own published payment terms.', 'inactivity_fee' => '€10/month after 24 months with no trades (only if the balance is above zero); up to 3 months of previously charged fees are refundable on reactivation -- confirmed via Admirals\' own fee page and reported by Finance Magnates.', 'customer_service_note' => 'Trustpilot rates the Admirals Group 4.2/5 from around 2,150 reviews, with praise for responsiveness; the company reportedly replies to all negative reviews within 48 hours.', 'mobile_note' => 'No numeric App Store or Google Play rating was found in this research pass.', 'education_note' => 'Offers a free "Premium Analytics" portal for all live clients (news and analysis from Dow Jones, Trading Central, Acuity) plus a Technical Insight tool via the MetaTrader Supreme Edition plugin; one independent review site ranks it #15 of 63 brokers overall with a 4-star research rating.', 'blurb' => 'One of the older and larger MetaTrader-focused broker groups on this list, founded in Estonia in 2001 and rebranded from Admiral Markets to Admirals in 2021.', 'cysec_note' => 'Previously ASIC-regulated via its Australian unit, which was sold and rebranded in 2025, ending direct ASIC-regulated presence.', 'fca' => '595450', 'scores' => array( 'regulation' => 2.6, 'cost' => 4.66, 'platforms' => 4.2, 'track_record' => 2.8, 'overall' => 3.58 ), 'rank' => 13 ),
        array( 'slug' => 'fxopen', 'name' => 'FXOpen', 'entity' => 'FXOpen EU Ltd', 'cysec' => '194/13', 'seychelles' => null, 'seychelles_note' => 'FSA Seychelles-licensed via FXON Ltd, per the official FSA Capital Markets register; licence number not independently confirmed.', 'founded' => 2003, 'hq' => 'London, UK (group); FXOpen EU Ltd, the CySEC entity, is based in Cyprus', 'min_deposit_usd' => 300, 'min_deposit_display' => '$300 / €300', 'spread_eurusd' => 1, 'platforms' => array('MT4', 'MT5', 'TradingView', 'Proprietary (TickTrader)'), 'other_reg' => array('ASIC'), 'other_reg_count' => 1, 'instruments' => 'Forex plus CFDs on indices, commodities, stocks and cryptocurrencies', 'account_types' => 'The EU entity (FXOpen EU Ltd) offers ECN-model accounts only, in Standard and "Pro" tiers, with a swap-free option, and a minimum deposit of $300/€300. Broader FXOpen group materials mention STP and crypto accounts, but these appear tied to other FXOpen group entities and weren\'t confirmed as available under the EU entity specifically.', 'execution_model' => 'Confirmed ECN for the EU entity specifically -- direct access to a pooled interbank liquidity feed with no dealing desk, per FXOpen\'s own published business-model page.', 'withdrawal_deposit_note' => 'Minimum deposit $300, with no deposit fees; international wire-transfer fees are passed through to the client. Requests made before 12:00 GMT are processed the same business day. Bank-transfer withdrawals take 1-3 business days, card withdrawals 2-5 business days.', 'overnight_financing' => 'Rollover is applied to positions still open at 23:59:30 platform time (processed between 23:59:00 and 00:05:00); no swap applies if a position is closed the same day. On the Islamic account, no swap is charged, but a fixed commission sized to match the swap amount is charged instead on overnight positions.', 'currency_conversion_fee' => 'FXOpen states it passes on bank/wire-transfer currency-conversion charges for international transfers, but no specific percentage was found in this research pass.', 'inactivity_fee' => 'An account is deemed dormant after 90 days with no trading activity (deposits/withdrawals don\'t reset this), after which a $10/month fee (or the remaining balance if smaller) is deducted until the balance reaches zero. A separate $50 reactivation fee after 90 days\' inactivity was referenced in one user complaint thread but is lower-confidence and should be checked against FXOpen\'s current entity-specific terms before relying on it.', 'customer_service_note' => 'Trustpilot ratings differ by regional listing -- around 3.7/5 globally (roughly 450 reviews) versus 2.8/5 on a Hong Kong-entity-specific listing. Email support is praised as efficient; live chat is criticized in some reviews as uninformed or giving outdated information, and a recurring complaint theme is deposits not being credited without clear explanation.', 'mobile_note' => 'No numeric App Store or Google Play rating was found in this research pass.', 'education_note' => 'One independent review site gives it a Trust Score of 76 and an overall rating of 6.9/10, with a below-average 5.5/10 research score; independent reviewers describe its educational materials as limited, lacking structured beginner/advanced video courses. Its proprietary TickTrader platform is well regarded for tools (1,200+ indicators, Level 2 pricing).', 'blurb' => 'FXOpen began in 2003 as a trading-education outfit before launching brokerage services in 2005, and today operates as a multi-entity group regulated separately by CySEC (Cyprus), the FCA (UK) and ASIC (Australia).', 'cysec_note' => 'FCA and ASIC licences are held by separate FXOpen group entities (UK and Australia), not by FXOpen EU Ltd itself.', 'fca' => '579202', 'scores' => array( 'regulation' => 2.6, 'cost' => 4.54, 'platforms' => 4.2, 'track_record' => 2.63, 'overall' => 3.51 ), 'rank' => 14 ),
        array( 'slug' => 'eightcap', 'name' => 'Eightcap', 'entity' => 'Eightcap EU Ltd', 'cysec' => '246/14', 'fca' => '921296', 'seychelles' => 'SD100', 'seychelles_note' => 'single-source; provisional', 'founded' => 2009, 'hq' => 'Melbourne, Australia', 'min_deposit_usd' => 100, 'min_deposit_display' => '$100', 'spread_eurusd' => 1, 'platforms' => array('MT4', 'MT5', 'TradingView'), 'other_reg' => array('ASIC', 'SCB'), 'other_reg_count' => 2, 'instruments' => '800+ across forex, indices, commodities, shares, crypto CFDs', 'account_types' => 'Standard (spreads from about 1.0 pip, no commission, $100 minimum deposit), Raw (spreads from roughly 0.06-0.20 pip plus about $3.50-per-side commission, i.e. around $7 round-turn), and a TradingView-integrated account. Islamic/swap-free accounts are available but reportedly only by contacting support directly, not as a self-service toggle.', 'execution_model' => 'Raw is ECN-style (liquidity-provider pricing passed through without markup); Standard is STP-style (cost built into the spread, no separate commission). Eightcap doesn\'t claim to be a classic client-to-client ECN -- it aggregates and routes orders to liquidity providers.', 'withdrawal_deposit_note' => 'No internal deposit or withdrawal fees reported across methods. Card, PayPal, Neteller and Skrill deposits are instant; bank wire takes 3-5 business days. Withdrawals go through a 1-2 business day security review, then take 1 day (UnionPay/Skrill) to 2-5 days (cards/wire).', 'overnight_financing' => 'Charged on positions open past midnight GMT+2; one aggregator describes its CFD financing/swap rates as "average for the industry," though no specific benchmark-plus-markup formula was found. An Islamic/swap-free account is available on request.', 'currency_conversion_fee' => 'Not specifically quantified in this research pass. Eightcap supports AUD, USD, GBP, EUR, NZD, CAD and SGD as account base currencies, which limits but doesn\'t eliminate conversion exposure outside those currencies.', 'inactivity_fee' => 'One independent source confirms an inactivity fee exists, but the exact amount and time threshold weren\'t confirmed in this research pass -- verify against Eightcap\'s current terms before relying on a specific figure.', 'customer_service_note' => 'Trustpilot rates it 4.0/5 from around 3,700 reviews, with praise for helpful, professional staff. One notable negative review describes funds being withheld for 4+ months despite completed verification.', 'mobile_note' => 'No numeric App Store or Google Play rating was found in this research pass.', 'education_note' => 'Won "Best Forex Educational Resources - Global" at the Global Forex Awards 2022. Independent reviewers describe beginner-level content as solid but advanced/in-depth education as limited compared to competitors; one aggregator rates its research 5.0/5.', 'blurb' => 'Newer to CySEC regulation than most peers here, with strong TradingView integration.', 'scores' => array( 'regulation' => 3.4, 'cost' => 4.58, 'platforms' => 3.4, 'track_record' => 2.14, 'overall' => 3.5 ), 'rank' => 15 ),
        array( 'slug' => 'fxpro', 'name' => 'FxPro', 'entity' => 'FxPro Financial Services Limited', 'cysec' => '078/07', 'fca' => '509956', 'seychelles' => 'SD120', 'founded' => 2006, 'hq' => 'Limassol, Cyprus', 'min_deposit_usd' => 100, 'min_deposit_display' => '$100', 'spread_eurusd' => 1.44, 'platforms' => array('MT4', 'MT5', 'cTrader'), 'other_reg' => array('FSCA', 'SCB'), 'other_reg_count' => 2, 'instruments' => 'Forex, shares, indices, commodities, metals, futures CFDs', 'account_types' => 'MT4/MT5 Standard (spreads from about 1.2 pips, commission-free), Raw+/cTrader (spreads from 0.0 pips plus roughly $3.50-per-side commission, i.e. about $7 round-turn), and FxPro Edge (a customizable, spread-betting-style product), with Islamic/swap-free available across platforms and a free demo account.', 'execution_model' => 'FxPro positions itself as No Dealing Desk (NDD) but publishes a page explicitly titled "Why FxPro is not an STP Broker," distancing itself from that specific label while using related technology -- an unusually candid distinction worth citing directly rather than summarizing as plain STP.', 'withdrawal_deposit_note' => 'No FxPro-side fee; third-party card processing may add roughly 1-3%. Minimum deposit and minimum withdrawal are both $100. Bank transfer takes about 1 business day to deposit and 1-3 days to withdraw; cards are instant to deposit with 1-2 day withdrawals; e-wallets are near-instant both ways.', 'overnight_financing' => 'Swap is charged daily at 21:59 UK time, with a triple charge on Wednesday for FX and metals (Friday for other instruments) to account for weekends. The rate is based on the tomorrow-next deposit rate differential between the two currencies plus FxPro\'s own additional rate. Islamic/swap-free accounts avoid this charge.', 'currency_conversion_fee' => 'FxPro states a live conversion rate is shown when transferring between its internal Wallet and an account of a different currency, but no specific markup percentage was found in this research pass.', 'inactivity_fee' => 'A one-off $15 account-maintenance fee plus $5/month, triggered after 6 months of account inactivity -- per an independent broker-fee comparison source.', 'customer_service_note' => 'Trustpilot rates it just 3/5 from 761 reviews -- notably lower than most peers researched so far. Reviews show real dissatisfaction specifically around customer service and payment-processing delays, alongside some praise for transparency and asset range.', 'mobile_note' => 'Reported around 4.5 on Google Play (500,000+ downloads) and about 4.7 on the App Store, though some recent complaints mention app-update issues affecting chart visibility and profit tracking.', 'education_note' => 'Offers beginner and advanced education sections plus a YouTube playlist; multilingual webinars are cited by one independent reviewer as a genuine advantage over peers, and its "FxPro Squawk" real-time news feed is noted as a particular strength for news-driven trading. One independent review site gives it a trust score of 93 ("Highly Trusted").', 'blurb' => 'One of the oldest CySEC licences on this list (issued 2007), reflecting a long operating history in Cyprus specifically.', 'scores' => array( 'regulation' => 3.4, 'cost' => 4.41, 'platforms' => 3.4, 'track_record' => 2.39, 'overall' => 3.5 ), 'rank' => 16 ),
        array( 'slug' => 'fp-markets', 'name' => 'FP Markets', 'entity' => 'First Prudential Markets Ltd', 'cysec' => '371/18', 'seychelles' => 'SD130', 'founded' => 2005, 'hq' => 'Sydney, Australia', 'min_deposit_usd' => 100, 'min_deposit_display' => '$100', 'spread_eurusd' => 1, 'platforms' => array('MT4', 'MT5', 'cTrader', 'TradingView'), 'other_reg' => array('ASIC', 'FSCA'), 'other_reg_count' => 2, 'instruments' => '10,000+ instruments across forex, indices, commodities and shares CFDs (plus direct Australian share trading via the third-party IRESS platform)', 'account_types' => 'Standard (commission-free, spreads from about 1.0 pip), Raw/RAW ECN (spreads from 0.0 pips plus roughly $3-per-side-per-100k commission, i.e. about $6 round-turn per standard lot), with Islamic swap-free available on both. A separate IRESS account (an Australian share-trading platform, $1,000 minimum deposit) and MAM/PAMM accounts also exist, though the IRESS product appears to be an Australia-entity offering and its availability under the EU entity reviewed here wasn\'t confirmed.', 'execution_model' => 'Described by independent comparison sites as ECN/STP ("A-book"), with liquidity-provider pricing streamed directly rather than through an internal dealing desk.', 'withdrawal_deposit_note' => 'No deposit fees; minimum deposit $100 (standard) or $1,000 for the IRESS product. Withdrawals: bank cards are free, international wire costs around AUD 10, Rapid Transfer around 1%, and e-wallets 1-2%. Processing typically takes 1-3 business days (wire 2-3 days; e-wallet/debit card within hours).', 'overnight_financing' => 'Swap applies on Standard, Raw and IRESS accounts; one independent reviewer describes its swap fees as "average for the industry" based on direct testing, though no specific benchmark-plus-markup formula was found. Islamic accounts avoid overnight interest but are charged a small administrative fee directly against the balance instead.', 'currency_conversion_fee' => 'A conversion fee may apply when the account\'s base currency differs from an instrument\'s quote currency; FP Markets offers accounts in ten currencies (including USD, GBP, EUR and AUD), and matching account currency to trading activity avoids the fee. No specific percentage was found.', 'inactivity_fee' => 'No inactivity fee on standard FX/CFD accounts, per an independent broker-fee comparison. The separate IRESS platform reportedly carries an AUD 55/month fee unless a minimum monthly commission or balance threshold is met -- likely an Australia-specific policy not confirmed for the EU entity.', 'customer_service_note' => 'Trustpilot rates it "Excellent," 4.9/5 from 9,000+ reviews (94% five-star), with independent commentary consistently praising staff professionalism and responsiveness. FP Markets advertises 24/7 support in 40+ languages via live chat, email and phone.', 'mobile_note' => 'Sources disagree sharply: the Apple App Store shows just 3.3/5 but from only 7 ratings (too small a sample to be meaningful), while one review site\'s own methodology scores its mobile apps 4/5, ranking it 18th of 63 brokers reviewed. A Google Play rating wasn\'t found. Present these as disagreeing data points rather than a single settled rating.', 'education_note' => 'Reviewed as comprehensive and improving: webinars, beginner and advanced videos, podcasts, articles, ebooks and tutorials, plus unlimited demo accounts with full live-account functionality. Research tools include free daily reports, market snapshots, a dividend calendar, and Autochartist. One review site\'s scorecard rates its research 5.0/5, education 4.5/5, and overall 4.6/5, while still noting room for improvement versus the very best brokers.', 'blurb' => 'Founded in Australia in 2005 by Matt Murphie, FP Markets is regulated by ASIC and South Africa\'s FSCA in addition to CySEC, and is one of the few brokers here offering cTrader and TradingView alongside MT4/MT5.', 'cysec_note' => 'FP Markets group also holds a Seychelles FSA licence and a Saint Lucia registration, both offshore and excluded here.', 'scores' => array( 'regulation' => 2.6, 'cost' => 4.58, 'platforms' => 4.2, 'track_record' => 2.47, 'overall' => 3.49 ), 'rank' => 17 ),
        array( 'slug' => 'hf-markets', 'name' => 'HF Markets', 'entity' => 'HF Markets (Europe) Ltd', 'cysec' => '183/12', 'seychelles' => 'SD015', 'founded' => 2010, 'hq' => 'Limassol, Cyprus', 'min_deposit_usd' => 5, 'min_deposit_display' => '$5 (Premium account); Pro account requires $100/€100', 'spread_eurusd' => 1.2, 'platforms' => array('MT4', 'MT5', 'Proprietary (HFM App)'), 'other_reg' => array('DFSA', 'FSCA'), 'other_reg_count' => 2, 'instruments' => '500+ CFDs across forex, metals, indices, stocks, bonds, energies, commodities and cryptocurrencies.', 'account_types' => 'Micro, Premium, and Zero Spread (also called Zero) in the EU/UK; Islamic/swap-free versions exist for Micro and Premium. Zero Spread is commission-based with near-zero spreads, Premium has no commission with tighter spreads, and Micro/Cent-style accounts allow very small lot sizes.', 'execution_model' => 'Described as no-dealing-desk, offering both STP and ECN-style execution depending on account (Zero Spread closer to ECN/STP, Premium/Micro closer to STP) -- not independently confirmed via a direct read of HF Markets\' own disclosures.', 'withdrawal_deposit_note' => 'No deposit or withdrawal fee charged by HF Markets itself (card networks/banks may apply their own, typically 1-3% for cards). Processing: cards around 10 minutes, Trustly around 2 business days, wire 2-7 business days. One source notes only the original deposit amount can be withdrawn back to a card, with profits required to go via wire transfer.', 'overnight_financing' => 'Standard swap applies on non-Islamic accounts (rate/methodology not independently confirmed). Swap-free accounts remove overnight interest, but HF Markets\' own terms reportedly list a replacement storage cost for select currency pairs held open past 7 days -- so "swap-free" isn\'t unconditionally free indefinitely.', 'currency_conversion_fee' => 'Not independently confirmed -- no specific fee or percentage was found.', 'inactivity_fee' => 'Sources disagree: the most detailed figure found is $5/month after 6-12 months of inactivity, rising to $10/month at 1-2 years and $20/month at 2-3 years; a separate source claims no inactivity fee at all. Verify directly against HF Markets\' current legal documents before relying on either claim.', 'customer_service_note' => 'Claims 24/7 support via phone, email and live chat. Trustpilot rates it around 4.5/5 from roughly 3,000 reviews, with HF Markets reportedly responding to 99% of negative reviews.', 'mobile_note' => 'Google Play rating around 4.0/5 from roughly 5,200 reviews, though this figure traces to a source dated 2023 and may be stale; the app reportedly has over 1 million downloads.', 'education_note' => 'Offers video courses, webinars, PDF guides, daily market commentary, recorded lessons and a podcast. Its demo account is reportedly unlimited and never expires, unusually generous versus competitors, and independent commentary frames education as a strength for beginners.', 'blurb' => 'HF Markets (HFM), formerly HotForex, was founded in 2010 in Cyprus and rebranded to HFM in 2022, with group entities separately licensed by the FCA, DFSA and FSCA.', 'cysec_note' => 'FCA held by HF Markets (UK) Ltd, DFSA by HF Markets (DIFC) Ltd, and FSCA by HF Markets SA (PTY) Ltd -- separate group entities from the CySEC-licensed HF Markets (Europe) Ltd.', 'fca' => '801701', 'scores' => array( 'regulation' => 3.4, 'cost' => 4.52, 'platforms' => 3.4, 'track_record' => 2.06, 'overall' => 3.47 ), 'rank' => 18 ),
        array( 'slug' => 'capital-com', 'name' => 'Capital.com', 'entity' => 'Capital Com SV Investments Ltd', 'cysec' => '319/17', 'fca' => '793714', 'founded' => 2016, 'hq' => 'Limassol, Cyprus', 'min_deposit_usd' => 20, 'min_deposit_display' => '$20', 'spread_eurusd' => 0.6, 'platforms' => array('Proprietary', 'MT4', 'TradingView'), 'other_reg' => array('ASIC', 'FSCA'), 'other_reg_count' => 2, 'instruments' => 'Forex, indices, commodities, shares, crypto CFDs', 'account_types' => 'Rather than separate execution-type accounts, Capital.com layers service/deposit tiers (Standard, Plus, Premier) onto one CFD account. It also offers a "1X CFD" no-leverage option (still carries market risk), an Islamic/swap-free account on request, and a Professional account with higher leverage for eligible clients. There\'s no separate ECN/raw-spread account.', 'execution_model' => 'Market maker, with spread-only pricing and no separate commission on most instruments.', 'withdrawal_deposit_note' => 'No Capital.com-side deposit or withdrawal fees (bank/processor fees may still apply). Card, Apple Pay and PayPal deposits are instant; PayID/bank transfer can take up to 24 business hours. Withdrawals are processed within 24 hours (91% within 5 minutes per Capital.com\'s own claim), though funds can take up to 5 business days to actually land. Minimum deposit $10 (cards/Apple Pay) or $50 (wire); minimum withdrawal $50.', 'overnight_financing' => 'Daily fee = Capital.com\'s own fee (reported around 4%/year, divided by 360 or 365) plus or minus the relevant benchmark rate (e.g. SOFR for USD, SONIA for GBP). A reported policy change now charges the administrative component only on net exposure rather than gross position, cutting overnight costs roughly in half for fully hedged portfolios. Islamic/swap-free accounts remove this charge.', 'currency_conversion_fee' => '0.7% of the spot forex rate for retail clients, 0.5% for professional clients -- per Capital.com\'s own published fees page.', 'inactivity_fee' => '$10/month (or base-currency equivalent) after 12 months of no activity, described by Capital.com as an administration/maintenance charge.', 'customer_service_note' => 'Trustpilot rates it around 4.6/5 ("Excellent") from roughly 13,000 reviews, with over 70% five-star; reviewers repeatedly describe support as helpful, patient and efficient. About 10% of ratings are one-star, with withdrawal delays and slow support the main complaint categories.', 'mobile_note' => 'Google Play rating around 4.5/5 from 60,000+ reviews and 5 million+ downloads. Capital.com runs three apps (its main trading app, the education-focused "Investmate," and MT4); reviewers praise smooth performance and integrated news/education.', 'education_note' => 'The Investmate app offers 30+ structured courses for beginners, integrated with the main app\'s news/education feed -- independent commentary treats this as a genuine differentiator versus a typical broker education page.', 'blurb' => 'Newer than most on this list but grew fast; low minimum deposit and commission-free pricing on most instruments.', 'scores' => array( 'regulation' => 3.4, 'cost' => 4.76, 'platforms' => 3.4, 'track_record' => 1.57, 'overall' => 3.44 ), 'rank' => 19 ),
        array( 'slug' => 'xm', 'name' => 'XM', 'entity' => 'Trading Point of Financial Instruments Ltd', 'cysec' => '120/10', 'fca' => null, 'fca_note' => 'FCA-licensed; firm reference number not independently confirmed.', 'seychelles' => 'SD010', 'seychelles_note' => 'XM also operates a second Seychelles-licensed entity, XM (SC) Limited, under licence SD190', 'founded' => 2009, 'hq' => 'Limassol, Cyprus', 'min_deposit_usd' => 5, 'min_deposit_display' => '$5', 'spread_eurusd' => 1.1, 'platforms' => array('MT4', 'MT5'), 'other_reg' => array('ASIC', 'DFSA'), 'other_reg_count' => 2, 'instruments' => '1,000+ across forex, stocks, indices, commodities, metals, crypto', 'account_types' => 'Micro (minimum $5, micro lots), Standard (standard lots), Ultra Low (available in Micro and Standard variants, spreads from 0.6 pips, zero commission), Zero (raw spreads from 0.0 pips plus commission), and Shares (direct share trading, per-share commission, no leverage). Islamic/swap-free versions are available across account types. One source cites an unusually high $10,000 minimum specifically for a "Shares" account variant, which wasn\'t cross-verified and conflicts with XM\'s typically low minimums elsewhere -- treat with caution.', 'execution_model' => 'More recent independent sources describe XM as operating a market-maker/dealing-desk model on most account types, with commission-free pricing built into the spread; older material describing it as no-dealing-desk appears to reflect outdated positioning rather than current practice.', 'withdrawal_deposit_note' => 'No XM-side deposit fees. Minimum deposit $5; minimum withdrawal $5 (with a possible exception on the Shares account noted above, unverified). Card withdrawals take 1-3 business days, wire 1-4 business days, Skrill within 1 business day, and other e-wallets often within about an hour.', 'overnight_financing' => 'Standard overnight swap is applied at daily rollover (reported at 17:00 New York time), with direction and size depending on the interest-rate differential between the two currencies in a pair. Islamic/swap-free accounts are available and don\'t charge the daily swap.', 'currency_conversion_fee' => 'Applied automatically when trading an instrument denominated in a currency different from the account\'s base currency, described only as a "variable markup spread" with no specific percentage found.', 'inactivity_fee' => 'A $15 one-off maintenance fee after 90 days of inactivity, followed by an ongoing $5/month fee if the account remains inactive thereafter.', 'customer_service_note' => 'Described as available 24 hours a day, 5 days a week via live chat, phone and email. Reviewer commentary found in this research pass was broadly positive, though a specific Trustpilot score or detailed complaint breakdown wasn\'t located.', 'mobile_note' => 'Apple App Store rating of 4.7/5 from 385 reviews; a Google Play rating wasn\'t found in this research pass.', 'education_note' => 'Widely cited for an extensive educational program aimed at beginner-to-intermediate traders, including daily live education sessions delivered through its app, alongside standard webinars and articles.', 'blurb' => 'One of the lowest minimum deposits on this list; large global client base and a long-running CySEC licence.', 'scores' => array( 'regulation' => 3.4, 'cost' => 4.56, 'platforms' => 2.6, 'track_record' => 2.14, 'overall' => 3.34 ), 'rank' => 22 ),
        array( 'slug' => 'markets-com', 'name' => 'Markets.com', 'entity' => 'Safecap Investments Ltd', 'cysec' => '092/08', 'founded' => 2008, 'hq' => 'Nicosia, Cyprus', 'min_deposit_usd' => 100, 'min_deposit_display' => '$100', 'spread_eurusd' => 1.3, 'platforms' => array('MT4', 'MT5'), 'other_reg' => array('FSCA', 'ASIC'), 'other_reg_count' => 2, 'instruments' => 'Forex, indices, commodities, shares and crypto CFDs (Safecap/Markets.com is part of Finalto, a Playtech-owned group).', 'account_types' => 'Retail and Professional accounts (both reportedly around $100 minimum deposit, with Professional offering higher leverage and lower margin requirements), plus a genuine Islamic/swap-free account. No dedicated ECN/raw-spread tier was found. Platforms are its proprietary Marketsx alongside MT4 and MT5.', 'execution_model' => 'Not clearly confirmed -- Markets.com is widely described as using spread-only pricing with no commission, consistent with a market-maker or STP structure, but no source explicitly classified it as one or the other.', 'withdrawal_deposit_note' => 'No deposit, withdrawal or commission fees were found; sources disagree on the minimum deposit ($100 vs. $250). Deposits over $2,500 reportedly have any external transaction fees reimbursed.', 'overnight_financing' => 'Only generic industry swap mechanics were found (interest-rate differential plus broker markup, with a Wednesday triple charge); no Markets.com-specific markup was disclosed. The Islamic account is confirmed swap-free.', 'currency_conversion_fee' => 'A 0.3% conversion fee applies when the account currency differs from the instrument\'s currency.', 'inactivity_fee' => '$10/month after 90 days of inactivity on a live account.', 'customer_service_note' => 'Phone, email and live chat, available 24/5 (not weekends); email responses can take up to 48 hours. Trustpilot shows mixed feedback from around 1,250 reviews -- praise for individual agents alongside complaints about slow responses.', 'mobile_note' => 'Reported around 3.2 on iOS versus a notably higher 4.5 on Android. Reviewers generally describe the app as a good transition from desktop, well-stocked with charting and risk-management tools.', 'education_note' => 'Offers webinars, beginner and advanced videos, a demo account via its proprietary platform, and copy trading. One independent review site rated its beginner/education offering below average.', 'blurb' => 'Markets.com is operated by Safecap Investments Ltd, part of Finalto (owned by Playtech, a FTSE-listed company), and Safecap itself holds both CySEC and South African FSCA licences directly, while its ASIC licence sits in a separate Finalto group entity.', 'cysec_note' => 'FSCA licence is held directly by Safecap Investments Ltd, the same CySEC entity. ASIC (via Finalto (Australia) Pty Ltd) is held by a separate group entity under the Finalto/Playtech umbrella, not by Safecap itself. Correction: this review previously also credited an FCA (UK) licence via Finalto Trading Ltd; a 2026 market-map of FCA-authorised forex/CFD brokers lists that UK entity under "Excluded or Transition" (not treated as a live FCA retail forex broker), so the FCA credit has been removed pending reconfirmation -- do not rely on FCA coverage for this broker without checking the FCA register directly.', 'scores' => array( 'regulation' => 2.6, 'cost' => 4.46, 'platforms' => 2.6, 'track_record' => 2.22, 'overall' => 3.08 ), 'rank' => 34 ),
        array( 'slug' => 'easymarkets', 'name' => 'easyMarkets', 'entity' => 'Easy Forex Trading Ltd', 'cysec' => '079/07', 'seychelles' => 'SD056', 'founded' => 2001, 'hq' => 'Limassol, Cyprus', 'min_deposit_usd' => 25, 'min_deposit_display' => '$25', 'spread_eurusd' => 1.8, 'platforms' => array('MT4', 'MT5', 'Proprietary (easyMarkets platform)'), 'other_reg' => array('ASIC', 'FSCA'), 'other_reg_count' => 2, 'instruments' => '300+ instruments across forex and CFDs', 'account_types' => 'Standard ($100 minimum, fixed spreads from 0.9 pips, free guaranteed stop-loss, no commission), Premium ($2,000 minimum, lower spreads plus a personal account manager), VIP ($10,000 minimum, lowest spreads plus a dedicated senior manager), and Islamic ($100 minimum, swap-free, fixed spreads, free guaranteed stop-loss).', 'execution_model' => 'One source describes easyMarkets as using a no-dealing-desk model, which is in tension with its broader reputation and fixed-spread product design (a hallmark of market-making) -- this discrepancy wasn\'t resolved with a second independent source, so verify directly against easyMarkets\' own execution disclosures before stating either model as fact.', 'withdrawal_deposit_note' => 'No deposit fees; card and e-wallet deposits are instant, wire transfers take 2-5 days. Withdrawal methods include card, wire, Bitcoin, Neteller, Skrill and Tether, typically processing in 1-2 business days (sometimes reported as long as 3-10 days). No minimum withdrawal for card/e-wallet methods; $50 minimum for bank withdrawals. Notably, withdrawals of $500 or more are reportedly subject to a 10% fee unless the account has met a trading-volume threshold (reportedly $200,000 in turnover per $500 withdrawn) -- a materially important, non-obvious condition worth knowing before withdrawing a larger amount.', 'overnight_financing' => 'Standard floating overnight swap applies to non-Islamic accounts (positive or negative depending on instrument; no rate/markup breakdown found). The Islamic account is explicitly swap-free, available from a $100 deposit, and retains fixed spreads and the free guaranteed stop-loss feature.', 'currency_conversion_fee' => 'Not independently confirmed -- no specific fee or percentage was found.', 'inactivity_fee' => 'Sources disagree: one states $25 per 6 months of dormancy, another (older) source cites $10/month (or the remaining balance if lower) after 90 days of no trading activity. These are materially different policies -- check easyMarkets\' current terms directly rather than relying on either figure.', 'customer_service_note' => 'Trustpilot rates it 4.2/5 from around 1,880 reviews. Reviewers frequently praise fast, friendly, helpful staff, and easyMarkets reportedly responds to all negative reviews, typically within 24 hours. Some negative reports describe slow account verification.', 'mobile_note' => 'One comparison source cites an iOS rating around 4.6/5 versus a notably lower 3.6/5 on Android, though this wasn\'t independently cross-checked against the live App Store/Play Store listings.', 'education_note' => 'easyMarkets Academy offers 9 structured lessons with 70+ videos and regular quizzes covering trading basics, technical and fundamental analysis. One independent reviewer calls the courses well-structured with interactive gamification but somewhat superficial in content -- good for onboarding beginners, thin for advanced traders. Its demo account uses $10,000 in virtual funds and, unusually, never expires.', 'blurb' => 'One of the longer-established Cyprus brokers (founded 2001 as Easy Forex), easyMarkets is known for proprietary risk-management tools such as dealCancellation and Freeze Rate built into its own platform rather than relying only on MT4/MT5.', 'cysec_note' => 'Also holds licences via other group entities from the Seychelles FSA and BVI FSC (both excluded as non-Tier-1).', 'scores' => array( 'regulation' => 2.6, 'cost' => 4.28, 'platforms' => 3.4, 'track_record' => 2.8, 'overall' => 3.3 ), 'rank' => 23 ),
        array( 'slug' => 'afterprime', 'name' => 'Afterprime', 'entity' => 'Claremont Square Capital Ltd', 'cysec' => '368/18', 'seychelles' => 'SD057', 'seychelles_note' => 'single-source; provisional', 'founded' => null, 'hq' => 'Sydney, Australia (group HQ, via Argamon Markets Pty Ltd); the CySEC entity, Claremont Square Capital Ltd (formerly Afterprime Europe Ltd), is registered in Nicosia (Lakatamia), Cyprus', 'min_deposit_usd' => 0, 'min_deposit_display' => 'No stated minimum (recommended ~$200)', 'spread_eurusd' => 0.9, 'platforms' => array('MT4', 'MT5', 'TraderEvolution'), 'other_reg' => array('ASIC'), 'other_reg_count' => 1, 'instruments' => 'Forex, metals, indices and commodities CFDs, traded on a 100% A-book/STP execution model', 'account_types' => 'Sources describe a single standard ECN-style account (raw spreads from 0.0 pips plus roughly $7 round-lot commission on FX), with an Islamic/swap-free option available on request. No separate professional or demo tier is documented on third-party sites. One lower-authority source reports Afterprime screens applicants and approves only 10-20% of sign-ups, favoring disciplined, longer-term traders -- unverified and worth treating with caution. Separately, one broker-tracking site flags an unverified, suspected clone claiming an Australian presence -- worth confirming you\'re dealing with the genuine CySEC entity before relying on anything beyond this review.', 'execution_model' => 'Described consistently across multiple reviews as 100% A-book/STP-ECN -- trades are hedged directly with liquidity providers, and the broker states it does not profit from client losses. No dealing-desk or market-maker model was found, and it\'s not confirmed whether execution differs by account tier.', 'withdrawal_deposit_note' => 'Minimum deposit reported as low as $1 on one comparison site, though this wasn\'t verified against Afterprime\'s own site directly. Reviews generally describe withdrawals as fast and hassle-free, though forum threads document specific withdrawal denials tied to the broker flagging arbitrage-style strategies as breaching liquidity-provider terms -- so experience appears mixed and strategy-dependent. Specific payment methods, fees, and processing times weren\'t found.', 'overnight_financing' => 'No Afterprime-specific swap rate or calculation table was found; Islamic/swap-free accounts are confirmed to avoid overnight swaps.', 'currency_conversion_fee' => 'Not found -- no specific fee or percentage was located.', 'inactivity_fee' => 'Not found -- no source stated a policy either way.', 'customer_service_note' => 'Trustpilot rates it around 4.5-4.6/5 from roughly 80-100 reviews, with largely positive sentiment describing quick responses (often within minutes) via live chat, email, and an active Discord community; the founders (a former Global Prime team) are cited as personally responsive. About a third of negative reviews get a company response.', 'mobile_note' => 'Not found -- no App Store or Google Play rating was located.', 'education_note' => 'No formal in-house courses or webinars were found. A July 2026 partnership with FX Dealer Academy runs a monthly competition awarding a funded trading account, which is a promotional/community feature rather than structured education. A demo account wasn\'t confirmed either way.', 'blurb' => 'Founded by the same pair who built and sold Global Prime (Jeremy Kinstlinger and Elan Bension), and runs a 100% A-book model where every client trade is hedged externally with Tier-1 liquidity providers rather than taken on as principal risk.', 'scores' => array( 'regulation' => 1.8, 'cost' => 4.64, 'platforms' => 3.4, 'track_record' => null, 'overall' => 3.27 ), 'rank' => 24 ),
        array( 'slug' => 'ingot-brokers', 'name' => 'INGOT Brokers', 'entity' => 'Ingot Brokers Europe Ltd', 'cysec' => '462/25', 'seychelles' => 'SD117', 'founded' => 2006, 'hq' => 'Limassol, Cyprus', 'min_deposit_usd' => 100, 'min_deposit_display' => '$100', 'spread_eurusd' => null, 'platforms' => array('MT4', 'MT5'), 'other_reg' => array('ASIC', 'CMA'), 'other_reg_count' => 2, 'instruments' => null, 'account_types' => 'Prime (commission-based, lowest spreads), Professional (commission-free, slightly wider spreads), and ECN (raw spreads from 0.0 pips plus roughly $7 round-lot commission), plus demo and Islamic/swap-free accounts. Leverage reported up to 1:400 with 1,000+ CFD instruments on MT4/MT5.', 'execution_model' => 'Not independently confirmed for the Europe entity specifically -- sources found were generic broker-type explainers rather than INGOT-specific disclosures.', 'withdrawal_deposit_note' => 'Methods include bank card, bank wire, and PayPal; processing times range from about 15 minutes to 3 business days; minimum withdrawal $5; no withdrawal fee reported. Worth noting: INGOT\'s CySEC licence was only granted around November 2025 and, per one trade-press report, had yet to start operations as of that reporting -- EU-entity-specific terms may still be provisional.', 'overnight_financing' => 'Standard overnight swap rates apply per the broker\'s agreement; Islamic accounts are reported exempt. No specific calculation formula or rate table was found.', 'currency_conversion_fee' => 'A currency-conversion fee applies on deposits, withdrawals or transfers made in a currency other than the account\'s base currency, charged at the broker\'s prevailing exchange rate -- no specific percentage was found.', 'inactivity_fee' => 'Reported as none -- no inactivity fee, deposit fee, or withdrawal fee, per one independent comparison site.', 'customer_service_note' => 'Trustpilot rates it 3.8/5 from 53 reviews. Positive commentary highlights localized support and training, particularly in Kenya and Bangladesh with in-person offices; recurring complaints include withdrawal delays (sometimes over a week) and spread widening during low-liquidity Asian-session hours.', 'mobile_note' => 'One aggregator cites 4.8/5 on iOS and 4.6/5 on Android, but this wasn\'t independently cross-verified against the live App Store/Google Play listings and may reflect generic MT4/MT5 app ratings rather than an INGOT-specific app -- treat as low-confidence.', 'education_note' => 'Assessed by one independent reviewer as a weak point, with educational resources and market research trailing most competitors -- limited to a blog, market news, and a corporate-events calendar. This is in some tension with the customer-service finding above mentioning free monthly training sessions in certain regions; sources aren\'t fully consistent on this point.', 'blurb' => 'Ingot Brokers Europe Ltd is a newly licensed CySEC entity (licence granted ~Nov 2025) of the wider INGOT group, which is also regulated by ASIC in Australia and the CMA in Kenya.', 'cysec_note' => 'ASIC and CMA licences are held by other entities within the wider INGOT group, not confirmed to be held directly by the CySEC entity, which as of late 2025 had obtained its CySEC licence but reportedly had not yet begun operations under it.', 'scores' => array( 'regulation' => 2.6, 'cost' => 4.96, 'platforms' => 2.6, 'track_record' => 2.39, 'overall' => 3.27 ), 'rank' => 25 ),
        array( 'slug' => 'go-markets', 'name' => 'GO Markets', 'entity' => 'Go Markets Ltd', 'cysec' => '322/17', 'seychelles' => 'SD043', 'founded' => 2006, 'hq' => 'Melbourne, Australia (group HQ); Go Markets Ltd, the CySEC entity, is Cyprus-based', 'min_deposit_usd' => 100, 'min_deposit_display' => '$100', 'spread_eurusd' => 1, 'platforms' => array('MT4', 'MT5', 'cTrader', 'TradingView'), 'other_reg' => array('ASIC'), 'other_reg_count' => 1, 'instruments' => 'Forex plus CFDs on indices, commodities and shares', 'account_types' => 'Standard (commission-free, spreads from 0.8 pips, up to 30:1 leverage for retail), GO Plus+ (spreads from 0.0 pips, around $3-per-side-per-lot commission, aimed at higher-volume/EA traders), Micro (leverage up to 500:1 for eligible clients, no commission, $10 minimum deposit), and GO Professional (by application, for eligible/sophisticated clients, higher leverage), with Islamic/swap-free available on account types.', 'execution_model' => 'Described in independent commentary as an ECN/STP broker, with orders routed to liquidity providers rather than through a stated dealing-desk model; it\'s not confirmed whether execution differs explicitly by account tier beyond the spread/commission structure.', 'withdrawal_deposit_note' => 'No deposit or withdrawal fee from GO Markets itself (third-party/bank fees may apply). Methods include bank transfer, cards, Skrill, Neteller, PayPal, BPAY and USDT. Withdrawals are typically processed within 24 hours (same-day if requested before 1pm AEST), though the first withdrawal may take up to 3 business days. No stated minimum withdrawal.', 'overnight_financing' => 'Standard accounts pay or receive swap. Islamic/swap-free accounts get an 11-day grace period, after which daily admin fees apply by instrument: reportedly $8/lot for indices, $10/lot for crypto, $15/lot for spot Brent/WTI, $40/lot for FX and metals, and $50/lot for BTC -- per GO Markets\' own published Islamic-account page.', 'currency_conversion_fee' => 'GO Markets offers several base currencies (USD, EUR, GBP, AUD, CAD, NZD, CHF, BTC); a conversion fee applies when the deposit currency differs from the account currency, but the exact percentage wasn\'t found on GO Markets\' own page in this research pass.', 'inactivity_fee' => 'Reported as none by multiple aggregator sources, though this wasn\'t independently confirmed on GO Markets\' own fee page directly.', 'customer_service_note' => '24/5 support, marketed with several industry awards (which are vendor/trade-publication recognitions, not independent user-satisfaction surveys). Trustpilot shows roughly 4.5-4.6/5, though the review count cited varies (162-709) across different snapshots.', 'mobile_note' => 'Reported around 4.6 on Android and about 4 on iOS per one aggregator, not independently verified directly against the live App Store/Play Store listings.', 'education_note' => 'Offers a trading handbook, MT4 video tutorials, tiered courses, webinars, and a demo account (limited to one month unless a live account is also opened, which removes the limit and adds TradingView access). Research tools include Trading Central, Autochartist and a proprietary "A-QUANT" AI signal tool; one independent review describes the research tools as relatively basic compared to larger competitors.', 'blurb' => 'GO Markets was founded in 2006 in Melbourne under ASIC regulation before adding a CySEC-licensed EU entity, and it offers a commission-free Standard account (spreads from ~1.0 pip) alongside a raw-spread \'GO Plus+\' ECN account.', 'scores' => array( 'regulation' => 1.8, 'cost' => 4.58, 'platforms' => 4.2, 'track_record' => 2.39, 'overall' => 3.23 ), 'rank' => 26 ),
        array( 'slug' => 'etoro', 'name' => 'eToro', 'entity' => 'eToro (Europe) Ltd', 'cysec' => '109/10', 'fca' => '583263', 'seychelles' => 'SD076', 'founded' => 2007, 'hq' => 'Tel Aviv / Limassol', 'min_deposit_usd' => 50, 'min_deposit_display' => '$50', 'spread_eurusd' => 1, 'platforms' => array('Proprietary (CopyTrader)'), 'other_reg' => array('ASIC', 'FSAS'), 'other_reg_count' => 2, 'instruments' => '5,000+ across forex, stocks, ETFs, commodities, indices, 100+ crypto', 'account_types' => 'Retail, Professional (EEA clients can opt up post-ESMA for higher leverage), Corporate, and an Islamic/swap-free account restricted to residents of several Middle Eastern and North African countries, reportedly requiring a $1,000 minimum deposit.', 'execution_model' => 'Uses spread-based pricing with no flat commission on most CFDs; the underlying execution classification (market maker vs. STP) wasn\'t explicitly disclosed in sources found.', 'withdrawal_deposit_note' => 'A flat $5 withdrawal fee applies on USD accounts (not reported for GBP/EUR external accounts); minimum withdrawal $30 on a USD account. Deposit methods include bank transfer, debit/credit card, PayPal, Skrill and Neteller. Deposits typically process instantly to within 3 days (wire 2-3 days); withdrawals vary by method, up to 5 business days for cards/bank transfer and about 2 days for e-wallets.', 'overnight_financing' => 'Standard accounts are charged per-instrument overnight fees (exact methodology wasn\'t fully detailed in sources found beyond "daily, based on instrument"). The Islamic/swap-free account has a 7-day grace period with zero interest, after which a daily administrative fee (which eToro states is not interest, for Sharia compliance) applies per instrument to positions held past 22:00 GMT.', 'currency_conversion_fee' => 'On GBP/EUR accounts, a deposit conversion cost of roughly 150 pips is cited, alongside a conversion fee of about 0.75% on trades/transfers from GBP/EUR to USD; withdrawal/deposit conversion fees of 1.5-3.0% are also cited depending on currency and payment method -- sources broadly agree on the general range but the exact figure depends on the specific currency pair and method.', 'inactivity_fee' => '$10/month charged if there\'s no login for 12 months.', 'customer_service_note' => 'Independent ratings are mixed -- G2 rates it 3.6/5 (26 reviews) and Capterra 4.3/5 (20 reviews), with recurring complaints about difficulty reaching support, slow or unresolved issues, and long withdrawal timeframes.', 'mobile_note' => 'iOS App Store rating around 4.4/5 from about 9,300 reviews; an Android rating wasn\'t found. Independent reviewers cite the CopyTrader social feed and beginner-friendly interface as strengths, alongside some reports of technical glitches and slow loading.', 'education_note' => 'eToro Academy provides articles, videos, investment courses, podcasts and webinars, alongside a $100,000 virtual-fund demo account usable with CopyTrader to test strategies risk-free. One independent review site calls it "Highly Trusted" and notes it\'s strong for beginner education.', 'blurb' => 'Best known for social/copy trading. No MT4/MT5 -- everything happens on eToro\'s own platform.', 'scores' => array( 'regulation' => 3.4, 'cost' => 4.59, 'platforms' => 1.8, 'track_record' => 2.31, 'overall' => 3.22 ), 'rank' => 27 ),
        array( 'slug' => 'xs-markets', 'name' => 'XS Markets', 'entity' => 'XS Markets Ltd', 'cysec' => '412/22', 'seychelles' => 'SD089', 'founded' => 2010, 'hq' => null, 'min_deposit_usd' => 0, 'min_deposit_display' => 'No minimum', 'spread_eurusd' => null, 'platforms' => array('MT4', 'MT5'), 'other_reg' => array('ASIC', 'FSCA'), 'other_reg_count' => 2, 'instruments' => null, 'account_types' => 'Standard (commission-free, spreads from 0.7 pips, $200 minimum deposit) and Raw (spreads from 0 pips, around $6 commission per round lot, $500 minimum deposit); an Islamic/swap-free variant is available only on the Standard profile, restricted to Muslim clients.', 'execution_model' => 'One independent review describes XS as offering STP or ECN execution on its CFD range, without clearly differentiating by account type in sources found.', 'withdrawal_deposit_note' => 'No internal XS fee for deposits or withdrawals under normal use, but XS\'s own funding-methods page states it reserves the right to apply a withdrawal fee of up to 3% in cases of no trading activity or suspected abuse -- functioning more like a dormant-withdrawal penalty than a classic inactivity fee. Deposit minimums/times: bank transfer $300 (1-7 days), cards $20 (instant), Skrill/Neteller $15 (instant). Withdrawal minimums/times: bank transfer $250 (1-7 days), cards $5 (7-10 days), Skrill $50 (1 day), Neteller $15 (instant).', 'overnight_financing' => 'Calculated on the interest-rate differential between a pair\'s two currencies, applied at a daily cutoff around 5pm EST; the broker\'s markup over that rate wasn\'t disclosed in sources found. The Islamic account on the Standard profile is swap-free, with no further fee structure found.', 'currency_conversion_fee' => 'XS doesn\'t charge its own conversion fee, but third-party payment providers or banks may apply conversion/network fees; account funding currencies are limited to EUR, USD and GBP.', 'inactivity_fee' => 'General aggregator sources claim no inactivity fee, but this is in tension with XS\'s own withdrawal-fee clause above for dormant/no-activity accounts -- treat the "no inactivity fee" claim as not fully confirmed given that conflict.', 'customer_service_note' => 'Trustpilot TrustScore around 4/5; a separate review aggregator rates it 4.8/5 (38 reviews). Independent comments praise quick live-chat responses and professionalism.', 'mobile_note' => 'No specific App Store or Google Play star rating was found in this research pass.', 'education_note' => 'One reviewer explicitly flagged a "lack of additional tools and educational resources" as a drawback, describing the educational support as somewhat poor -- independent sentiment on this item is mixed-to-negative, unlike most peers researched so far.', 'blurb' => 'XS Markets Ltd is the CySEC-regulated Cyprus entity of the globally rebranded XS.com group (formerly XSMarkets, founded 2010), which also operates ASIC-licensed and FSCA-licensed entities alongside several smaller offshore ones that don\'t count as Tier-1.', 'scores' => array( 'regulation' => 2.6, 'cost' => 5, 'platforms' => 2.6, 'track_record' => 2.06, 'overall' => 3.21 ), 'rank' => 28 ),
        array( 'slug' => 'atfx', 'name' => 'ATFX', 'entity' => 'ATFX Global Markets (Cy) Ltd', 'cysec' => '285/15', 'fca' => null, 'fca_note' => 'FCA-licensed; firm reference number not independently confirmed.', 'seychelles' => 'SD093', 'seychelles_note' => 'single-source; provisional', 'founded' => 2017, 'hq' => 'Limassol, Cyprus (Cyprus entity); wider ATFX group headquartered in London, UK', 'min_deposit_usd' => 200, 'min_deposit_display' => '$200 (Standard account)', 'spread_eurusd' => 1.2, 'platforms' => array('MT4', 'MT5'), 'other_reg' => array('ASIC', 'FSCA'), 'other_reg_count' => 2, 'instruments' => '350+ CFDs across forex, indices, shares, commodities and cryptocurrencies', 'account_types' => 'Standard (no commission, floating spreads reported from roughly 0.2-1.8 pips depending on source) and ECN/Raw (spreads from about 0.15 pips on EUR/USD, around $3.50/lot commission). Minimum deposit figures conflict across sources ($500, $5,000, and region-specific figures have all been cited) -- treat as unconfirmed and likely region-dependent. Islamic/swap-free accounts are available per general industry description, though ATFX-specific terms weren\'t found.', 'execution_model' => 'Independent sources describe ATFX as operating both STP and ECN execution models, with the ECN tier offering direct market access with no markup.', 'withdrawal_deposit_note' => 'No fee for bank transfer, card or e-wallet deposits (non-UK cards may occasionally be charged a fee, refundable on proof). Deposits credit within about 30 minutes (card/e-wallet) or 1 business day (bank transfer). Fee-free withdrawal above a threshold of roughly €/$/£100 (or the full balance if lower); below that, a €/$/£5 fee applies. Processing generally takes 1-3 days.', 'overnight_financing' => 'General swap mechanics (interest-rate differential plus broker markup) are described industry-wide, but ATFX\'s specific markup or calculation wasn\'t found. Islamic account swap-free terms weren\'t found either.', 'currency_conversion_fee' => 'Not independently confirmed -- no ATFX-specific conversion fee or rate was found; multiple base currencies (AUD, USD, EUR, GBP) are offered, which can reduce conversion exposure.', 'inactivity_fee' => 'Not found -- no ATFX-specific inactivity-fee figure was located in this research pass.', 'customer_service_note' => 'One review aggregator gives it an overall score of 4.3, with customer support rated 4.6 and education a perfect 5.0; 24/5 multilingual support is offered via email, phone, WhatsApp and live chat, with independent commentary describing staff as friendly, helpful and professional.', 'mobile_note' => 'Figures conflict: its "AT GO" app shows 5.0/5 on the Apple App Store but from only 2 ratings (not a statistically meaningful sample), while a separate source cites 3.5 stars, possibly for an older/general ATFX app rather than AT GO specifically -- recheck against the live store listing before relying on either figure.', 'education_note' => 'Noted as a strength in independent reviews, covering trading fundamentals, strategies, risk management and market insights; one source rated its education 5.0/5 and research 4.7/5.', 'blurb' => 'Backed by a multi-entity global group holding FCA, ASIC and FSCA licences in addition to its Cyprus CIF licence.', 'scores' => array( 'regulation' => 3.4, 'cost' => 4.48, 'platforms' => 2.6, 'track_record' => 1.49, 'overall' => 3.18 ), 'rank' => 29 ),
        array( 'slug' => 'swissquote', 'name' => 'Swissquote', 'entity' => 'Swissquote Capital Markets Limited', 'cysec' => '422/22', 'founded' => 1996, 'hq' => 'Limassol, Cyprus (Cyprus entity); parent Swissquote Group headquartered in Gland, Switzerland', 'min_deposit_usd' => 1000, 'min_deposit_display' => '$1,000 (varies $1,000-$10,000 by account tier)', 'spread_eurusd' => 1.3, 'platforms' => array('MT4', 'MT5', 'Proprietary (Advanced Trader)'), 'other_reg' => array(), 'other_reg_count' => 0, 'instruments' => '80+ forex pairs and roughly 400-500 CFDs on indices, commodities, bonds and shares via the CySEC/EU entity; the wider Swissquote Bank platform (a different regulated entity) offers a much larger universe of stocks, ETFs, funds, options and bonds for investing.', 'account_types' => 'Standard (minimum reported around $1,000/CHF 1,000, spreads from about 1.4 pips), Premium (minimum around CHF 10,000, spreads from about 1.1 pips), and Prime (minimum around CHF 50,000, spreads from about 0.1 pips), plus an Islamic/swap-free option on Standard and Premium (commission-free, no overnight interest on trades held over 24 hours). One source cites a much lower $100 minimum for a "Standard" account, which conflicts with the CHF 1,000 figure elsewhere -- likely reflecting different legal entities or jurisdictions, so treat the minimum deposit as entity-dependent and not fully confirmed.', 'execution_model' => 'Swissquote describes its own model as a proprietary agency/principal execution model -- not a simple pure-ECN or pure-market-maker label, so this should be stated as Swissquote\'s own description rather than an independently verified classification.', 'withdrawal_deposit_note' => 'Deposits are reported fee-free and typically instant; withdrawals are reported to take 1-3 business days depending on method (bank transfer slower), with some bank/card withdrawal methods possibly carrying fees not itemized in sources found. Methods include cards, bank transfer, PayPal and Skrill; no minimum withdrawal figure was found.', 'overnight_financing' => 'One example cited: holding one standard lot of EUR/USD costs about $5.88/night on a buy position and credits about $2.41/night on a sell -- described by independent commentary as average-to-high versus the industry. For options and futures, an overnight funding fee (reported around 1.5% for major currencies) applies only when available cash in that currency is below the required margin.', 'currency_conversion_fee' => 'A fee is confirmed to exist, but the exact percentage wasn\'t retrievable from the sources found in this research pass -- needs a direct check of Swissquote\'s own fee page.', 'inactivity_fee' => 'Charged if there\'s no open position or trading activity for 6+ months: up to 10 units of the account\'s base currency (or the remaining balance if lower), deducted monthly until trading resumes, the account closes, or the balance reaches zero. Separately, a quarterly custody fee applies based on assets held, ranging from about 20 CHF/quarter below CHF 50,000 up to 50 CHF/quarter above CHF 150,000, with an additional 0.03%/year on assets above CHF 1 million -- confirmed via Swissquote\'s own published pricing page.', 'customer_service_note' => 'One review site cites a support rating of 4.8/5, with general sentiment around 4.5/5 and particular praise for trust and safety -- consistent with Swissquote\'s dual status as a bank and a broker.', 'mobile_note' => 'Reported around 4.5 on iOS versus a notably lower 3.4 on Android. One independent review site separately ranks its mobile apps 4.5/5, placing it 12th of 63 brokers reviewed for that category.', 'education_note' => 'Its Education Center includes 2 video courses (31 videos, about 2 hours total), 16 eBooks, live webinars, the Autochartist technical-analysis tool, Dow Jones real-time news, "Market Talk" videos, and TradingView-powered advanced charting -- reviewed as a strong point, with one source specifically praising its research and education as outstanding.', 'blurb' => 'Swissquote is the CFD/forex arm of Swissquote Group, a Swiss stock-exchange-listed (SIX: SQN) online bank founded in 1996 and regulated by FINMA in Switzerland, with its EU retail CFD business run through the CySEC-licensed Swissquote Capital Markets Limited in Cyprus.', 'cysec_note' => 'FCA licence is held by a separate group entity, Swissquote Ltd (UK), not by Swissquote Capital Markets Ltd (Cyprus). The Swissquote Group\'s Swiss parent, Swissquote Bank Ltd, is regulated by FINMA (Switzerland) -- a Tier-1 banking regulator not on the standard list, noted here since it applies to the parent bank, not the CySEC CFD entity.', 'fca' => '562170', 'scores' => array( 'regulation' => 1.8, 'cost' => 4.29, 'platforms' => 3.4, 'track_record' => 3.2, 'overall' => 3.15 ), 'rank' => 30 ),
        array( 'slug' => 'topfx', 'name' => 'TopFX', 'entity' => 'Topfx Ltd', 'cysec' => '138/11', 'fca' => null, 'fca_note' => 'FCA-licensed; firm reference number not independently confirmed.', 'seychelles' => 'SD037', 'founded' => 2010, 'hq' => 'Limassol, Cyprus', 'min_deposit_usd' => 0, 'min_deposit_display' => 'No minimum', 'spread_eurusd' => null, 'platforms' => array('MT4', 'MT5', 'cTrader'), 'other_reg' => array(), 'other_reg_count' => 0, 'instruments' => '600+ instruments across forex and CFDs', 'account_types' => 'Only a "Zero" account (tight spreads, around €5.50 round-turn commission) was confirmed in sources found; a possible standard/spread-only tier is referenced in some generic listings but wasn\'t independently confirmed for TopFX specifically. Islamic/swap-free account availability wasn\'t directly confirmed either -- treat as not found.', 'execution_model' => 'Described as direct-market-access with no dealing-desk intervention, consistent with TopFX\'s institutional/prime-brokerage origins (built initially as an institutional liquidity provider before expanding into retail).', 'withdrawal_deposit_note' => 'Minimum deposit $50; no TopFX-charged deposit fees (third-party card fees of roughly 1-3% may apply). Deposits are instant except SEPA/wire (3-5 days). Minimum withdrawal $100; the first and second withdrawals are reported free, and bank-wire withdrawals above $100/€100 are free, with a flat $10/€10 fee below that threshold.', 'overnight_financing' => 'Not independently confirmed -- no TopFX-specific swap calculation or Islamic swap-free terms were found in this research pass.', 'currency_conversion_fee' => 'TopFX offers multiple base account currencies to reduce conversion need, but no specific conversion-fee percentage was found.', 'inactivity_fee' => 'Not found -- no TopFX-specific figure was located.', 'customer_service_note' => 'One review site rates it 4.3/5 overall (support 4.2/5); another rates it 3.5/5 overall. Independent commentary describes live-chat replies arriving within minutes and email replies within 24 hours, calling support first-class.', 'mobile_note' => 'One review site rates mobile apps around 4/5 industry-wide but ranks TopFX low within that comparison (52nd of 63 brokers reviewed) -- its platforms are MT4 and cTrader rather than a proprietary app.', 'education_note' => 'Reviewed as a clear weak point -- described as severely limited and limiting for beginners compared to category leaders, despite providing in-house market analysis, Autochartist and Trading Central.', 'blurb' => 'TopFX is a CySEC- and FCA-regulated ECN broker based in Limassol with no stated minimum deposit and raw/ECN pricing (commission-based) rather than a traditional marked-up standard account.', 'scores' => array( 'regulation' => 1.8, 'cost' => 5, 'platforms' => 3.4, 'track_record' => 2.06, 'overall' => 3.13 ), 'rank' => 31 ),
        array( 'slug' => 'xtb', 'name' => 'XTB', 'entity' => 'XTB Limited', 'cysec' => '169/12', 'fca' => '522157', 'seychelles' => 'SD148', 'seychelles_note' => 'single-source; provisional', 'founded' => 2002, 'hq' => 'Warsaw, Poland', 'min_deposit_usd' => 0, 'min_deposit_display' => '$0', 'spread_eurusd' => 0.7, 'platforms' => array('xStation 5 (proprietary)'), 'other_reg' => array('KNF (Poland)'), 'other_reg_count' => 1, 'instruments' => '11,300+ across forex, indices, commodities, stocks, ETFs, crypto CFDs', 'account_types' => 'Standard (floating spreads from about 0.5 pips, no commission) and Pro (market execution, commission charged, spreads from about 0.1 pip), plus an Islamic/swap-free account offered via XTB International, limited to residents of a specified list of Middle Eastern, North African and Southeast Asian countries.', 'execution_model' => 'Standard uses floating-spread, market-maker-style pricing; Pro uses market execution with a commission, closer to STP/raw pricing -- so execution genuinely varies by account type, per XTB\'s own descriptions.', 'withdrawal_deposit_note' => 'No deposit fee and no stated minimum deposit (card or bank transfer). Fee-free withdrawal thresholds vary by legal entity: the UK entity is free above £50/€50/$50 (same-day if requested before 1pm GMT), the Cyprus entity is free above €100 (with a €10 fee below that, processed the next business day), and the international entity is free above $50 (1 business day processing). Methods include bank card, bank wire, Bitcoin, Neteller, Skrill and Tether.', 'overnight_financing' => 'Daily swap points are credited or debited at midnight for CFD positions held overnight; the exact markup over the benchmark rate wasn\'t disclosed in sources found.', 'currency_conversion_fee' => '0.5% of transfer value for transfers between investment accounts in different currencies (0.8% on weekends/holidays); a 0.5% margin is also applied to XTB\'s own exchange rate for currency conversions arising from trade opening/closing and corporate actions -- confirmed via XTB\'s own published fees-and-commissions page, one of the more specifically sourced figures in this research pass.', 'inactivity_fee' => '€10/month (or the GBP/USD equivalent), applied only if there\'s been no position opened or closed in 365 days AND no deposit made in 90 days -- confirmed via XTB\'s own published fees page.', 'customer_service_note' => 'One review site rates its support 4.6/5, citing 24/5 availability and a dedicated account manager. Another gives it a trust score of 96/99 and an overall rating of 5/5.', 'mobile_note' => 'App Store rating around 4.5/5 (3,300+ reviews); Google Play around 4.5/5 (132,000+ reviews) -- among the highest-volume, most consistent ratings found across this research set.', 'education_note' => 'One review site gives its education a perfect 5.0/5 and another rates it 4.5/5, with beginner and advanced video content both cited as comprehensive.', 'blurb' => 'Publicly listed on the Warsaw Stock Exchange. No minimum deposit, no MT4/MT5 -- everything runs on its own xStation 5 platform.', 'scores' => array( 'regulation' => 2.6, 'cost' => 4.72, 'platforms' => 1.8, 'track_record' => 2.71, 'overall' => 3.1 ), 'rank' => 32 ),
        array( 'slug' => 'fortrade', 'name' => 'Fortrade', 'entity' => 'Fortrade Cyprus Ltd', 'cysec' => '385/20', 'fca' => '609970', 'founded' => 2013, 'hq' => 'London, UK', 'min_deposit_usd' => 100, 'min_deposit_display' => '$100', 'spread_eurusd' => 2.5, 'platforms' => array('MT4', 'Proprietary (Fortrader)'), 'other_reg' => array('ASIC', 'CIRO'), 'other_reg_count' => 2, 'instruments' => '300+ instruments including about 60 forex pairs, 15 cryptocurrencies and 150 stock CFDs', 'account_types' => 'One independent review explicitly notes Fortrade offers only a single live account type (a Real Trading Account) plus a demo account; an Islamic/swap-free variant can reportedly be arranged by emailing support after standard registration, rather than as a self-service separate tier.', 'execution_model' => 'Fortrade runs its own proprietary platform ("Fortrader") alongside MT4, but sources found don\'t explicitly classify it as market maker, STP or ECN -- treat its execution model as not independently confirmed rather than inferring one from its single-account, proprietary-platform structure.', 'withdrawal_deposit_note' => 'No Fortrade deposit fee; minimum deposit $100. Methods include Visa/Mastercard, bank wire, Skrill, Neteller and Bitcoin. Processing: cards instant to 2 days, wire 1-5 days, e-wallets instant to 1 day, Bitcoin 10 minutes to 1 hour. Withdrawals follow a strict back-to-source policy (funds returned to the original deposit method up to the deposited amount); any bank withdrawal fees are passed to the customer, cited at around $40, with full processing taking up to 5 business days.', 'overnight_financing' => 'No commission is charged on trades; swap/financing fees apply by asset class (day-to-day calculation not detailed beyond asset-class examples). On the Islamic/swap-free account, rollover interest is replaced by markup charges -- for example, weekly rates on stocks/ETFs, and other instrument classes charged at a reported 7x the regular daily swap on the Wednesday-to-Thursday rollover (the standard triple-swap day), pro-rated for positions opened or closed within that window.', 'currency_conversion_fee' => 'Not found -- no Fortrade-specific conversion fee or percentage was located.', 'inactivity_fee' => 'A $10/month administrative fee, triggered after a grace period of 6 consecutive months (one source instead cites 365 days) with no transactions, recurring monthly thereafter.', 'customer_service_note' => 'Trustpilot sentiment is mixed -- praise for transparency and support sits alongside complaints about aggressive sales-call pressure, a recurring theme in reviews specifically about Fortrade.', 'mobile_note' => 'One ranking aggregator cites around 3.5 on iOS and 4.2 on Android, with Fortrade ranked comparatively low (77th) among CFD brokers reviewed in that same source -- treat as an approximate, single-source figure.', 'education_note' => 'Described as a genuine strength, including an integrated trading academy and demo account, alongside FCA/CySEC regulation and MT4 availability; the same reviews note slower withdrawals, wider-than-average spreads on some assets, and the single account type as drawbacks.', 'blurb' => 'Fortrade is regulated across four jurisdictions (CySEC, FCA, ASIC and CIRO) and offers its own proprietary Fortrader platform in addition to MT4.', 'scores' => array( 'regulation' => 3.4, 'cost' => 3.98, 'platforms' => 2.6, 'track_record' => 1.82, 'overall' => 3.1 ), 'rank' => 33 ),
        array( 'slug' => 'ic-markets', 'name' => 'IC Markets', 'entity' => 'IC Markets (EU) Ltd', 'cysec' => '362/18', 'seychelles' => 'SD018', 'founded' => 2007, 'hq' => 'Sydney, Australia', 'min_deposit_usd' => 200, 'min_deposit_display' => '$200', 'spread_eurusd' => 0.8, 'platforms' => array('MT4', 'MT5', 'cTrader'), 'other_reg' => array('ASIC'), 'other_reg_count' => 1, 'instruments' => 'Forex, metals, stocks, commodities, futures, crypto, indices', 'account_types' => 'Standard and Raw Spread accounts (minimum deposit $200 across both), both available with an Islamic/swap-free add-on, across MT4, MT5 and cTrader. Raw Spread offers spreads from 0.0 pips plus roughly $3.50-per-lot commission; Standard has no commission but wider spreads.', 'execution_model' => 'IC Markets describes itself as "True ECN," no-dealing-desk, naming several major banks as liquidity providers. One source notes it doesn\'t always offset every position directly with liquidity providers, implying a possible partial B-book element alongside its ECN model.', 'withdrawal_deposit_note' => 'No deposit or withdrawal fees charged by IC Markets itself (third-party bank fees may apply). Methods include bank wire, cards, e-wallets (PayPal, Skrill, Neteller) and crypto. Minimum deposit $200; a specific minimum withdrawal figure wasn\'t found.', 'overnight_financing' => 'Standard and Raw Spread accounts use the standard interest-differential swap. Islamic/swap-free accounts avoid swap but are charged a flat per-lot holding fee on overnight positions instead -- reportedly ranging from around $2/lot on lower-volatility pairs up to roughly $20/lot on higher-volatility pairs, per IC Markets\' own Islamic-account page, though the exact scope wasn\'t fully consistent in the source found and is worth confirming directly.', 'currency_conversion_fee' => 'Not found -- no specific fee or percentage was located.', 'inactivity_fee' => 'Disputed: IC Markets\' EU entity publishes a formal Inactivity Fees Policy defining an inactive account as one with no executed trade for 6 continuous months, but multiple independent comparison sites claim no inactivity fee is actually charged. This is a real conflict between a published policy document and third-party reporting -- the exact fee amount, if any, wasn\'t found.', 'customer_service_note' => 'Trustpilot ratings for the EU entity are strong but vary by regional mirror (reported between about 3.7 and 4.9 out of 5, with review counts also differing by source). Praise focuses on responsiveness and professionalism; some complaints mention difficulty reaching live agents and slow email replies.', 'mobile_note' => 'Its main MT4/MT5 apps show around 4.2 on Android and a notably lower 3.1 on iOS; a separate cTrader-branded app is rated much higher, around 4.8 (though from a small review count). Reviewers single out raw pricing and fast execution as standout features.', 'education_note' => 'Offers demo accounts, platform tutorials, videos and webinars. One independent review site scores its research category 5.0/5 and its overall rating 4.8, describing the offering as geared more to intermediate and advanced traders than beginners.', 'blurb' => 'Known for raw ECN-style pricing aimed at active and algorithmic traders; higher minimum deposit than most on this list.', 'scores' => array( 'regulation' => 1.8, 'cost' => 4.64, 'platforms' => 3.4, 'track_record' => 2.31, 'overall' => 3.07 ), 'rank' => 35 ),
        array( 'slug' => 'fusion-markets', 'name' => 'Fusion Markets', 'entity' => 'Fusion Markets EU Ltd', 'cysec' => '444/24', 'seychelles' => 'SD096', 'founded' => 2017, 'hq' => 'Melbourne, Australia', 'min_deposit_usd' => 0, 'min_deposit_display' => 'No minimum', 'spread_eurusd' => 0.9, 'platforms' => array('MT4', 'MT5', 'cTrader', 'TradingView'), 'other_reg' => array('ASIC'), 'other_reg_count' => 1, 'instruments' => '250+ instruments across forex, indices, commodities, shares and crypto CFDs', 'account_types' => 'Zero (raw-spread, roughly $4.50 round-turn commission, spreads from 0.0 pips) and Classic (no separate commission, cost built into the spread), both with an Islamic/swap-free option available on request -- clients must declare a religious basis and can\'t mix swap-free and swap-charged accounts.', 'execution_model' => 'Described as ECN/STP, routing to liquidity pools from multiple institutions, though no more specific detail was found.', 'withdrawal_deposit_note' => 'Advertised as fee-free on Fusion\'s side (banks/payment providers may add their own costs). Sources disagree on the minimum deposit ($0 vs. $10). Methods include cards, Neteller, PayPal, Skrill, bank wire, BinancePay and SticPay, with processing from instant up to 1-5 business days depending on method.', 'overnight_financing' => 'Reported to use an "admin fee" model rather than a conventional nightly swap, charged only once a position has been open longer than 7 days, varying by instrument -- this specific mechanism came from a secondary source rather than Fusion Markets\' own site directly, so it\'s worth verifying before relying on exact figures.', 'currency_conversion_fee' => 'Not found -- no specific fee or percentage was located.', 'inactivity_fee' => 'Disputed: most recent sources say no inactivity fee is charged, while other mentions suggest a fee could apply after 6 months of dormancy. Not clearly confirmed either way.', 'customer_service_note' => 'Trustpilot rates it strongly, around 4.8/5 across roughly 8,000+ reviews (about 88% five-star). Praise centers on responsive, personalized support, with some complaints about generic, "copy-paste"-style answers.', 'mobile_note' => 'Reported around 4.4 on Android and 4.8 on iOS across its cTrader/MT4/MT5/TradingView apps; the cTrader app is singled out for its large number of indicators and timeframes.', 'education_note' => 'Explicitly noted by at least one independent reviewer as a weak point -- limited educational resources, with no dedicated academy or course content found.', 'blurb' => 'Founded in 2017 by former Pepperstone executives Phil Horner and David Swinden, Fusion Markets is built around low-cost pricing and added its CySEC-licensed EU entity (444/24) as one of the newest licences in this group, issued in 2024.', 'cysec_note' => 'Fusion Markets also operates offshore entities regulated by Vanuatu\'s VFSC and the Seychelles FSA, excluded here as non-Tier-1.', 'scores' => array( 'regulation' => 1.8, 'cost' => 4.64, 'platforms' => 4.2, 'track_record' => 1.49, 'overall' => 3.07 ), 'rank' => 36 ),
        array( 'slug' => 'fxglobe', 'name' => 'FXGlobe', 'entity' => 'FXGLOBE Ltd', 'cysec' => '205/13', 'founded' => null, 'hq' => 'Limassol, Cyprus', 'min_deposit_usd' => 540, 'min_deposit_display' => '€500 (general minimum first funding); a "Pathfinder" entry account is advertised elsewhere from €250', 'spread_eurusd' => 0.7, 'platforms' => array('MT4', 'MT5'), 'other_reg' => array('FSCA'), 'other_reg_count' => 1, 'instruments' => 'Forex, stocks/equities, and other CFDs (site has a dedicated stocks section and a separate equities account type)', 'account_types' => 'Standard (minimum deposit $250), Pro (raw-spread style, spreads from around 1.2 pips plus roughly $7/lot commission), Islamic/swap-free, and a demo account.', 'execution_model' => 'Holds a CySEC "Forex Execution Licence (STP)" and markets itself as operating in an ECN-style environment; it also holds a separate Vanuatu licence. One unverified customer-complaint thread alleges the broker told a client their account fell under the weaker Vanuatu licence rather than CySEC -- a disputed customer claim, not independently confirmed, but worth flagging given the jurisdiction-protection stakes.', 'withdrawal_deposit_note' => 'Minimum withdrawal $25, with withdrawal fees reported to start from $0 depending on method; processing from 15 minutes up to 3 business days. Methods include bank card, bank wire, crypto (BTC/ETH/USDT), Neteller and Skrill for withdrawals, with additional deposit-only methods like SEPA and various regional payment processors.', 'overnight_financing' => 'Standard swap applies on conventional accounts; Islamic accounts are swap-free. No specific broker markup was found.', 'currency_conversion_fee' => 'Not found -- no specific fee or percentage was located.', 'inactivity_fee' => 'Confirmed to exist, reportedly starting from $25 on dormant accounts, though the exact trigger period (e.g. 90 or 180 days) wasn\'t found.', 'customer_service_note' => 'Trustpilot TrustScore 3.5/5 from 260 reviews; the company replies to roughly three-quarters of negative reviews but often takes over a month to do so. Users describe staff as helpful when reached, though the slow reply time weighs on the overall picture.', 'mobile_note' => 'Not found -- no App Store or Google Play rating was located specifically for FXGlobe\'s apps.', 'education_note' => 'Educational resources, market news and risk-management tools are mentioned generically in marketing material, but no detail on course depth, webinar frequency, or an independent quality rating was found.', 'blurb' => 'FXGlobe runs three tiered account levels (Pathfinder, Navigator, Infinity) with rising minimum deposits, and the same brand also carries a South African FSCA licence through a separate related entity.', 'cysec_note' => 'The FSCA licence (FSP No. 52045) is held by a related entity, APLFX (Pty) Ltd, trading under the FXGlobe brand -- not by FXGLOBE Ltd, the CySEC entity.', 'scores' => array( 'regulation' => 1.8, 'cost' => 4.62, 'platforms' => 2.6, 'track_record' => null, 'overall' => 3.06 ), 'rank' => 37 ),
        array( 'slug' => 'ironfx', 'name' => 'IronFX', 'entity' => 'Notesco Financial Services Ltd', 'cysec' => '125/10', 'fca' => '585561', 'founded' => 2010, 'hq' => 'Limassol, Cyprus', 'min_deposit_usd' => 100, 'min_deposit_display' => '$100 (a lower-deposit Cent account is also offered)', 'spread_eurusd' => 1.2, 'platforms' => array('MT4', 'MT5'), 'other_reg' => array('FSCA'), 'other_reg_count' => 1, 'instruments' => '500+ instruments across roughly 6 asset classes: shares, indices, forex (80+ pairs), futures, metals and commodities', 'account_types' => 'Multiple tiers reported: Micro, Standard, Premium, VIP, Zero Fixed, No Commission, Zero Spread, and Absolute Zero, with Islamic/swap-free available across Standard, Premium, Zero Fixed and VIP. Zero Fixed carries an $18 round-turn commission per lot.', 'execution_model' => 'Varies genuinely by account type, one of the more clearly confirmed cases in this research: Micro/Premium/VIP/Zero Fixed use floating or fixed spreads in a dealing-desk style, while No Commission/Zero Spread/Absolute Zero are marketed as ECN/STP.', 'withdrawal_deposit_note' => 'Minimum deposit $100. IronFX reportedly recently waived fees on all withdrawal methods, though e-wallet deposits are said to carry around a 2% charge. Deposits are near-instant; withdrawals take 1-3 business days. Methods include bank transfer, cards, Neteller, PayPal and Skrill.', 'overnight_financing' => 'Standard swap mechanics apply on conventional accounts; Islamic accounts are confirmed swap-free directly from IronFX\'s own materials. Broker markup specifics weren\'t found.', 'currency_conversion_fee' => 'Not found -- no specific fee or percentage was located.', 'inactivity_fee' => 'Confirmed to exist generically, but the exact amount and trigger period weren\'t confirmed -- a commonly cited $50-after-3-months figure traces to an unrelated legal-contract database rather than IronFX\'s own policy, so treat it as unconfirmed.', 'customer_service_note' => 'Significant reputational concern: Trustpilot shows a weak TrustScore of around 2/5 (717 reviews) for the main entity and 2.5/5 (78 reviews) for the EU entity, with many recent reviewers reporting serious withdrawal and refund disputes and funds being withheld. Live-chat support itself gets some positive mentions for responsiveness, and 24/5 multilingual support across 30+ languages is claimed.', 'mobile_note' => 'Its trading app is rated around 3.5-3.8 across sources, and ranked 61st of 62 brokers in one independent comparison -- one of the lowest-rated apps found in this research set.', 'education_note' => 'Marketing material describes a trading school, blog, webinars, podcasts, courses and a "VIP Room" with expert insights, but no independent reviewer\'s quality assessment was found to corroborate the breadth claimed.', 'blurb' => 'IronFX/FXLift is a trade name of the Notesco group, which is dual-regulated for EU clients under CySEC (Notesco Financial Services Ltd, 125/10) and for UK clients under the FCA, plus an FSCA licence in South Africa.', 'scores' => array( 'regulation' => 2.6, 'cost' => 4.5, 'platforms' => 2.6, 'track_record' => 2.06, 'overall' => 3.06 ), 'rank' => 38 ),
        array( 'slug' => 'amana-capital', 'name' => 'Amana Capital', 'entity' => 'Amana Capital Ltd', 'cysec' => '155/11', 'fca' => null, 'fca_note' => 'FCA-licensed; firm reference number not independently confirmed.', 'founded' => 2010, 'hq' => 'Limassol, Cyprus', 'min_deposit_usd' => 50, 'min_deposit_display' => '$50 (Classic account, approximate — some sources list no stated minimum)', 'spread_eurusd' => 1.4, 'platforms' => array('MT4', 'MT5'), 'other_reg' => array('DFSA'), 'other_reg_count' => 1, 'instruments' => '360+ instruments across forex (66 pairs), 330+ share CFDs, indices, metals, energies, commodities and crypto', 'account_types' => 'Sources conflict significantly: one comparison site describes only individual/joint/corporate account variants (no execution-style tiers), while another describes Classic (low-deposit, beginner), Active, and Elite (raw-spread, high-volume) tiers. This is a genuine, unresolved disagreement between sources.', 'execution_model' => 'One source states Amana uses a market-maker model with no ECN or STP accounts offered; this is in tension with the "raw spreads" language used for the Active/Elite tiers described by another source, which would imply an STP-style model for those tiers. Treat as disputed rather than settled.', 'withdrawal_deposit_note' => 'Minimum deposit figures conflict ($1,000 vs. a more recent $50 figure). No deposit fees from Amana itself (card processors may charge 1-3%). Minimum withdrawal $10, processing from 15 minutes up to 3 business days. Methods include bank wire, cards and PayPal for deposits, plus Neteller and Skrill for withdrawals.', 'overnight_financing' => 'Multiple sources describe every Amana Capital account as swap-free by default, in line with Sharia principles -- an unusually broad, singular claim from limited sourcing that\'s worth verifying directly rather than assuming confirmed.', 'currency_conversion_fee' => 'Not found -- no specific fee or percentage was located.', 'inactivity_fee' => 'Not found.', 'customer_service_note' => 'Trustpilot rates it around 3.5/5 with mixed feedback: some praise fast withdrawals and helpful support after extended use, while others report unanswered phones, poor email responsiveness, and app glitches including an inability to stop trading.', 'mobile_note' => 'An app matching Amana\'s name shows a strong rating (around 4.7 from about 195 ratings) on iOS, but this could not be confirmed as the same company as Amana Capital Ltd the FX/CFD broker -- a similarly named, unrelated consumer investing app exists in the same region, so this figure isn\'t reliably attributable and shouldn\'t be taken as Amana Capital\'s own rating.', 'education_note' => 'Marketing material references tutorials and educational content, but this description may also trace to the ambiguous similarly-named app rather than Amana Capital specifically -- not independently confirmed.', 'blurb' => 'Cyprus entity of a broader group with UK (FCA) and Dubai (DFSA) licensed affiliates alongside its CySEC licence.', 'scores' => array( 'regulation' => 2.6, 'cost' => 4.43, 'platforms' => 2.6, 'track_record' => 2.06, 'overall' => 3.04 ), 'rank' => 39 ),
        array( 'slug' => 'libertex', 'name' => 'Libertex', 'entity' => 'Indication Investments Ltd', 'cysec' => '164/12', 'founded' => 2012, 'hq' => 'Limassol, Cyprus', 'min_deposit_usd' => 100, 'min_deposit_display' => '$100 (varies by region/promo, as low as $10 on some entities)', 'spread_eurusd' => 0.5, 'platforms' => array('MT4', 'MT5', 'Proprietary (Libertex)'), 'other_reg' => array('FSCA'), 'other_reg_count' => 1, 'instruments' => 'Roughly 1,000+ CFDs and real-share offerings spanning forex, indices, commodities, ETFs, bonds and cryptocurrencies.', 'account_types' => 'Two main products: a Portfolio Account (long-term stock investing, no commission, no swap, no inactivity fee) and a CFD Account (leveraged trading up to 1:999, spread-based pricing). No separate Islamic, professional, or ECN tier was found.', 'execution_model' => 'Libertex states it uses "Market Execution" -- orders filled at the best available price rather than a requoted or fixed model -- but isn\'t classified by independent sources as specifically ECN or STP.', 'withdrawal_deposit_note' => 'No minimum deposit requirement and no fee on bank-wire deposits. Card deposits carry a 2.5% fee (minimum $0.50), Skrill 1.9% (minimum $0.50), and Neteller 4.0% (no minimum). Withdrawals carry a 0.5% fee (minimum €2, maximum €10), with card withdrawals a flat €1 and Neteller withdrawals 1.0%. Methods include bank transfer, cards, Skrill, Neteller, PayPal and crypto.', 'overnight_financing' => 'Rollover interest is applied at 9pm GMT, tripled Wednesday-to-Thursday for FX pairs and Friday-to-Monday for CFDs, the standard triple-swap convention. Libertex does not offer an Islamic/swap-free account, so this applies universally. At least one independent source criticizes its broader commission/fee disclosure as confusing and not fully transparent.', 'currency_conversion_fee' => 'A fee applies when an asset\'s currency differs from the account\'s base currency, but the exact rate is explicitly described by one source as undisclosed.', 'inactivity_fee' => 'Sources differ on the exact trigger period (90 vs. 180 days), though both corroborate a fee of roughly €10/month -- treat the fee amount as reasonably confirmed and the trigger period as unconfirmed.', 'customer_service_note' => 'Two separate Trustpilot listings exist for the Libertex group (libertex.com and libertex.org) showing similar overall scores around 3.8-4/5 from very large review bases (several thousand each), but differing negative-review response rates (83% within a week vs. 100% within 48 hours). Users commonly praise the interface as beginner-friendly.', 'mobile_note' => 'iOS App Store rating of 4.3/5 from 435 reviews; a Google Play rating wasn\'t found.', 'education_note' => '"Libertex Academy" offers courses, videos, guides, tutorials and hour-long webinars with company presenters, plus a demo account with up to $100,000 in virtual funds. At least one independent reviewer notes a shortage of educational material variety despite decent quality -- a mixed assessment.', 'blurb' => 'Libertex is operated by Indication Investments Ltd (CySEC 164/12, founded as a brand in 2012) and offers MT4/MT5 alongside its own Libertex platform, with a separate group entity also holding an FSCA license in South Africa.', 'cysec_note' => 'FSCA held by a separate Libertex group entity, not Indication Investments Ltd. Group also holds offshore licenses (Mauritius FSC, Vanuatu VFSC) which are excluded per the approved regulator list. No FCA license; UK/AU/US clients not accepted.', 'scores' => array( 'regulation' => 1.8, 'cost' => 4.78, 'platforms' => 3.4, 'track_record' => 1.9, 'overall' => 3.03 ), 'rank' => 40 ),
        array( 'slug' => 'doto', 'name' => 'Doto', 'entity' => 'Doto Europe Ltd', 'cysec' => '399/21', 'seychelles' => 'SD0063', 'seychelles_note' => 'unusual 4-digit format; worth confirming against the FSA register directly', 'founded' => 2019, 'hq' => 'Limassol, Cyprus', 'min_deposit_usd' => 15, 'min_deposit_display' => '$15', 'spread_eurusd' => null, 'platforms' => array('MT4', 'MT5', 'Proprietary (Doto Platform)'), 'other_reg' => array('FSCA'), 'other_reg_count' => 1, 'instruments' => 'Forex, indices, commodities and a selection of cryptocurrency CFDs', 'account_types' => 'Standard and Raw Spread accounts, with a minimum deposit as low as $15; both are available in demo form preloaded with $10,000 in virtual funds. No separate Islamic/swap-free account was found.', 'execution_model' => 'Doto Europe Ltd specifically is CySEC-licensed for "Forex Execution (STP)" -- a direct, entity-specific confirmation rather than generic industry description.', 'withdrawal_deposit_note' => 'Marketed as offering free deposits and withdrawals, though no specific fee schedule or minimum-withdrawal figure was found. Minimum deposit $15. Note: Doto operates through several separate legal entities (this CySEC-regulated one, plus others under Mauritius, South African and Seychelles regulators), and most review-site commentary found doesn\'t distinguish which entity a given customer\'s experience applies to.', 'overnight_financing' => 'Only generic industry swap mechanics were found (interest differential plus broker markup, Wednesday triple charge); no Doto-specific rate or markup was disclosed.', 'currency_conversion_fee' => 'Not found -- no specific fee or percentage was located.', 'inactivity_fee' => 'Not found.', 'customer_service_note' => 'Trustpilot shows a TrustScore around 3.5/5 from roughly 155-160 reviews (varying slightly by regional mirror), with the company replying to about three-quarters of negative reviews within roughly two weeks. Two independent review sites separately scored its customer support considerably higher (around 4.0 and 4.9 out of 5) -- a meaningful spread between organic Trustpilot sentiment and editorial review scores, worth noting as a disagreement. User feedback is mixed: praise for the interface, complaints about withdrawal fees and issues.', 'mobile_note' => 'Its app shows 500,000+ installs on Google Play, but no star rating was found.', 'education_note' => 'One independent review site rated its education section 2.5/5, describing it as limited and needing more detailed learning materials. Its demo account is the most substantial confirmed educational tool.', 'blurb' => 'Doto Europe Ltd (formerly Vasby Capital Markets Ltd) is one entity within a multi-jurisdiction group also comprising Doto Global Ltd (Mauritius), Doto International Ltd (Seychelles) and Doto South Africa (Pty) Ltd (FSCA); reported EUR/USD spreads vary by account type so no single figure could be confirmed.', 'cysec_note' => 'FSCA licence is held via a separate but same-brand entity, Doto South Africa (Pty) Ltd; Doto Global Ltd is also FSC-Mauritius licensed and Doto International Ltd FSA-Seychelles licensed (both excluded as non-Tier-1).', 'scores' => array( 'regulation' => 1.8, 'cost' => 4.99, 'platforms' => 3.4, 'track_record' => 1.33, 'overall' => 2.98 ), 'rank' => 41 ),
        array( 'slug' => 'justmarkets', 'name' => 'JustMarkets', 'entity' => 'JustMarkets Ltd', 'cysec' => '401/21', 'seychelles' => 'SD088', 'founded' => 2012, 'hq' => 'Limassol, Cyprus', 'min_deposit_usd' => 10, 'min_deposit_display' => '$10', 'spread_eurusd' => 1, 'platforms' => array('MT4', 'MT5', 'Proprietary (JM Mobile Trading App)'), 'other_reg' => array('FSCA'), 'other_reg_count' => 1, 'instruments' => 'Currency pairs, indices, commodities, share CFDs and cryptocurrencies', 'account_types' => 'Standard, Standard Cent, Pro, and Raw Spread (available on both MT4 and MT5), with a swap-free/Islamic option layered across account types.', 'execution_model' => 'JustMarkets states it uses STP execution, though one independent community source notes no liquidity-provider quotes have been published to verify this -- treat it as the broker\'s own characterization rather than independently confirmed.', 'withdrawal_deposit_note' => 'No deposit or withdrawal fees reported. Bank transfer takes 1-3 business days; card and e-wallet withdrawals are typically instant.', 'overnight_financing' => 'Islamic/swap-free accounts pay a fixed replacement fee instead of swap; the benchmark-rate-plus-markup formula used for standard (non-Islamic) accounts wasn\'t found.', 'currency_conversion_fee' => 'Deposits in a currency different from the account currency are auto-converted, but the specific conversion fee or markup percentage wasn\'t found.', 'inactivity_fee' => '$5 debited after 150 days of no activity, per one moderate-confidence secondary source (not independently confirmed directly against JustMarkets\' own site).', 'customer_service_note' => '24/7 multilingual live chat, plus additional channels (Telegram, Viber, Facebook Messenger, Instagram, iMessage) for the Seychelles FSA entity specifically; the CySEC entity offers live chat only. Email responses typically arrive within 48 hours. Trustpilot ratings are cited inconsistently across sources (4.4/5 from 3,000+ reviews in one place, 4.8/5 from around 2,000 in another) -- sources disagree on the exact figures.', 'mobile_note' => 'Its "JustMarkets Trade" app on Google Play has 44,300+ installs, but no star rating was found in reachable sources.', 'education_note' => 'Described by one source as limited; the broker runs contests and events (such as a "Grand Seminar"), but no detailed course catalogue was found.', 'blurb' => 'JustMarkets rebranded from JustForex in September 2022 at the same time it launched its CySEC-licensed EU entity, and advertises a $10 minimum deposit on its Standard account versus $200 for Pro/Raw Spread accounts.', 'cysec_note' => 'FSCA registration is associated with the JustMarkets brand generally; not confirmed to be the same legal entity as CySEC-licensed JustMarkets Ltd.', 'scores' => array( 'regulation' => 1.8, 'cost' => 4.6, 'platforms' => 3.4, 'track_record' => 1.9, 'overall' => 2.98 ), 'rank' => 42 ),
        array( 'slug' => 'octa', 'name' => 'Octa', 'entity' => 'Octa Markets Cyprus Ltd', 'cysec' => '372/18', 'founded' => 2011, 'hq' => 'Nicosia, Cyprus (Octa Markets Cyprus Ltd, the CySEC entity); the global Octa brand\'s other entities are headquartered in Saint Lucia and St. Vincent & the Grenadines', 'min_deposit_usd' => 25, 'min_deposit_display' => '$25', 'spread_eurusd' => 0.6, 'platforms' => array('MT4', 'MT5', 'cTrader', 'Proprietary (OctaTrader)'), 'other_reg' => array(), 'other_reg_count' => 0, 'instruments' => null, 'account_types' => 'Standard, Pro (on cTrader), and ECN, available across OctaTrader, MT4 and MT5, all supporting scalping, hedging and copy trading.', 'execution_model' => 'STP/ECN with no dealing desk, consistent across multiple sources; the minimum spread is cited inconsistently as either 0.2 or 0.5 pips depending on the source.', 'withdrawal_deposit_note' => 'Zero deposit or withdrawal fees on any method. Minimum deposit $25 (around $50 for some cryptocurrencies). Methods include bank wire, card, e-wallet, and crypto (BTC, ETH, USDT, LTC, DOGE), with crypto withdrawals often processing in under an hour.', 'overnight_financing' => 'A notable finding: Octa is reported to have removed swap/overnight financing fees for all account types, not just a separate Islamic tier -- this is a differentiator worth double-checking against Octa\'s current live terms before relying on it, since broker policies can change.', 'currency_conversion_fee' => 'Not found -- no specific fee or percentage was located.', 'inactivity_fee' => 'None -- multiple independent sources confirm Octa charges no inactivity fee.', 'customer_service_note' => 'Trustpilot rates it 4.4/5, with reviewers citing ease of use, low spreads, and support quality.', 'mobile_note' => 'Its Google Play app has 230,000+ reviews described as high-rated, though an exact star figure wasn\'t found; one independent review site scores its mobile trading 4/5.', 'education_note' => 'Described as comprehensive, including webinars and both beginner and advanced video content.', 'blurb' => 'Octa (rebranded from OctaFX in late 2023) is a global CFD broker reporting over 13 million clients across 180+ countries, with its EU-facing operations regulated by CySEC as Octa Markets Cyprus Ltd; client funds there are covered up to €20,000 via the Investor Compensation Fund.', 'scores' => array( 'regulation' => 1, 'cost' => 4.76, 'platforms' => 4.2, 'track_record' => 1.98, 'overall' => 2.96 ), 'rank' => 44 ),
        array( 'slug' => 'tickmill', 'name' => 'Tickmill', 'entity' => 'Tickmill Europe Ltd', 'cysec' => '278/15', 'fca' => '717270', 'seychelles' => 'SD008', 'founded' => 2014, 'hq' => 'Limassol, Cyprus', 'min_deposit_usd' => 100, 'min_deposit_display' => '$100', 'spread_eurusd' => 1.7, 'platforms' => array('MT4', 'MT5'), 'other_reg' => array('FSCA'), 'other_reg_count' => 1, 'instruments' => 'Forex, indices, commodities, bonds CFDs', 'account_types' => 'Classic (spreads from around 1.6 pips, no commission, $100 minimum), Raw/Pro (spreads from 0.0 pips, commission reported inconsistently as $2-3 per side per lot across sources), and VIP ($50,000+ balance, spreads from 0.0, around $1 per side commission, personal account manager). Account naming and exact commission tiers aren\'t fully consistent across sources.', 'execution_model' => 'ECN/STP, described consistently across sources as no-dealing-desk.', 'withdrawal_deposit_note' => 'No Tickmill-side commission on deposits or withdrawals. A "Zero Fees Policy" reimburses up to $100 in bank-wire charges for transfers of $5,000 or more. Minimum withdrawal around $25 equivalent; minimum deposit $100.', 'overnight_financing' => 'An Islamic/swap-free account is available, but a handling/admin charge applies for holding several instruments overnight, and a reported 10%/year charge applies to long crypto positions even on the Islamic account.', 'currency_conversion_fee' => 'Base currencies are EUR, GBP, USD and PLN. Tickmill states it charges no internal conversion fee, with conversions to or from other currencies using real-time rates -- though your own bank may add its own charge.', 'inactivity_fee' => '$10 after 12 months of inactivity.', 'customer_service_note' => 'A notable finding: Tickmill\'s Trustpilot profile currently carries a warning (as of mid-2026) stating fabricated reviews were removed, with a visible score of around 3.1/5 (1,130 reviews); a separate, seemingly older source instead cites 4.1/5 -- a direct conflict worth disclosing rather than picking one number. One independent review site separately rates its customer support 4.8/5.', 'mobile_note' => 'Only a very thin data point was found -- one App Store listing shows 5.0/5 from a single rating, not statistically meaningful. Tickmill offers MT4/MT5 mobile apps plus a separate account-management-only app that doesn\'t support trading.', 'education_note' => 'Active webinars, seminars, video tutorials and blog content; one independent review site gives its education a 5.0/5 score.', 'blurb' => 'No account maintenance or inactivity fees on CySEC-regulated accounts; wider standard spreads than ECN-focused peers.', 'scores' => array( 'regulation' => 2.6, 'cost' => 4.3, 'platforms' => 2.6, 'track_record' => 1.73, 'overall' => 2.94 ), 'rank' => 46 ),
        array( 'slug' => 'tiomarkets', 'name' => 'TioMarkets', 'entity' => 'TioMarkets CY Ltd', 'cysec' => '429/23', 'seychelles' => 'SD167', 'founded' => 2018, 'hq' => null, 'min_deposit_usd' => 10, 'min_deposit_display' => '$10', 'spread_eurusd' => 1.2, 'platforms' => array('MT4', 'MT5'), 'other_reg' => array('FSCA'), 'other_reg_count' => 1, 'instruments' => '300+ CFDs across forex, indices, stocks, and commodities', 'account_types' => 'Nano (minimum $20, around 0.6 pip spread, $6/lot commission), Standard (minimum $20, around 1.1 pip, no commission), Raw (minimum $250, 0.0 pip, $6/lot commission), and VIP Black (minimum $1,000, around 0.3 pip, no commission). An Islamic/swap-free option is available on eligible instruments, but clients must contact support after registration to confirm eligibility.', 'execution_model' => 'Markets itself as "true ECN" with no dealing desk and no rejections -- this is the broker\'s own characterization; no independent third-party execution-quality data was found to verify it.', 'withdrawal_deposit_note' => 'Deposits and withdrawals are fee-free if $20 or more; a $25 processing fee applies if the account was funded but never traded, if the withdrawal is under $20, or for crypto withdrawals. Minimum withdrawal $20. Bank wire supports EUR, USD, GBP, CAD and AED.', 'overnight_financing' => 'The Islamic account removes swap on eligible instruments; the standard swap calculation (benchmark plus markup) wasn\'t found.', 'currency_conversion_fee' => 'Not found -- no specific fee or percentage was located.', 'inactivity_fee' => 'Accounts are deemed inactive after just 3 months with no open positions or trades, triggering a $30/month dormancy fee -- notably faster-triggering and higher than most peers researched so far.', 'customer_service_note' => 'Trustpilot rates it 4.5/5 from 691 reviews; praised for quick, professional 24/7 live chat and phone support, with some mixed feedback on payment-processing delays.', 'mobile_note' => 'One aggregator cites 3.6 on Android and 4.6 on iOS -- single-source figures not cross-verified elsewhere.', 'education_note' => 'Not found -- no detailed course or webinar catalogue was located, despite general marketing claims of research tools.', 'blurb' => 'TioMarkets is known for a very low ($10) minimum deposit and dual FCA/CySEC regulation, though its Cyprus entity (TioMarkets CY Ltd) is reported to be under CySEC examination for voluntary licence renunciation, worth flagging prominently.', 'cysec_note' => 'CySEC lists this licence as under examination for voluntary renunciation -- confirm current regulatory status directly with the broker and the CySEC register before relying on it.', 'fca' => null, 'fca_note' => 'FCA-licensed; firm reference number not independently confirmed.', 'scores' => array( 'regulation' => 2.6, 'cost' => 4.52, 'platforms' => 2.6, 'track_record' => 1.41, 'overall' => 2.94 ), 'rank' => 47 ),
        array( 'slug' => 'gbe-brokers', 'name' => 'GBE Brokers', 'entity' => 'GBE Brokers Ltd', 'cysec' => '240/14', 'seychelles' => 'SD176', 'founded' => 2014, 'hq' => 'Limassol, Cyprus (with a branch office in Hamburg, Germany)', 'min_deposit_usd' => 1080, 'min_deposit_display' => '€1,000 / $1,000 / CHF 1,000 (Classic account)', 'spread_eurusd' => 0.7, 'platforms' => array('MT4', 'MT5', 'TradingView'), 'other_reg' => array('BaFin'), 'other_reg_count' => 1, 'instruments' => 'Forex plus CFDs on indices, commodities and stocks (1,000+ instruments claimed via MT5)', 'account_types' => 'Standard (minimum €500, spreads from 0.1 pip) and Professional (tighter spreads, higher leverage, for experienced/qualifying clients). An Islamic/swap-free account wasn\'t confirmed in any source reached -- not found, not necessarily unavailable.', 'execution_model' => 'Described as strict ECN/STP with no dealing desk, routing to Tier-1 interbank liquidity -- a broker/reviewer description, not independently benchmarked.', 'withdrawal_deposit_note' => 'Methods include wire transfer, credit card, Neteller and Skrill. Deposits are fee-free. Withdrawal fees vary by method -- credit card withdrawals incur around 1.5%, while bank wire is generally free. Minimum deposit is cited as €500 for the Standard account, though one source references up to €1,000 for other tiers.', 'overnight_financing' => 'Not found -- no benchmark-plus-markup disclosure was located.', 'currency_conversion_fee' => 'Not found -- no specific fee or percentage was located.', 'inactivity_fee' => 'Sources directly conflict: one states €10/month after 12 months of no activity, another states GBE charges no inactivity fee at all. Not resolved -- both claims are reported here rather than one being picked.', 'customer_service_note' => 'Trustpilot rates it unusually highly, 4.9/5 from around 670 reviews; reviewers specifically praise assigned personal account managers over automated or chatbot-style support.', 'mobile_note' => 'One independent review site rates its mobile trading apps 4/5.', 'education_note' => 'Flagged by one reviewer as a relative weak point, lacking a standard beginner/advanced video library, though GBE has launched free webinars focused specifically on using the TradingView platform.', 'blurb' => 'GBE Brokers is one of the few CySEC brokers also directly registered with Germany\'s BaFin for its Hamburg branch, and its entry-level Classic account has a comparatively high $1,000 minimum deposit.', 'cysec_note' => 'BaFin registration covers GBE Brokers\' Hamburg, Germany branch.', 'scores' => array( 'regulation' => 1.8, 'cost' => 4.52, 'platforms' => 3.4, 'track_record' => 1.73, 'overall' => 2.92 ), 'rank' => 48 ),
        array( 'slug' => 'fbs', 'name' => 'FBS', 'entity' => 'Tradestone Ltd', 'cysec' => '331/17', 'seychelles' => null, 'seychelles_note' => 'FSA Seychelles-licensed via FBS Trading (Seychelles) Ltd, per the official FSA Capital Markets register; licence number not independently confirmed.', 'founded' => 2009, 'hq' => null, 'min_deposit_usd' => 11, 'min_deposit_display' => '€10', 'spread_eurusd' => null, 'platforms' => array('MT4', 'MT5', 'Proprietary (FBS Trader)'), 'other_reg' => array(), 'other_reg_count' => 0, 'instruments' => 'Forex, indices, commodities, stocks and crypto CFDs', 'account_types' => 'Non-EU/offshore FBS entities offer five tiers (Cent, Micro, Standard, Zero Spread, ECN), but the EU entity (Tradestone Ltd) reviewed here offers only Standard and Cent accounts (leverage capped at 1:30), plus "Pro Standard"/"Pro Cent" variants for professional clients (leverage up to 1:500).', 'execution_model' => 'The ECN account routes to liquidity providers with commission charged; Standard/Cent and other accounts are STP with execution speed marketed around 0.3 seconds and no commission.', 'withdrawal_deposit_note' => 'Methods include bank card, bank wire, Neteller and Skrill (availability varies by region). No FBS-side withdrawal fee is stated, though banks or processors may charge their own. Processing: e-wallets near-instant (up to 30 minutes), cards around 3-4 business days, bank wire around 7-10 business days. Minimum withdrawal is reported as low as $1, though method-specific minimums vary ($1-10 for e-wallets, $10-30 for cards, $50-100 for wire).', 'overnight_financing' => 'On Islamic/swap-free accounts, no swap applies on short holds, but FBS may charge a fixed fee (one point\'s value times the swap point size) for positions held more than 2 days, framed as an administrative charge rather than interest. The swap-calculation methodology for standard (non-Islamic) accounts wasn\'t found.', 'currency_conversion_fee' => 'Not found -- no specific fee or percentage was located for general currency conversion.', 'inactivity_fee' => 'Confirmed to exist generically (charged after a long period without use), but the exact threshold and amount weren\'t confirmed from a primary source.', 'customer_service_note' => '24/7 support via live chat and email. Trustpilot shows a high TrustScore around 4.3-4.5/5 from roughly 10,000 reviews, with mixed comments -- praise for fast deposits/withdrawals alongside complaints about account terminations.', 'mobile_note' => 'Google Play rating around 4.4/5 (90,000+ reviews, 10 million+ downloads); App Store around 4.9/5. Described as lightweight and beginner-friendly by independent reviewers.', 'education_note' => '"FBS Academy" offers structured courses, webinars and step-by-step lessons, plus a demo account with virtual funds and no expiry. Widely described by independent reviewers as strong for beginners.', 'blurb' => 'FBS\'s CySEC-licensed EU entity (Tradestone Ltd) markets a low minimum deposit of about €10 for European clients, distinct from the $1 cent-account minimum FBS advertises through its non-EU offshore entities.', 'scores' => array( 'regulation' => 1, 'cost' => 5, 'platforms' => 3.4, 'track_record' => 2.14, 'overall' => 2.91 ), 'rank' => 50 ),
        array( 'slug' => 'jfd-brokers', 'name' => 'JFD Brokers', 'entity' => 'JFD Group Ltd', 'cysec' => '150/11', 'founded' => 2011, 'hq' => 'Limassol, Cyprus', 'min_deposit_usd' => 540, 'min_deposit_display' => '€500 (or equivalent in USD/GBP/CHF)', 'spread_eurusd' => null, 'platforms' => array('MT4', 'MT5'), 'other_reg' => array('BaFin'), 'other_reg_count' => 1, 'instruments' => null, 'account_types' => 'Historical/legacy information only, predating the April 2026 retail-market exit noted above: Standard (floating spreads, no added commission) and ECN/RAW (near-raw spreads plus commission).', 'execution_model' => 'Described elsewhere as 100% DMA/STP/no-dealing-desk, though this wasn\'t independently re-confirmed against JFD\'s own fee schedule before its retail exit.', 'withdrawal_deposit_note' => 'Legacy information: reported as no withdrawal fee; specific payment methods, processing times and minimums weren\'t found.', 'overnight_financing' => 'Not found -- no benchmark-plus-markup swap methodology was located.', 'currency_conversion_fee' => 'Not found -- no specific fee or percentage was located.', 'inactivity_fee' => 'Sources conflict: one comparison site states no inactivity fee existed, while Trustpilot reviews include complaints that JFD drained accounts due to inactivity fees -- a genuine, unresolved conflict rather than a settled fact.', 'customer_service_note' => 'Legacy Trustpilot rating around 4.1/5 from a small sample (33 reviews). Reviews were mixed: some called support very helpful and praised platform stability, while others reported a serious account-draining complaint (including one citing a roughly €14,000 loss) and a phishing/security-related complaint. JFD reportedly responded to about three-quarters of negative reviews, usually within two weeks.', 'mobile_note' => 'No verified App Store or Google Play star rating was found; a figure sometimes cited elsewhere traces to a broker-comparison score rather than an actual app-store rating.', 'education_note' => 'Offered MT4+, MT5+, and the German-focused "Guidants" platform (charts, expert streams, research features) across 1,500+ tradable assets, but no dedicated webinar or course program was found.', 'blurb' => 'Important: JFD Group Ltd announced in April 2026 that it is withdrawing from the retail market -- GBE Brokers Ltd acquired its retail client base and partner network in an asset deal, with German-speaking client support moving to GBE\'s Hamburg office. As of this review, JFD is effectively no longer operating as a retail broker; the account and fee details below predate this exit and are kept only as historical/legacy information, not a live offering.', 'cysec_note' => 'The BaFin licence is held by the German affiliate JFD Bank AG, a separate legal entity from the CySEC-licensed JFD Group Ltd; JFD\'s earlier FCA passporting registration lapsed after Brexit. Note: this CySEC licence\'s practical relevance is now in question given JFD\'s April 2026 retail-market exit (see blurb above).', 'scores' => array( 'regulation' => 1.8, 'cost' => 4.8, 'platforms' => 2.6, 'track_record' => 1.98, 'overall' => 2.9 ), 'rank' => 51 ),
        array( 'slug' => 'oneroyal', 'name' => 'OneRoyal', 'entity' => 'Royal Financial Trading (Cy) Ltd', 'cysec' => '312/16', 'founded' => 2006, 'hq' => 'Sydney, Australia (group); Cyprus entity based in Limassol', 'min_deposit_usd' => 5, 'min_deposit_display' => '$5 (Classic/ECN accounts); $5,000 for Prime account', 'spread_eurusd' => 1.4, 'platforms' => array('MT4', 'MT5'), 'other_reg' => array('ASIC'), 'other_reg_count' => 1, 'instruments' => 'Forex, indices, commodities and share CFDs; group marketing cites 2,000+ instruments across brands, though the EU-facing offering is narrower.', 'account_types' => 'Cent, Classic, ECN, Prime and VIP tiers (availability varies by jurisdiction). Classic: minimum deposit $50, no commission, spreads from 1.4 pips. ECN: raw spreads from 0.0 pips, commission from $3.50/lot. Minimum deposits range from $5 to $5,000 across tiers, with demo and Islamic/swap-free accounts also offered.', 'execution_model' => 'Sources describe it inconsistently -- as a hybrid of dealing-desk, STP and ECN depending on account, while OneRoyal\'s own marketing describes itself simply as STP. This discrepancy wasn\'t resolved and is worth confirming directly.', 'withdrawal_deposit_note' => 'Over 50 payment methods are cited, with withdrawal fees said to vary by method. One source reports Neteller withdrawals being subject to an unusual 7-business-day wait after a deposit, though this wasn\'t independently corroborated elsewhere. Minimum deposit $5.', 'overnight_financing' => 'Islamic/swap-free accounts are available; no benchmark-rate-plus-markup methodology was found for standard accounts.', 'currency_conversion_fee' => 'Not found -- no specific fee or percentage was located.', 'inactivity_fee' => 'Not found after a targeted search -- genuinely unconfirmed either way.', 'customer_service_note' => '24/7 support via live chat, email and phone (5 dedicated lines), plus Instagram DM and Facebook Messenger, in multiple languages. Its Trustpilot rating is currently unavailable due to a stated breach of Trustpilot\'s guidelines, though individual reviews remain visible and are mixed -- five-star praise alongside one-star complaints about platform issues and bonus terms.', 'mobile_note' => 'Not found -- no App Store or Google Play rating was located.', 'education_note' => 'A "Knowledge Hub"/Academy offers articles, videos and market updates, with a named analyst hosting webinars and live sessions spanning forex basics to AI-in-trading topics; independent commentary on substance wasn\'t found.', 'blurb' => 'OneRoyal (formerly branded Royal/FXGiants) traces to a 2006-founded Sydney group whose Australian ASIC licence sits in a different legal entity than its CySEC-regulated European arm, Royal Financial Trading (Cy) Ltd.', 'cysec_note' => 'ASIC licence is held by a separate group entity, Royal Financial Trading Pty Ltd (Australia), not by the CySEC-licensed Cyprus entity. The group also holds VFSC (Vanuatu) and FSA (St. Vincent) licences via other entities -- both offshore/non-Tier-1, so excluded.', 'scores' => array( 'regulation' => 1.8, 'cost' => 4.44, 'platforms' => 2.6, 'track_record' => 2.39, 'overall' => 2.87 ), 'rank' => 52 ),
        array( 'slug' => 'iqbroker', 'name' => 'IQBroker', 'entity' => 'IQBroker Europe Ltd', 'cysec' => '247/14', 'founded' => 2013, 'hq' => 'Limassol, Cyprus', 'min_deposit_usd' => 10, 'min_deposit_display' => '$10', 'spread_eurusd' => 1.2, 'platforms' => array('Proprietary (Quadcode Markets platform)'), 'other_reg' => array('ASIC', 'SCB'), 'other_reg_count' => 2, 'instruments' => 'Forex, commodities, stock indices and cryptocurrencies via CFDs', 'account_types' => 'A simple structure: a Demo account ($10,000 in virtual funds, replenishable, no time limit) and a Real account activated from a $10 minimum deposit. The related IQCent brand may not share the same CySEC coverage as this entity -- worth confirming before treating them as interchangeable.', 'execution_model' => 'One independent source characterizes it as a market maker, with the broker providing liquidity and setting its own prices.', 'withdrawal_deposit_note' => 'No withdrawal fee from the broker itself (third-party/bank fees may apply). Minimum withdrawal $2. Processing: bank cards 1-10 business days, e-wallets usually within 24 hours (often minutes). A rule limits withdrawing more than the originally deposited amount back to the same card within 90 days -- any excess must go via e-wallet or bank transfer.', 'overnight_financing' => 'Percentage-based overnight fees are cited for specific instruments (e.g. small fractions of a percent on EUR/USD and gold), but these figures come from a secondary aggregator rather than the broker\'s own fee schedule, so treat them as indicative only. An Islamic/swap-free option is available for Sharia-compliant clients.', 'currency_conversion_fee' => 'Not found -- no specific fee or percentage was located.', 'inactivity_fee' => 'Not found.', 'customer_service_note' => 'Trustpilot rates it around 4.3/5. User comments praise ease of use and execution speed; complaints focus mostly on missing features (no MetaTrader integration, no copy trading) rather than fund-safety or withdrawal issues.', 'mobile_note' => 'Google Play shows a strong, well-documented figure: over 100 million installs and around 4.59/5 from roughly 710,000 ratings. An App Store-specific rating wasn\'t separately confirmed.', 'education_note' => 'The free demo account is the primary educational tool; no detailed independent commentary on formal courses or webinars was found beyond that.', 'blurb' => 'IQBroker Europe Ltd is the CySEC entity behind the rebranded Quadcode Markets platform (formerly IQ Option Europe), and it uses an in-house proprietary trading platform rather than MetaTrader or cTrader.', 'cysec_note' => 'ASIC and SCB registrations belong to other Quadcode/IQ Option group entities operating under the same brand, not confirmed to be the same legal entity as the CySEC-licensed IQBroker Europe Ltd.', 'scores' => array( 'regulation' => 2.6, 'cost' => 4.52, 'platforms' => 1.8, 'track_record' => 1.82, 'overall' => 2.86 ), 'rank' => 54 ),
        array( 'slug' => 'colmex-pro', 'name' => 'Colmex Pro', 'entity' => 'Colmex Pro Ltd', 'cysec' => '—', 'founded' => 2010, 'hq' => 'Limassol, Cyprus', 'min_deposit_usd' => 500, 'min_deposit_display' => '$500', 'spread_eurusd' => 1.5, 'platforms' => array('MT4', 'MT5', 'Proprietary (Colmex Pro 2.0)', 'Proprietary (MultiTrader)'), 'other_reg' => array(), 'other_reg_count' => 0, 'instruments' => '4,000+ CFDs and 3,000+ real US stocks with direct market access (NYSE, NASDAQ, AMEX), plus forex, indices and commodities CFDs', 'account_types' => 'Forex/non-equity CFD accounts across five tiers (deposits from $2,000 to $50,000, with per-lot commissions that appear unusually high and should be re-verified against Colmex\'s own current schedule before relying on them), plus separate equity/equity-CFD accounts split into tiered plans (Bronze through Diamond, from $500) and fixed plans (from $2,000-3,000). All include a personal account manager and are available in swap-free/Islamic variants.', 'execution_model' => 'Colmex Pro is known in the industry for US-stock direct-market-access-style trading via DAS Trader Pro, but this specific relationship couldn\'t be independently re-confirmed from a primary or reputable secondary source in this research pass -- treat it as an industry-known characteristic needing manual confirmation.', 'withdrawal_deposit_note' => 'No withdrawal fee reported. Minimum deposit figures conflict across sources (tiered entry points from $500 vs. other figures as high as $10,000 seen elsewhere) -- the tiered figures above are the more reliably sourced ones.', 'overnight_financing' => 'Not found -- no calculation methodology was located.', 'currency_conversion_fee' => 'Not found -- no specific fee or percentage was located.', 'inactivity_fee' => 'Sources conflict: some comparison pages state no inactivity fee applies, while another indicates a fee exists without specifying the amount -- unresolved.', 'customer_service_note' => 'Trustpilot rates it strongly and consistently, around 4.5-4.6/5 from 181 reviews. Reviewers specifically praise personalized account-manager support described as fast, smooth and personal; the company responds to reviews within about a week.', 'mobile_note' => 'Not found -- no app-store rating was located; qualitative reviews describing the platform as reliable and intuitive referred to the desktop/trading platform generally, not confirmed as mobile-specific.', 'education_note' => 'Not found -- no independent commentary on courses, webinars, or research tools was located.', 'blurb' => 'Distinguished by offering direct market access to real US stocks (not just CFDs) alongside standard forex/CFD trading, via its own proprietary Colmex Pro 2.0 and MultiTrader platforms.', 'scores' => array( 'regulation' => 1, 'cost' => 4.31, 'platforms' => 4.2, 'track_record' => 2.06, 'overall' => 2.85 ), 'rank' => 55 ),
        array( 'slug' => 'skilling', 'name' => 'Skilling', 'entity' => 'Skilling Ltd', 'cysec' => '357/18', 'seychelles' => 'SD042', 'founded' => 2016, 'hq' => 'Nicosia, Cyprus', 'min_deposit_usd' => 100, 'min_deposit_display' => '€100/$100/£100 (Standard account); €5,000/$5,000 for Premium account', 'spread_eurusd' => 0.8, 'platforms' => array('MT4', 'cTrader', 'TradingView', 'Proprietary (Skilling Trader)'), 'other_reg' => array(), 'other_reg_count' => 0, 'instruments' => '900-1,200+ CFDs across forex, indices, shares, commodities and crypto.', 'account_types' => 'Standard (minimum deposit $100, commission-free, spreads from 0.7 pips) and Premium (minimum deposit $5,000, spreads from 0.1 pips, commission from $35/million traded), with an Islamic/swap-free option also offered across its own proprietary platform, cTrader, and MT4.', 'execution_model' => 'Described as no-dealing-desk with both a "market maker" account and an "STP" account available, meaning execution style appears to vary by account tier, consistent with the Standard/Premium split. A roughly 0.05-second execution speed is marketed but not independently verified.', 'withdrawal_deposit_note' => 'Cards, e-wallets (Skrill, Neteller) and bank wire are supported. Deposits are generally instant for cards/e-wallets (2-7 business days for wire); withdrawals process in 1-48 hours for cards/e-wallets and several business days for wire. Deposits and withdrawals are generally fee-free except Skrill/Neteller, which may carry fees up to around 2.9%. Minimum withdrawal around $50/€50.', 'overnight_financing' => 'The Islamic account avoids swaps; no benchmark-plus-markup methodology was found for standard accounts.', 'currency_conversion_fee' => 'Not found -- searches returned only unrelated e-wallet conversion-fee information, not Skilling\'s own account-currency conversion policy.', 'inactivity_fee' => '£10 (or currency equivalent) after 12 months of dormancy, per one broker-comparison source; exact exemptions weren\'t detailed and should be confirmed against Skilling\'s own terms.', 'customer_service_note' => 'Trustpilot rates it around 4.2/5 from 432 reviews on one regional storefront. Detailed independent commentary on support hours and channels specifically wasn\'t found beyond the rating itself.', 'mobile_note' => 'One broker-comparison aggregator cites 4.2 on Android and 5.0 on iOS, though these figures weren\'t independently verified directly against the live App Store/Google Play listings. Skilling also offers copy trading with 800+ strategies.', 'education_note' => 'Offers forex calculators and trading videos, but no in-depth independent assessment of course or webinar substance was found.', 'blurb' => 'Skilling, co-founded in 2016 by former IG/Nordea/Cinnober executives, was acquired by INFINOX in late 2025, after which the brand continued operating with access to the wider INFINOX group\'s technology and licences.', 'cysec_note' => 'Skilling also holds an FSA Seychelles licence via a separate Seychelles entity and an FCA UK branch authorisation obtained in 2020 -- not counted here since sourcing did not clearly confirm the FCA authorisation is held by the same legal entity as the CySEC licence. Skilling was acquired by INFINOX in late 2025.', 'scores' => array( 'regulation' => 1, 'cost' => 4.66, 'platforms' => 4.2, 'track_record' => 1.57, 'overall' => 2.85 ), 'rank' => 56 ),
        array( 'slug' => 'fxview', 'name' => 'FXView', 'entity' => 'Charlgate Ltd', 'cysec' => '367/18', 'founded' => 2018, 'hq' => 'Limassol, Cyprus', 'min_deposit_usd' => 50, 'min_deposit_display' => '$50 (non-EU); €200 (EU clients), RAW ECN account', 'spread_eurusd' => 0, 'platforms' => array('MT5', 'ActTrader'), 'other_reg' => array('FSCA'), 'other_reg_count' => 1, 'instruments' => '500+ CFDs across forex, indices, commodities, 300+ share CFDs and cryptocurrencies', 'account_types' => 'RAW ECN (main live account, minimum deposit $50), Premium ECN (minimum deposit $5,000, for high-volume traders), a "Zulu" account for ZuluTrade copy-trading integration, and an Islamic account reportedly available to global clients only -- possibly excluding EU/CySEC clients, worth confirming directly.', 'execution_model' => 'Described as ECN/STP with spreads from 0 pips; swaps are generally negative on majors and minors, consistent with standard cost-of-carry rather than a specifically disclosed markup formula.', 'withdrawal_deposit_note' => 'Deposit methods include cards, bank transfer, Rapid Transfer, Skrill, Neteller, Klarna, Giropay, Przelewy24, Nordea Solo, and crypto (for global clients only); withdrawal methods include bank card, bank wire, Neteller, Skrill, and crypto. No deposit or withdrawal fees are charged by FXView, with withdrawal processing cited at around 1 business day.', 'overnight_financing' => 'No specific benchmark-plus-markup disclosure was found; an Islamic/swap-free account is available, subject to the eligibility caveat noted above.', 'currency_conversion_fee' => 'Not found -- no specific fee or percentage was located.', 'inactivity_fee' => 'Not found despite a dedicated search attempt.', 'customer_service_note' => 'Trustpilot rates it around 4.2/5 from 212 reviews -- mixed, with praise for fast withdrawals and customer service alongside complaints about withdrawal delays and deposit-bonus concerns.', 'mobile_note' => 'Runs its own apps ("Fxview Phone" on the App Store, "Fxview Droid" on Google Play) syncing with its desktop/web platform for account management and trading, but no numeric star rating was found for either.', 'education_note' => 'Only a generic Trustpilot mention of "great educational resources" was found, with no specifics on courses, webinars, or research tools identified -- unconfirmed beyond that general positive mention.', 'blurb' => 'Runs an ECN-only model (no MT4, only MT5 and ActTrader) with spreads from 0.0 pips plus commission, and recently added a full FSCA (South Africa) licence, though its earlier UK FCA licence has been revoked.', 'cysec_note' => 'Previously held a UK FCA licence (850138) which has since been revoked, so FCA is not listed as a current licence. Separately, CySEC reached a EUR50,000 settlement with Charlgate Ltd (FXView\'s CySEC entity) covering authorization-requirement lapses from 2020 through mid-2023, a client-fund-protection shortfall in September 2023, and a best-execution shortfall in July 2023, which Charlgate paid.', 'scores' => array( 'regulation' => 1.8, 'cost' => 4.99, 'platforms' => 2.6, 'track_record' => 1.41, 'overall' => 2.84 ), 'rank' => 57 ),
        array( 'slug' => 'naga', 'name' => 'NAGA', 'entity' => 'Naga Markets Europe Ltd', 'cysec' => '204/13', 'seychelles' => 'SD026', 'founded' => 2015, 'hq' => 'Hamburg, Germany (The NAGA Group AG, parent, listed on Frankfurt Stock Exchange as N4G0); Naga Markets Europe Ltd is the CySEC-regulated Cyprus entity', 'min_deposit_usd' => 50, 'min_deposit_display' => '$50', 'spread_eurusd' => 1.7, 'platforms' => array('MT4', 'MT5', 'Proprietary (NAGA Trader)'), 'other_reg' => array('FSCA'), 'other_reg_count' => 1, 'instruments' => '4,000+ tradable assets across forex, stocks, ETFs, commodities, indices and crypto, with built-in social/copy trading (NAGA Autocopy)', 'account_types' => 'Standard and ECN/Raw accounts, both available with an Islamic swap-free variant obtained by converting a standard account via a support request.', 'execution_model' => 'Disputed: NAGA states it is a market maker in parts of its own disclosures, which some trader commentary criticizes as inconsistent with STP-style language used elsewhere in its marketing -- not independently resolved either way.', 'withdrawal_deposit_note' => 'Card deposits around 10 minutes, e-wallet/crypto instant, wire 2-5 business days; withdrawals from 15 minutes up to 3 business days. Withdrawal fees range $0-5 depending on account tier; minimum withdrawal $50.', 'overnight_financing' => 'The Islamic account removes rollover swap but may carry an admin fee or wider spread as compensation; the standard (non-Islamic) swap calculation methodology wasn\'t found.', 'currency_conversion_fee' => 'Reported as no conversion fee, via a multi-currency account supporting EUR, USD, GBP, PLN and others -- not independently verified against NAGA\'s own fee schedule directly.', 'inactivity_fee' => 'Reported as applied after 90 days of no trading; the exact amount wasn\'t confirmed.', 'customer_service_note' => 'Mixed: praise for responsive phone/chat support and access to signals/webinars, alongside complaints about slow or unhelpful email support, login issues, and withdrawal/fund-availability disputes. Its Trustpilot status is reported inconsistently across sources -- around 3.8/5 from roughly 2,200 reviews in one place, versus "currently unavailable due to a guideline breach" with around 4,300 reviews in another.', 'mobile_note' => 'Reported around 4.4 on iOS and 3.8 on Android, a blended figure around 4.1.', 'education_note' => 'Offers webinars, video tutorials/courses, an economic calendar, market analysis, and signals, with reviewer ratings on these sub-items ranging from around 3.0 to 4.5/5. One source states a $250 deposit tier unlocks full education access, though this wasn\'t verified against an official pricing page.', 'blurb' => 'NAGA is the retail trading brand of Hamburg-based, Frankfurt Stock Exchange-listed The NAGA Group AG, built around integrated social and copy-trading features (NAGA Autocopy) alongside MT4/MT5.', 'cysec_note' => 'The wider NAGA brand also operates via other legal entities holding ADGM and Seychelles FSA licences for non-EU clients; separate companies from the CySEC-licensed Naga Markets Europe Ltd named here.', 'scores' => array( 'regulation' => 1.8, 'cost' => 4.31, 'platforms' => 3.4, 'track_record' => 1.65, 'overall' => 2.84 ), 'rank' => 58 ),
        array( 'slug' => 'fxcc', 'name' => 'FXCC', 'entity' => 'FX Central Clearing Ltd', 'cysec' => '121/10', 'founded' => 2010, 'hq' => 'Limassol, Cyprus', 'min_deposit_usd' => 0, 'min_deposit_display' => 'No minimum', 'spread_eurusd' => null, 'platforms' => array('MT4', 'MT5'), 'other_reg' => array(), 'other_reg_count' => 0, 'instruments' => 'Forex, commodities and CFDs via STP/ECN execution', 'account_types' => 'A single commission-free "ECN XL" account (variable spreads from 0.0 pips, lots from 0.01, leverage up to 1:500), plus demo, Islamic swap-free, and managed account options.', 'execution_model' => 'Described consistently as STP/ECN with no dealing desk, routing directly to interbank liquidity.', 'withdrawal_deposit_note' => 'Card and bank transfer deposits are free; card withdrawals are free; Skrill/Neteller withdrawals carry a 2.7% fee; other methods like bank wire cost $30-50. Minimum withdrawal $50; no minimum deposit.', 'overnight_financing' => 'Standard accounts incur nightly swap charges; the Islamic account has no swap, commission, or admin fee. The benchmark-plus-markup calculation methodology wasn\'t disclosed in sources found.', 'currency_conversion_fee' => 'Not found -- no specific fee or percentage was located.', 'inactivity_fee' => 'Reported as $5/month after roughly 3-4 months of inactivity, with a minor discrepancy in sources over the exact trigger period (90 vs. 120 days).', 'customer_service_note' => 'Ratings vary sharply by platform: Trustpilot shows a strong 4.5-4.6/5 (152 reviews, with the company replying to all negative reviews within about a week), while ForexPeaceArmy shows a much weaker 2.7/5 (60+ reviews) and REVIEWS.io shows 3.8/5 (300+ reviews) -- a notable disagreement between review platforms worth disclosing rather than picking one.', 'mobile_note' => 'Reported around 4.8 on iOS and 4.4 on Android; MT4 is the only mobile platform offered (no MT5 mobile app).', 'education_note' => 'Widely cited by reviewers as one of FXCC\'s strongest areas, with a learning centre offering articles, e-books, courses and calculators.', 'blurb' => 'One of the longer-established brokers in this group (founded 2010), FXCC runs its CySEC-regulated entity alongside a separate offshore entity licensed in Comoros, with only the CySEC entity segregating client funds.', 'cysec_note' => 'FXCC also operates a separate Comoros entity licensed by MISA (Mwali International Services Authorities, licence BFX2024085); Comoros is an offshore registry, not counted on the Tier-1 list, and per FXCC\'s own disclosures only the CySEC entity segregates client funds.', 'scores' => array( 'regulation' => 1, 'cost' => 5, 'platforms' => 2.6, 'track_record' => 2.06, 'overall' => 2.73 ), 'rank' => 60 ),
        array( 'slug' => 'fxprimus', 'name' => 'FXPrimus', 'entity' => 'Primus Global Ltd', 'cysec' => '261/14', 'founded' => 2009, 'hq' => 'Limassol, Cyprus', 'min_deposit_usd' => 15, 'min_deposit_display' => '$15 (PrimusCent); $1,000 (PrimusZERO)', 'spread_eurusd' => 1.5, 'platforms' => array('MT4', 'MT5', 'cTrader'), 'other_reg' => array(), 'other_reg_count' => 0, 'instruments' => '120-140+ CFDs spanning forex majors/minors/exotics, indices, precious metals, energies, global equities/ETFs and a handful of crypto pairs.', 'account_types' => 'PrimusClassic (no commission, spreads from around 1.5 pips), PrimusPRO (spreads from 0.3 pips plus $8/lot commission on MT5), PrimusZERO (near-zero spread plus commission), and PrimusCent, with an Islamic swap-free option available on Classic, Cent and Pro.', 'execution_model' => 'Described as a mixed STP/ECN-style model depending on account tier, though sources don\'t explicitly label each tier as one or the other. Platforms are MT4, MT5 and cTrader.', 'withdrawal_deposit_note' => 'Methods include Visa/Mastercard, bank wire, Skrill, Neteller, BTC and USDT. No deposit fees from FXPrimus itself (card processors may charge 1-3%). Processing from instant (crypto, under an hour) to 2 business days (cards) to 5 days (wire). Minimum deposit figures conflict across sources ($500 initial/$100 subsequent in one source vs. much lower figures for specific account tiers in another).', 'overnight_financing' => 'Islamic accounts are swap-free across Classic, Cent and Pro; the standard-account swap methodology wasn\'t found.', 'currency_conversion_fee' => 'Not found -- only generic, non-broker-specific information was located.', 'inactivity_fee' => 'Multiple sources state no inactivity fee is charged -- unusual among peers researched so far, worth double-checking against current terms.', 'customer_service_note' => 'Trustpilot shows a TrustScore of 3.5/5 from a thin base of 90 reviews, with about 40% of negative reviews answered, typically within 24 hours. One independent scorecard separately rates mobile apps 7.5/10 and education 6.5/10.', 'mobile_note' => 'No numeric app-store rating was found beyond the 7.5/10 aggregate score mentioned above.', 'education_note' => 'Reviewers disagree: one source says FXPrimus lacks both beginner and advanced educational video content, while another calls its research and education rich and professional.', 'blurb' => 'FXPrimus, founded in 2009 and based in Limassol, is regulated in the EU via Primus Global Ltd (CySEC 261/14) and offers MT4, MT5 and cTrader, with no currently confirmed Tier-1 regulator beyond CySEC.', 'cysec_note' => 'International entity (Primus Markets Intl Ltd) holds a Vanuatu VFSC license, excluded per the approved regulator list. Some sources report a prior FSCA (South Africa) license as revoked/no longer active, so it was not counted as currently held.', 'scores' => array( 'regulation' => 1, 'cost' => 4.4, 'platforms' => 3.4, 'track_record' => 2.14, 'overall' => 2.73 ), 'rank' => 61 ),
        array( 'slug' => 'squaredfinancial', 'name' => 'SquaredFinancial', 'entity' => 'Squared Financial (CY) Ltd', 'cysec' => '329/17', 'seychelles' => 'SD024', 'founded' => 2005, 'hq' => 'Nicosia/Limassol, Cyprus', 'min_deposit_usd' => 0, 'min_deposit_display' => '$0 (SquaredPro); $500-$5,000 (Elite account, figures vary by source)', 'spread_eurusd' => 1.2, 'platforms' => array('MT4', 'MT5'), 'other_reg' => array(), 'other_reg_count' => 0, 'instruments' => '2,000+ CFDs across forex, indices, shares, ETFs and commodities.', 'account_types' => 'SquaredPro (no minimum deposit, $0 commission) and SquaredElite (minimum $5,000, $5/lot commission), both using market execution, with a SwapFree Islamic variant available on the SF MT4 platform.', 'execution_model' => 'Market execution on both tiers; sources didn\'t specify ECN vs. STP vs. market-maker terminology beyond that general description.', 'withdrawal_deposit_note' => 'Methods include bank card, bank wire, BTC, Neteller, Skrill and USDT. No deposit fee; normal withdrawals are free aside from third-party costs. Minimum withdrawal $5, processing from 15 minutes up to 3 business days. Minimum deposit reported around $250 as of mid-2026, post-restructuring -- worth reconfirming given the firm\'s ongoing licence wind-down (see regulatory note above).', 'overnight_financing' => 'The SwapFree account removes interest on positions held over 24 hours; standard accounts reportedly apply a handling charge specifically for exotic pairs held more than 3 consecutive nights -- an unusually specific policy worth confirming against the current fee schedule given the firm\'s 2025 restructuring.', 'currency_conversion_fee' => 'Not found as a specific percentage; base currencies offered are USD, EUR, GBP and BTC.', 'inactivity_fee' => 'Reported inconsistently: one source lists no inactivity fee, while another cites a 2% withdrawal fee specifically triggered when no trading has occurred -- these may describe the same underlying mechanism differently; treat the 2% dormant-withdrawal charge as the more likely operative fact.', 'customer_service_note' => 'Trustpilot shows a TrustScore of 3.8/5 from 651 reviews -- notable given this coexists with the licence wind-down and fund-freeze events described above; several reviews specifically allege disabled MT4 accounts and inability to withdraw, with at least one describing the operation as lacking clarity on where client funds are held.', 'mobile_note' => 'An app relaunch/enhancement was announced via company press releases, but no independent app-store star rating was found.', 'education_note' => 'Some reviewers praise a free "Trading Academy," though this isn\'t independently corroborated by a neutral reviewer site.', 'blurb' => 'Squared Financial (CY) Ltd formally began a voluntary, structured wind-down and surrender of its CySEC licence (329/17) in 2025 -- including a stop to onboarding new clients -- after CySEC had previously fined the firm EUR35,000 over CFD marketing practices to retail clients, and after reports of frozen partner funds.', 'cysec_note' => 'This entity began a voluntary, structured wind-down and surrender of its CySEC licence in 2025 and has reportedly stopped onboarding new clients, following a prior CySEC fine over CFD marketing practices and reports of frozen partner funds. CySEC lists this licence as under examination for voluntary renunciation -- confirm current regulatory status directly with the broker and the CySEC register before relying on it. Group also operates an offshore Seychelles entity, not Tier-1 and a separate legal entity from the CySEC one.', 'scores' => array( 'regulation' => 1, 'cost' => 4.52, 'platforms' => 2.6, 'track_record' => 2.47, 'overall' => 2.67 ), 'rank' => 62 ),
        array( 'slug' => 'capex-com', 'name' => 'CAPEX.com', 'entity' => 'Key Way Investments Ltd', 'cysec' => '292/16', 'seychelles' => 'SD020', 'seychelles_note' => 'single-source; provisional', 'founded' => 2016, 'hq' => 'Nicosia, Cyprus', 'min_deposit_usd' => 100, 'min_deposit_display' => '$100', 'spread_eurusd' => 1.8, 'platforms' => array('MT5', 'Proprietary (CAPEX WebTrader)'), 'other_reg' => array('FSCA'), 'other_reg_count' => 1, 'instruments' => 'Marketed as 5,000+ tradeable assets, including real stocks/ETFs alongside CFDs on forex, indices and commodities', 'account_types' => 'Essential, Original and Signature tiers, all with leverage up to 1:300; differences beyond the leverage cap (e.g. spreads or minimums per tier) weren\'t found.', 'execution_model' => 'Described by one source as a "non-advisory/executionary broker"; not framed in sources found as specifically STP, ECN, or market-maker.', 'withdrawal_deposit_note' => 'Reported as $0 deposit and $0 withdrawal fee; minimum deposit $100 as of mid-2026. Specific payment methods and processing times weren\'t found.', 'overnight_financing' => 'Islamic/swap-free account availability and terms for this broker specifically weren\'t found.', 'currency_conversion_fee' => 'General conversion-fee mechanics (a markup plus service charge) are described but no CAPEX-specific percentage was found. Base currencies offered include USD, EUR, GBP, ZAR and BTC.', 'inactivity_fee' => 'Reported differently by client type: $25 (or equivalent) after 12 months of inactivity for EU clients, versus a notably harsher $50 after just 60 days for non-EU clients. As the entity reviewed here is the EU/CySEC entity, the $25/12-month policy should apply, though this is worth confirming directly.', 'customer_service_note' => 'Not found -- no CAPEX-specific support hours or independent service-quality commentary was located.', 'mobile_note' => 'Not found -- searches returned unrelated apps with similar names rather than a confirmed CAPEX.com rating.', 'education_note' => 'Described generically as offering educational lessons, AI-driven sentiment analytics, news sentiment, and free/unlimited demo accounts across all tiers, but no independent (non-marketing) assessment of depth was found.', 'blurb' => 'CAPEX.com (Key Way Investments Ltd) is one of the few brokers in this set marketing direct stock/ETF investing alongside CFDs, with a fixed EUR/USD spread of about 1.8 pips via its own WebTrader platform or MT5; CySEC also reached a roughly EUR120k settlement with Key Way Investments over past compliance issues.', 'cysec_note' => 'FSCA regulation applies to a separate group entity operating under the same CAPEX brand, plus non-Tier-1 licences (ADGM UAE, Seychelles FSA) for other group entities -- not the CySEC entity Key Way Investments Ltd itself.', 'scores' => array( 'regulation' => 1.8, 'cost' => 4.26, 'platforms' => 2.6, 'track_record' => 1.57, 'overall' => 2.65 ), 'rank' => 63 ),
        array( 'slug' => 'finansero', 'name' => 'Finansero', 'entity' => 'Global Trade CIF Ltd', 'cysec' => '190/13', 'founded' => 2012, 'hq' => 'Nicosia, Cyprus', 'min_deposit_usd' => 200, 'min_deposit_display' => '$200 / €200', 'spread_eurusd' => 0.6, 'platforms' => array('MT4', 'Proprietary (XCITE)'), 'other_reg' => array(), 'other_reg_count' => 0, 'instruments' => '300+ assets across forex, indices, commodities and shares CFDs', 'account_types' => 'One review source describes Standard (EUR200 minimum), Premium (EUR5,000 minimum), and VIP (EUR20,000 minimum) tiers with escalating support levels -- not corroborated elsewhere, so treat as single-source.', 'execution_model' => 'Not found -- no source described an ECN/STP/market-maker/DMA classification.', 'withdrawal_deposit_note' => 'Per one source: bank transfer deposits take 2-5 business days and withdrawals 3-7 business days (bank fees may apply); e-wallets deposit instantly and withdraw within 24-48 hours with no broker fee reported. First-time withdrawals reportedly require extra ID/AML documentation.', 'overnight_financing' => 'Not found; an Islamic/swap-free account wasn\'t confirmed either way.', 'currency_conversion_fee' => 'Not found.', 'inactivity_fee' => 'Not found despite multiple searches.', 'customer_service_note' => 'One source describes 24/5 multilingual (English, Spanish, French, German, Arabic, Chinese, Russian) live chat, email and phone support -- single-source, not independently corroborated. Separately, one Trustpilot review rated the service 1/5, describing a lured investment scheme and a loss exceeding PLN30,000 -- see the serious regulatory caution in this broker\'s main blurb.', 'mobile_note' => 'Not found.', 'education_note' => 'Only a knowledge base, FAQ and platform tutorials were reported -- thin relative to other brokers researched so far, with no independent assessment of substance found.', 'blurb' => 'Important caution before anything else: independent sources on Finansero sharply disagree. Several comparison sites describe Global Trade CIF Ltd as a legitimately CySEC-licensed firm (licence 190/13, active since 2013), but a detailed ForexPeaceArmy complaint thread alleges the "Global Trade CIF Ltd / Finansero" a user dealt with had no valid licence from any recognized authority, was flagged by Russia\'s central bank, provided no verifiable contact details, and ran a fraud scheme -- a separate Trustpilot review independently calls it a scam. We could not determine whether this is a clone/impersonation of the genuine licensed entity or the same company, and this is unresolved. Verify directly against the live CySEC register (cysec.gov.cy) for licence 190/13 before relying on anything else in this review. Finansero also offers its own proprietary XCITE platform alongside MT4, with a 9-tier retail account structure based on funding/volume.', 'cysec_note' => 'See the caution above -- this licence number is reported as active by some sources, but a serious, unresolved fraud allegation exists concerning an entity using this same name. Confirm directly with CySEC before trusting any claim about this broker, including this site\'s own cysec field.', 'scores' => array( 'regulation' => 1, 'cost' => 4.72, 'platforms' => 2.6, 'track_record' => 1.9, 'overall' => 2.62 ), 'rank' => 65 ),
        array( 'slug' => 'finalto', 'name' => 'Finalto', 'entity' => 'Finalto EU Ltd', 'cysec' => '264/15', 'fca' => null, 'fca_note' => 'FCA-licensed; firm reference number not independently confirmed.', 'founded' => null, 'hq' => 'London, UK (Finalto EU Ltd\'s registered office is in Nicosia, Cyprus)', 'min_deposit_usd' => null, 'min_deposit_display' => null, 'spread_eurusd' => null, 'platforms' => array('MT4', 'MT5'), 'other_reg' => array('ASIC'), 'other_reg_count' => 1, 'instruments' => 'Liquidity, prime-of-prime and white-label solutions across forex and CFDs on indices, commodities and equities, aimed at B2B/institutional clients rather than direct retail sign-ups', 'account_types' => 'No retail account-tier structure was found -- Finalto operates as a B2B prime-of-prime/liquidity provider serving brokers, hedge funds, family offices and institutions via a single cross-margined account covering 800+ instruments, not retail standard/pro/Islamic/demo tiers.', 'execution_model' => 'Institutional prime brokerage and liquidity provision with sub-2-microsecond matching-engine execution across its own infrastructure -- effectively an ECN/DMA-style liquidity model for its broker clients, not a retail execution model, so it\'s not meaningful to ask whether this varies "by account type."', 'withdrawal_deposit_note' => 'Not found -- B2B settlement terms aren\'t publicly disclosed, as is typical for institutional contracts.', 'overnight_financing' => 'Not found -- not publicly disclosed.', 'currency_conversion_fee' => 'Not found.', 'inactivity_fee' => 'Not found -- not applicable given there\'s no retail account structure.', 'customer_service_note' => 'Not found in independent retail-review sources, as expected since Finalto isn\'t reviewed by retail-focused sites like Trustpilot or ForexBrokers.com in the way retail brokers are.', 'mobile_note' => 'Not found.', 'education_note' => 'Not found -- Finalto publishes institutional/trade-press content rather than retail education.', 'blurb' => 'Finalto operates primarily as a B2B liquidity and prime-of-prime provider rather than a direct-to-retail sign-up broker, with offices across London, Cyprus, Dubai, Singapore and Sydney and no publicly disclosed retail minimum deposit or spread figures.', 'scores' => array( 'regulation' => 2.6, 'cost' => null, 'platforms' => 2.6, 'track_record' => null, 'overall' => 2.6 ), 'rank' => 66 ),
        array( 'slug' => 'trading-212', 'name' => 'Trading 212', 'entity' => 'Trading 212 Markets Ltd', 'cysec' => '398/21', 'fca' => '609146', 'founded' => 2004, 'hq' => 'London, UK', 'min_deposit_usd' => 1.1, 'min_deposit_display' => '€1', 'spread_eurusd' => 2.7, 'platforms' => array('Proprietary'), 'other_reg' => array(), 'other_reg_count' => 0, 'instruments' => 'Forex, stocks, ETFs, commodities, indices, crypto CFDs', 'account_types' => 'Invest (general taxable investing), Stocks & Shares ISA (UK tax-free wrapper, GBP20,000/year allowance), Cash ISA (interest-bearing, flexible), and a CFD account (leveraged derivatives). No Islamic/swap-free account was found advertised, likely reflecting its UK/EU retail-investing focus.', 'execution_model' => 'For listed equities and ETFs, Trading 212 acts as a Systematic Internaliser (market maker/counterparty for its own clients). For crypto, it uses STP routed through a third-party prime broker rather than internalizing. For CFDs, it acts as counterparty and hedges its exposure in the underlying market -- the CFD business is described as its primary profit engine.', 'withdrawal_deposit_note' => 'No deposit or withdrawal fees (Trading 212 absorbs transfer costs). Methods include bank transfer, debit/credit card, Apple/Google Pay, PayPal, Skrill, Giropay and iDEAL. Minimum deposit around $10; minimum withdrawal around $1 (or 1 GBP/EUR equivalent). Processing: e-wallets up to 24 hours, cards 2-3 business days, bank transfer 1-5 business days depending on source.', 'overnight_financing' => 'Applies to CFD positions, based on the relevant benchmark rate for the instrument\'s currency plus a broker markup (exact markup percentage not disclosed); can be a charge or a credit depending on the rate differential. An Islamic/swap-free account wasn\'t found/confirmed to exist.', 'currency_conversion_fee' => '0.15% on Invest/ISA accounts for cross-currency share purchases, charged on both buy and sell; the CFD account\'s currency conversion fee is reported higher, around 0.5%. The fee can be avoided by holding the relevant currency directly in a multi-currency wallet.', 'inactivity_fee' => 'None -- multiple independent sources confirm no inactivity fee is charged.', 'customer_service_note' => 'Trustpilot rates it around 4.6/5 ("Excellent") from roughly 86,000 reviews, but a recurring, well-documented complaint theme is slow live-chat/support response times during high-volume periods, sometimes multi-hour or multi-day; Trading 212 has publicly acknowledged the delays and said it\'s expanding its support team. UK Financial Ombudsman decisions also show complaint volume around technical issues and trading restrictions.', 'mobile_note' => 'App Store rating around 4.6-4.7/5 (381,000+ ratings); Google Play notably lower around 3.9/5 -- a meaningful iOS/Android gap. Independent reviewers generally rate the app highly for ease of use and design.', 'education_note' => 'Assessed by independent reviewers as thin -- share-trading-focused video content exists, but reviewers note no webinars, no on-demand archive, and limited content on funds or retirement; research tools cover shares, ETFs and CFDs plus portfolio allocation, with a useful economic calendar, but substantive research is flagged as a weakness.', 'blurb' => 'Very low minimum deposit and a well-regarded no-frills app, but wider EUR/USD spreads and only one platform option.', 'scores' => array( 'regulation' => 1.8, 'cost' => 3.92, 'platforms' => 1.8, 'track_record' => 2.55, 'overall' => 2.59 ), 'rank' => 67 ),
        array( 'slug' => 'purple-trading', 'name' => 'Purple Trading', 'entity' => 'L.F. Investment Ltd', 'cysec' => '271/15', 'fca' => null, 'fca_note' => 'A UK FCA authorization number is cited by third-party sources; could not independently confirm whether this is a full permission or a passporting-era registration.', 'seychelles' => 'SD041', 'founded' => 2014, 'hq' => 'Limassol, Cyprus', 'min_deposit_usd' => null, 'min_deposit_display' => null, 'spread_eurusd' => 1.3, 'platforms' => array('MT4', 'cTrader'), 'other_reg' => array(), 'other_reg_count' => 0, 'instruments' => 'CFDs on forex and commodities (fuller instrument range not independently confirmed)', 'account_types' => 'ECN (standard/default real account, raw spreads plus per-lot commission), STP (no per-volume commission, wider spreads, aimed at swing/position traders), and a Managed Account tier linking clients to passive ETF portfolios and professional-trader-run strategies (a smaller version available from EUR100). A demo account is offered; an Islamic account is not.', 'execution_model' => 'ECN and STP, varying by the two account types above; no dealing-desk or market-maker model is claimed.', 'withdrawal_deposit_note' => 'Free for card deposits/withdrawals and for EUR/CZK/PLN bank transfers; a 0.5% fee applies for other currencies. Processing is reported from 15 minutes up to 3 business days.', 'overnight_financing' => 'Standard overnight swap applies; there\'s no Islamic/swap-free exemption since no Islamic account exists. The specific benchmark-plus-markup calculation methodology wasn\'t found.', 'currency_conversion_fee' => '0.45% applied when an instrument\'s quote currency differs from the account\'s base currency.', 'inactivity_fee' => 'EUR10/month after 6 months of account inactivity, per a comparison-site summary -- not independently verified directly against Purple Trading\'s own current fee-schedule document.', 'customer_service_note' => 'Mixed independent commentary: one review praises support as fast and pro-client, while a Forex Peace Army-linked review calls it unresponsive. Trustpilot shows inconsistent scores by region (3.2/5 from a single review versus 3.5/5 from 114 reviews on a different country\'s Trustpilot) -- treat these as low-sample and not fully reliable.', 'mobile_note' => 'Purple Trading doesn\'t appear to publish its own branded app -- clients use standard MT4 and cTrader mobile apps. Caution: an app called "DXtrade Purple Trading Prop" by a different developer (AXSE Brokerage Ltd) was found in search results but isn\'t confirmed to be affiliated with L.F. Investment Ltd\'s Purple Trading and shouldn\'t be attributed to this broker.', 'education_note' => 'Several independent reviewers cite good education content as a strength, though no specifics on webinars or courses were found to substantiate this further.', 'blurb' => 'Purple Trading (L.F. Investment Ltd) reportedly paid CySEC roughly EUR150,000 to settle allegations of lapses in its retail CFD offering, according to Finance Magnates reporting; minimum deposit figures for its standard/STP account conflict across sources so are left unreported here.', 'scores' => array( 'regulation' => 1.8, 'cost' => 3.96, 'platforms' => 2.6, 'track_record' => 1.73, 'overall' => 2.59 ), 'rank' => 68 ),
        array( 'slug' => 'fxoro', 'name' => 'FXORO', 'entity' => 'MCA Intelifunds Ltd', 'cysec' => '126/10', 'seychelles' => 'SD046', 'founded' => null, 'hq' => 'Limassol, Cyprus (Petrou Tsirou 82, Mesa Geitonia, 3076 Limassol)', 'min_deposit_usd' => 100, 'min_deposit_display' => '$100', 'spread_eurusd' => 2, 'platforms' => array('MT4', 'Proprietary (FXORO App)'), 'other_reg' => array(), 'other_reg_count' => 0, 'instruments' => null, 'account_types' => 'Three tiers by spread/execution type: Fix (fixed spreads, no commission, beginner-oriented), Floating/Variable (floating spreads, no commission, around 1.2 pips minimum on EUR/USD per one source), and ECN (raw/tight spreads plus a fixed commission, e.g. around $6/EUR5/£4 per lot per one source). An Islamic/swap-free option is reportedly available across account types, plus a demo account.', 'execution_model' => 'Dealing-desk-style fixed spreads on the Fix account versus ECN execution with direct market pricing on the ECN account, with commission charged only on the ECN tier.', 'withdrawal_deposit_note' => 'Minimum deposit reported at £200, higher than many competitors. Deposit methods (bank wire, cards, e-wallets) are reported free, but withdrawal fees apply with the exact amount not specified in sources found; one reviewer explicitly notes FXORO isn\'t transparent about its deposit and withdrawal fees.', 'overnight_financing' => 'Swap is reportedly charged on positions held between 23:00 and 08:00 (GMT+2) per one source; the benchmark-plus-markup calculation methodology wasn\'t disclosed.', 'currency_conversion_fee' => 'Not found -- no specific fee percentage was located.', 'inactivity_fee' => 'One source reports a $25 charge after 3 months of no activity, followed by $100/year ongoing -- this wasn\'t independently cross-confirmed by a second source and should be verified against FXORO\'s current terms.', 'customer_service_note' => 'One independent reviewer describes customer support as disappointing, with an unresponsive live chat service. A Trustpilot rating found under "FXORO Global" (fxoroglobal.com, 3.5/5, 11 reviews) belongs to a separate, Seychelles-licensed entity (ORO Fintech Limited) and shouldn\'t be cited for this CySEC entity without further verification.', 'mobile_note' => 'iOS and Android apps exist (MT4 only -- MT5 isn\'t offered per one reviewer); no App Store or Google Play rating figure was found specifically for this entity.', 'education_note' => 'One independent reviewer states FXORO\'s educational resources could be improved to better support new traders, and notes the absence of copy-trading tools -- assessed as below-average overall by that source.', 'blurb' => 'MCA Intelifunds Ltd (FXORO) is in the process of voluntarily renouncing CySEC licence 126/10 and has stated it will cease providing investment and ancillary services effective 24 October 2025.', 'cysec_note' => 'CySEC lists this licence as under examination for voluntary renunciation -- confirm current regulatory status directly with the broker and the CySEC register before relying on it. Separately, CySEC fined MCA Intelifunds EUR360,000 in April 2024 following a September 2022 inspection, covering failures to act fairly/professionally in clients\' best interest, inadequate compliance policies, failure to collect client knowledge/experience information, product-suitability failures, and failure to warn on inappropriate products. Note also: "FXORO Global" (fxoroglobal.com) is a separate, Seychelles FSA-licensed entity (ORO Fintech Limited) -- reviews and ratings for that domain should not be attributed to this CySEC entity.', 'scores' => array( 'regulation' => 1, 'cost' => 4.18, 'platforms' => 2.6, 'track_record' => null, 'overall' => 2.59 ), 'rank' => 69 ),
        array( 'slug' => 'iforex-europe', 'name' => 'iFOREX Europe', 'entity' => 'ICFD Ltd', 'cysec' => '143/11', 'founded' => 1996, 'hq' => 'Limassol, Cyprus', 'min_deposit_usd' => 100, 'min_deposit_display' => '$100', 'spread_eurusd' => 1.8, 'platforms' => array('Proprietary (iFOREX/FXnet platform)'), 'other_reg' => array(), 'other_reg_count' => 0, 'instruments' => '750+ CFD instruments including ~90 forex pairs, stock CFDs, commodities, indices, ETFs and cryptocurrencies.', 'account_types' => 'Two retail tiers -- Standard Mini and VIP -- differing by minimum deposit and service level, plus a $5,000 virtual-balance demo account. No Islamic account was confirmed.', 'execution_model' => 'Zero-commission, spread-based pricing with no ECN/raw-spread tier found -- effectively a market-maker/dealing-desk-style model typical of iFOREX\'s CFD and share-CFD products; not confirmed to vary by account type.', 'withdrawal_deposit_note' => 'Minimum deposit $100; minimum withdrawal reported at $100 elsewhere, though sources disagree slightly on whether that figure applies to deposits only or both. Methods include bank card, bank wire, Bitcoin, Ethereum, Tether, Neteller and Skrill, with fees varying by method (some free).', 'overnight_financing' => 'Overnight financing on leveraged CFDs reportedly starts at 5% per annum for indices and 2.5% per annum for commodities and crypto, per one source; the exact benchmark-plus-markup methodology wasn\'t disclosed, and an Islamic/swap-free exemption wasn\'t confirmed.', 'currency_conversion_fee' => 'Not found -- no specific fee or percentage was located.', 'inactivity_fee' => '$15 charged quarterly after 12 months of dormancy, per one source.', 'customer_service_note' => 'Trustpilot shows 4.5/5 from 114 reviews, with the company replying to all negative reviews -- a notably responsive pattern. One independent review site separately rates its customer support 4.6/5.', 'mobile_note' => 'One independent reviewer rated the mobile app 7.5/10, describing it as functional but not best-in-class; no specific App Store or Google Play star rating was found.', 'education_note' => 'Assessed as average to below-average: reviewers note beginner-level videos exist, but advanced education resources and webinars are not offered.', 'blurb' => 'iFOREX is a long-running CFD brand dating to 1996 whose EU-facing entity, ICFD Ltd, has been CySEC-licensed since 2011 and trades through a proprietary platform rather than MetaTrader.', 'cysec_note' => 'No Tier-1/well-regarded regulator confirmed for ICFD Ltd itself; a BVI FSC license exists but belongs to a separate group entity (Formula Investment House Ltd), and BVI is not on the approved regulator list. Separately, CySEC fined ICFD Ltd EUR138,000 for providing services beyond its authorized scope (including unlicensed investment advice), not acting in clients\' best interest, failing to properly disclose CFD risk, and allegedly encouraging clients not to disclose their trading experience in a way that would circumvent suitability checks.', 'scores' => array( 'regulation' => 1, 'cost' => 4.26, 'platforms' => 1.8, 'track_record' => 3.2, 'overall' => 2.58 ), 'rank' => 70 ),
        array( 'slug' => 'errante', 'name' => 'Errante', 'entity' => 'Notely Trading Ltd', 'cysec' => '—', 'seychelles' => 'SD038', 'founded' => 2018, 'hq' => 'Nicosia, Cyprus (registered office: 30 Karpenisiou, 1077 Nicosia)', 'min_deposit_usd' => 50, 'min_deposit_display' => '$50', 'spread_eurusd' => 1.5, 'platforms' => array('MT4', 'MT5', 'cTrader'), 'other_reg' => array(), 'other_reg_count' => 0, 'instruments' => '350+ instruments including roughly 55 forex pairs, 200+ stock CFDs, ~30 cryptocurrencies, plus indices and commodities', 'account_types' => 'Standard (EUR50 minimum deposit), Premium (EUR1,000), VIP (EUR5,000), and Tailor Made (EUR15,000) tiers, with negative balance protection and segregated funds claimed across all. An Islamic account wasn\'t confirmed either way.', 'execution_model' => 'Described by the broker and in award coverage as STP, ECN, NDD and DMA (it won a "Best ECN/STP Broker 2022" industry award) -- these are broker-asserted/trade-press claims rather than independently audited facts.', 'withdrawal_deposit_note' => 'No fee for bank wire or card; a 1% fee applies to e-wallet withdrawals. A notable, atypical penalty clause: withdrawing more than 80% of a deposit within 48 hours without significant trading activity triggers an additional 3% penalty fee.', 'overnight_financing' => 'Swap is instrument-specific, with example figures cited for individual pairs by one source, though these are point-in-time figures not independently re-verified and likely to be stale -- treat specific swap numbers as illustrative only.', 'currency_conversion_fee' => 'Not found -- no specific fee or percentage was located.', 'inactivity_fee' => 'A one-time $15 maintenance fee after 150 days of inactivity, followed by an ongoing $5/month charge -- a relatively aggressive, early-triggering policy compared to the 6-12 month norms seen at most peers.', 'customer_service_note' => 'Not found -- no independent commentary on support quality or hours was located.', 'mobile_note' => 'One source cites unusually high ratings (around 5.0 on iOS, 4.9 on Android) for its MT4/MT5 mobile apps, but these figures look potentially unreliable (small sample sizes are common for niche broker apps) and should be independently re-checked against the live store listings before relying on them.', 'education_note' => 'Described generically by one comparison source as offering a wide selection of educational content and trading tools for beginners, with no specifics on courses or webinar cadence found.', 'blurb' => 'Errante is a Cyprus-based broker established around 2018 that runs a separate, non-CySEC entity (Errante Securities (Seychelles) Ltd) for clients outside the EU/EEA.', 'cysec_note' => 'Worth knowing: Japan\'s FSA, Indonesia\'s BAPPEBTI, and WikiFX have each flagged activity associated with the broader Errante brand (clone-address warnings, a blocked domain, and recurring complaints about cancelled profitable trades). These warnings and complaints concern the brand\'s offshore affiliates (Errante Trading LLC in St Vincent, and Errante Securities (Seychelles) Ltd) rather than being confirmed specifically against this CySEC-regulated entity, Notely Trading Ltd -- but the shared branding makes it worth confirming which entity you\'d actually be contracting with before relying on this review.', 'scores' => array( 'regulation' => 1, 'cost' => 4.39, 'platforms' => 3.4, 'track_record' => 1.41, 'overall' => 2.58 ), 'rank' => 71 ),
        array( 'slug' => 'liteforex', 'name' => 'LiteForex', 'entity' => 'Liteforex (Europe) Ltd', 'cysec' => '093/08', 'founded' => 2005, 'hq' => 'Limassol, Cyprus', 'min_deposit_usd' => 50, 'min_deposit_display' => '$50', 'spread_eurusd' => 2, 'platforms' => array('MT4', 'MT5'), 'other_reg' => array(), 'other_reg_count' => 0, 'instruments' => null, 'account_types' => 'Classic (0% commission, spread markup, floating from around 1.8 pips on MT5 per one source) and ECN (flat $5 round-turn commission per lot, floating spreads from around 0.1 pips). Islamic/swap-free accounts are offered, but LiteForex explicitly reserves the right to begin charging a servicing fee on Islamic accounts at any time, and has previously applied special daily fees to swap-free accounts holding oil positions during periods of oil-market stress -- a meaningful disclosure since "swap-free" doesn\'t mean fee-free in every case here.', 'execution_model' => 'ECN execution on the ECN account; the Classic account appears to be a dealing-desk/spread-markup model.', 'withdrawal_deposit_note' => 'Minimum deposit $50 for both account types. Minimum transaction $1 for e-wallets, $10 for cards; card withdrawals reportedly carry a 3.5% fee with a $1.01 minimum. Deposit fees are reimbursed for local methods, which process instantly. Funding via Mastercard/Visa, Skrill and Neteller.', 'overnight_financing' => 'Standard swap applies on non-Islamic accounts; Islamic accounts avoid the standard swap but are subject to the broker\'s discretionary servicing/oil-contract fees noted above.', 'currency_conversion_fee' => 'Not found -- no specific fee or percentage was located.', 'inactivity_fee' => 'Not found specifically for this entity.', 'customer_service_note' => 'One comparison source describes 24/5 multilingual support with a personal manager assigned to each trader -- a positive claim that isn\'t independently verified by complaint-tracking sources, as no Trustpilot-specific data was found for this exact entity.', 'mobile_note' => 'Described by one reviewer as simple and ideal for newcomers, with technical-analysis tools and copy-trading features, but no specific App Store or Google Play star rating was found for this entity.', 'education_note' => 'One review source (ranking it 8th among CFD brokers compared, at 3.7/5) describes a rich education centre with daily analysis and quality training guides -- generally positive but not deeply substantiated across multiple independent sources.', 'blurb' => 'LiteForex says it pioneered cent trading accounts with deposits as low as $1 for its international brand, but its CySEC-regulated Cyprus entity\'s Classic account requires a $50 minimum deposit with spreads from 2 pips.', 'cysec_note' => 'LiteForex/LiteFinance\'s other registered entities (Marshall Islands, St Vincent and the Grenadines) are not Tier-1 regulators.', 'scores' => array( 'regulation' => 1, 'cost' => 4.19, 'platforms' => 2.6, 'track_record' => 2.47, 'overall' => 2.57 ), 'rank' => 73 ),
        array( 'slug' => 'scope-markets', 'name' => 'Scope Markets', 'entity' => 'SM Capital Markets Ltd', 'cysec' => '339/17', 'seychelles' => 'SD079', 'seychelles_note' => 'single-source; provisional', 'founded' => 2014, 'hq' => 'Limassol, Cyprus', 'min_deposit_usd' => 200, 'min_deposit_display' => '$200 (EU); Standard account cited elsewhere at $500', 'spread_eurusd' => 0.7, 'platforms' => array('MT4', 'MT5'), 'other_reg' => array(), 'other_reg_count' => 0, 'instruments' => 'Marketing cites up to 40,000 instruments group-wide across forex (70+ pairs), indices, shares (2,000+), energies, metals and commodities, via a network of separately regulated regional entities.', 'blurb' => 'Scope Markets is a group brand where the CySEC-licensed EU entity (SM Capital Markets Ltd) is legally separate from its South African (FSCA) and Kenyan (CMA) sister entities and from an offshore Belize entity.', 'cysec_note' => 'The Scope Markets group holds FSCA (South Africa) and CMA Kenya authorisations, but these are held by separate group entities (Scope Markets SA (Pty) Ltd and SCFM Ltd respectively), not by SM Capital Markets Ltd (the CySEC entity). The group\'s Belize entity and Seychelles FSA licence are offshore/non-Tier-1 and excluded.', 'scores' => array( 'regulation' => 1, 'cost' => 4.68, 'platforms' => 2.6, 'track_record' => 1.73, 'overall' => 2.57 ), 'rank' => 74 ),
