        array( 'slug' => 'fxtm', 'name' => 'FXTM', 'entity' => 'Exinity Limited (also trading as ForexTime)', 'cysec' => null, 'cysec_note' => 'FXTM\'s former CySEC-licensed EU entity, Forextime Ltd, ceased EU operations on 31 December 2023 and had its CIF authorisation formally withdrawn by CySEC effective 20 May 2024 following voluntary renunciation. Exinity Limited, the entity reviewed here, is licensed instead by the Mauritius FSC (Investment Dealer Licence C113012295) -- a materially different protection regime with no EU-style investor compensation scheme, so this broker should not be treated as EU-regulated.', 'fca' => '777911', 'fca_note' => 'The FCA has published a warning about a clone firm impersonating FXTM/Exinity -- verify you are dealing with Exinity UK Ltd specifically, and confirm current onboarding availability before relying on this entity.', 'seychelles' => null, 'seychelles_note' => 'FSA Seychelles-licensed (widely reported); the specific SD licence number could not be independently confirmed in this research pass.', 'founded' => 2011, 'hq' => 'Limassol, Cyprus (global offices)', 'min_deposit_usd' => null, 'min_deposit_display' => null, 'spread_eurusd' => null, 'platforms' => array('MT4', 'MT5', 'Proprietary (FXTM Trader)'), 'other_reg' => array('FSCA'), 'other_reg_count' => 1, 'instruments' => null, 'account_types' => 'Reported as including a Cent/Micro account (minimum $10) and Advantage/Advantage Plus tiers (minimum $500); execution models are described inconsistently across sources as spanning STP, ECN and market-maker depending on account, without a clean per-tier attribution.', 'execution_model' => 'Not cleanly attributed by account type in sources found -- treat the STP/ECN/market-maker classification as unresolved rather than settled.', 'withdrawal_deposit_note' => 'A wide range of methods is supported (bank transfer, cards, UPI, M-Pesa, Google Pay, Skrill, Neteller, PerfectMoney, and various regional options). Deposit fee $0, withdrawal fee reported around $3, with withdrawals processed from as little as $5 and typically completed within about 30 minutes.', 'overnight_financing' => 'An Islamic swap-free account is available; the broker-specific swap calculation methodology wasn\'t found.', 'currency_conversion_fee' => 'Not found -- no specific fee or percentage was located.', 'inactivity_fee' => '$10 after 3 months (90 days) of no trading, per multiple sources.', 'customer_service_note' => 'Trustpilot shows a notably weak aggregate around 2.5/5 from roughly 1,100 reviews -- lower than most peers researched so far.', 'mobile_note' => 'Reported around 4.8 on iOS and 4.4 on Android by one source, though Google Play is cited elsewhere at a lower 3.9/5 (5,000+ reviews, 1 million+ downloads) -- a minor disagreement on the Android figure.', 'education_note' => 'Offers market-analysis videos, research articles, eBooks, seminars and webinars, broadly praised across aggregator-style sources though not deeply assessed by any single independent reviewer found.', 'blurb' => 'One of the best-known global forex/CFD brands, ForexTime (FXTM) is operated by Exinity Limited and reports millions of clients worldwide. It holds direct FCA (UK) and FSCA (South Africa) authorisation, and its Seychelles FSA Securities Dealer licence is well documented, though we could not independently confirm the exact SD licence number in this research pass.', 'scores' => array( 'regulation' => 2.6, 'cost' => null, 'platforms' => 3.4, 'track_record' => 1.98, 'overall' => 2.65 ), 'rank' => 64 ),
        array( 'slug' => 'bdswiss', 'name' => 'BDSwiss', 'entity' => 'BDSwiss (Seychelles) Ltd', 'cysec' => null, 'cysec_note' => 'Some sources describe an additional CySEC-regulated EU entity, but the specific licence number could not be independently confirmed in this research pass.', 'seychelles' => 'SD047', 'founded' => 2012, 'hq' => 'Limassol, Cyprus (Seychelles-licensed entity: BDSwiss (Seychelles) Ltd)', 'min_deposit_usd' => null, 'min_deposit_display' => null, 'spread_eurusd' => null, 'platforms' => array('MT4', 'MT5', 'Proprietary (BDSwiss WebTrader)'), 'other_reg' => array(), 'other_reg_count' => 0, 'instruments' => null, 'blurb' => 'BDSwiss traces its roots to 2012 and has built a long-running international presence, particularly across Africa and Asia. Its Seychelles FSA Securities Dealer licence (SD047) is well documented across multiple sources; some sources also describe an additional CySEC-regulated EU entity we could not independently confirm with a specific licence number.', 'scores' => array( 'regulation' => 1, 'cost' => null, 'platforms' => 3.4, 'track_record' => 1.9, 'overall' => 1.94 ), 'rank' => 109 ),
        array( 'slug' => 'windsor-brokers', 'name' => 'Windsor Brokers', 'entity' => 'Windsor Brokers Ltd', 'cysec' => null, 'cysec_note' => 'Widely reported to also hold a CySEC licence for its EU-facing entity, but the specific licence number could not be independently confirmed in this research pass.', 'seychelles' => 'SD072', 'seychelles_note' => 'Single-source figure; recommend a second confirmation against the FSA Seychelles register before relying on it.', 'founded' => 1988, 'hq' => 'Limassol, Cyprus', 'min_deposit_usd' => null, 'min_deposit_display' => null, 'spread_eurusd' => null, 'platforms' => array('MT4', 'MT5'), 'other_reg' => array(), 'other_reg_count' => 0, 'instruments' => null, 'blurb' => 'One of the longest continuously operating forex brokers in the industry, Windsor Brokers has traded under its own name since 1988. It is widely reported to hold both a CySEC licence (number not independently confirmed here) and a Seychelles FSA Securities Dealer licence (SD072, single-sourced -- worth a second check).', 'scores' => array( 'regulation' => 1, 'cost' => null, 'platforms' => 2.6, 'track_record' => 3.86, 'overall' => 2.27 ), 'rank' => 94 ),
        array( 'slug' => 'hantec-markets', 'name' => 'Hantec Markets', 'entity' => 'Hantec Markets Ltd / Hantec (Seychelles) Services Ltd', 'cysec' => null, 'fca' => '502635', 'seychelles' => 'SD164', 'seychelles_note' => 'One source cited a conflicting number (SDR225); recommend confirming directly against the FSA Seychelles register before relying on this figure.', 'founded' => 1990, 'hq' => 'Hong Kong / London, UK (Hantec Group); a Seychelles entity serves clients outside the UK/EU', 'min_deposit_usd' => null, 'min_deposit_display' => null, 'spread_eurusd' => null, 'platforms' => array('MT4', 'MT5'), 'other_reg' => array(), 'other_reg_count' => 0, 'instruments' => null, 'blurb' => 'Part of the Hong Kong-founded Hantec Group, dating back to 1990, Hantec Markets holds direct FCA (UK) authorisation alongside a Seychelles FSA Securities Dealer licence for clients outside the UK/EU -- one of the longer operating histories among brokers covered here.', 'scores' => array( 'regulation' => 1.8, 'cost' => null, 'platforms' => 2.6, 'track_record' => 3.69, 'overall' => 2.57 ), 'rank' => 75 ),
        array( 'slug' => 'titan-fx', 'name' => 'Titan FX', 'entity' => 'Goliath Trading Limited', 'cysec' => null, 'seychelles' => 'SD138', 'seychelles_note' => 'Single-source figure; recommend a second confirmation against the FSA Seychelles register before relying on it.', 'founded' => 2014, 'hq' => 'Vanuatu / New Zealand (regional entities)', 'min_deposit_usd' => null, 'min_deposit_display' => null, 'spread_eurusd' => null, 'platforms' => array('MT4', 'MT5'), 'other_reg' => array(), 'other_reg_count' => 0, 'instruments' => null, 'blurb' => 'Titan FX has built a strong reputation among active MetaTrader traders in the Asia-Pacific region since 2014. Its Seychelles FSA Securities Dealer licence (SD138) is currently its primary regulatory credential -- it does not hold an FCA, ASIC, or other Tier-1 licence.', 'scores' => array( 'regulation' => 1, 'cost' => null, 'platforms' => 2.6, 'track_record' => 1.73, 'overall' => 1.67 ), 'rank' => 118 ),
        array( 'slug' => 'pu-prime', 'name' => 'PU Prime', 'entity' => 'PU Prime (regional entities across Australia, Seychelles, and the UK)', 'cysec' => null, 'seychelles' => 'SD050', 'seychelles_note' => 'Single-source figure; recommend a second confirmation against the FSA Seychelles register before relying on it.', 'founded' => 2015, 'hq' => 'Multi-jurisdictional (Australia, Seychelles, UK entities)', 'min_deposit_usd' => null, 'min_deposit_display' => null, 'spread_eurusd' => null, 'platforms' => array('MT4', 'MT5', 'Proprietary (PU Prime app)'), 'other_reg' => array(), 'other_reg_count' => 0, 'instruments' => null, 'blurb' => 'A newer, fast-growing multi-asset broker founded around 2015, PU Prime has expanded its regulatory footprint over time, most recently adding UAE authorisation alongside its Seychelles FSA Securities Dealer licence (SD050) -- a real but comparatively thin operating history versus most other brokers on this list.', 'scores' => array( 'regulation' => 1, 'cost' => null, 'platforms' => 3.4, 'track_record' => 1.65, 'overall' => 1.87 ), 'rank' => 111 ),
        array( 'slug' => 'vt-markets', 'name' => 'VT Markets', 'entity' => 'VT Markets (AC Capital Market Charts group)', 'cysec' => null, 'seychelles' => 'SD198', 'seychelles_note' => 'Single-source figure; recommend a second confirmation against the FSA Seychelles register before relying on it.', 'founded' => 2016, 'hq' => 'Sydney-linked / Asia-Pacific', 'min_deposit_usd' => null, 'min_deposit_display' => null, 'spread_eurusd' => null, 'platforms' => array('MT4', 'MT5'), 'other_reg' => array(), 'other_reg_count' => 0, 'instruments' => null, 'blurb' => 'VT Markets is a fast-growing broker founded in 2016 with an increasingly visible presence across Asia-Pacific markets. Its Seychelles FSA Securities Dealer licence (SD198) is currently its primary regulatory credential -- it does not yet hold an FCA, ASIC, or other Tier-1 licence.', 'scores' => array( 'regulation' => 1, 'cost' => null, 'platforms' => 2.6, 'track_record' => 1.57, 'overall' => 1.62 ), 'rank' => 122 ),
        array( 'slug' => 'exclusive-markets', 'name' => 'Exclusive Markets', 'entity' => 'Exclusive Markets Ltd', 'cysec' => null, 'seychelles' => null, 'seychelles_note' => 'FSA Seychelles-licensed, per the official FSA Capital Markets register; licence number not independently confirmed.', 'founded' => null, 'hq' => 'Eden Island, Mahé, Seychelles (also a Dubai representative office)', 'min_deposit_usd' => null, 'min_deposit_display' => null, 'spread_eurusd' => null, 'platforms' => array('MT4', 'MT5'), 'other_reg' => array(), 'other_reg_count' => 0, 'instruments' => null, 'blurb' => 'Exclusive Markets markets itself as serving 180+ countries with 5,000+ instruments and runs a funded prop-trading arm alongside its retail CFD business. Trade press has reported acquisition talks with INFINOX, though that deal\'s status is unconfirmed. Independent reviewers classify it as offshore-only regulation with limited investor protection, and some withdrawal-dispute complaints have been noted -- its founding year is widely cited as 1990 in marketing copy, but that traces to a claim about the team\'s "30+ years of collective experience" rather than a verified incorporation date, so it\'s left unconfirmed here.', 'scores' => array( 'regulation' => 1.0, 'cost' => null, 'platforms' => 2.6, 'track_record' => null, 'overall' => 1.64 ), 'rank' => 119 ),
        array( 'slug' => 'valutrades', 'name' => 'Valutrades', 'entity' => 'Valutrades (Seychelles) Limited', 'cysec' => null, 'fca' => '586541', 'seychelles' => null, 'seychelles_note' => 'FSA Seychelles-licensed, per the official FSA Capital Markets register; licence number not independently confirmed.', 'founded' => 2012, 'hq' => 'London, UK', 'min_deposit_usd' => null, 'min_deposit_display' => null, 'spread_eurusd' => null, 'platforms' => array('MT4', 'MT5'), 'other_reg' => array(), 'other_reg_count' => 0, 'instruments' => null, 'blurb' => 'Valutrades is a well-documented ECN-style multi-asset broker (forex, commodities, equity index CFDs) with a genuine, long-standing FCA authorisation (firm reference number 586541) on its UK entity, Valutrades Limited -- a separate legal entity from the Seychelles one reviewed here. No major scam allegations surfaced in research. The same FCA entity also stands behind ForexVox, a separate Seychelles-facing sister brand also reviewed on this site.', 'scores' => array( 'regulation' => 1.8, 'cost' => null, 'platforms' => 2.6, 'track_record' => 1.9, 'overall' => 2.06 ), 'rank' => 104 ),
        array( 'slug' => 'trade-nation', 'name' => 'Trade Nation', 'entity' => 'Trade Nation Financial Markets Limited', 'cysec' => '—', 'cysec_note' => 'Regulated directly in the EU via Portugal\'s CMVM (not CySEC/Cyprus), alongside the FCA (UK), ASIC (Australia), and the FSCA (South Africa). Also holds a Bahamas SCB registration, not Tier-1 and excluded here.', 'fca' => '525164', 'seychelles' => null, 'seychelles_note' => 'FSA Seychelles-licensed, per the official FSA Capital Markets register; licence number not independently confirmed.', 'founded' => 2014, 'hq' => 'London, UK', 'min_deposit_usd' => null, 'min_deposit_display' => null, 'spread_eurusd' => null, 'platforms' => array('MT4', 'TradingView', 'Proprietary (TN Trader)'), 'other_reg' => array('ASIC', 'FSCA'), 'other_reg_count' => 2, 'instruments' => null, 'account_types' => 'A CFD/Spread account (zero commission, fixed-style spreads from 0.5 pips, proprietary TN Trader platform with TradingView integration) and a MetaTrader (MT4) Standard account (variable spreads from 1.1 pips). An Islamic/swap-free account is available in most regions but explicitly not offered in Malaysia, per one source. A Professional account tier exists for qualifying clients.', 'execution_model' => 'Not confirmed as a clearly sourced, independent classification. The fixed-spread CFD/Spread account design is suggestive of a principal/market-maker model, but no source explicitly stated this, so it\'s reported here as unconfirmed rather than inferred.', 'withdrawal_deposit_note' => 'Minimum deposit $0. No Trade Nation-side fees on deposits or withdrawals (third-party payment-processor fees may still apply). Methods include cards, Apple Pay, local bank transfer, e-wallets and crypto, with withdrawals returned via the original deposit method.', 'overnight_financing' => 'The Islamic account replaces swap with a daily administration fee after a 5-day grace period. Standard swap depends on direction, instrument and market conditions; the benchmark-rate-plus-markup breakdown wasn\'t found.', 'currency_conversion_fee' => 'No fee percentage was found; Trade Nation\'s own guidance tells clients to fund in the same currency as their bank account "to avoid conversion fees," implying a fee exists on mismatched currencies, though the rate itself isn\'t disclosed.', 'inactivity_fee' => 'One source states a fee applies after 6 months of dormancy, but the exact amount wasn\'t found.', 'customer_service_note' => 'Trustpilot figures are inconsistent across sources -- one snippet shows 4.7/5 from 259 reviews, while another references 1,759 reviews for the same profile. Sentiment is consistently positive (responsive, knowledgeable support), with some complaints about an outdated charting interface and occasional demo-account access issues.', 'mobile_note' => 'Described qualitatively as quick and simple to navigate with positive user sentiment, but no single reliable aggregate App Store or Google Play star rating was found.', 'education_note' => 'A demo/practice account funded with £10,000 in virtual funds; reviewers describe its educational and research tools as a strength, but no detailed, independently reviewed course catalogue was found.', 'blurb' => 'A privately held CFD and spread-betting broker with one of the wider genuine regulatory footprints in this group -- direct EU regulation via Portugal\'s CMVM sits alongside the FCA, ASIC, and FSCA, plus a UK FSCS compensation scheme (up to £85,000) and negative balance protection. Trade Nation deliberately skips MetaTrader 5, offering its own TN Trader platform, TradingView integration, and MT4 instead.', 'scores' => array( 'regulation' => 3.4, 'cost' => null, 'platforms' => 3.4, 'track_record' => 1.73, 'overall' => 2.92 ), 'rank' => 49 ),
        array( 'slug' => 'eto-markets', 'name' => 'ETO Markets', 'entity' => 'ETO Markets Limited', 'cysec' => null, 'seychelles' => null, 'seychelles_note' => 'FSA Seychelles-licensed, per the official FSA Capital Markets register; licence number not independently confirmed.', 'founded' => 2013, 'hq' => 'Sydney, Australia', 'min_deposit_usd' => null, 'min_deposit_display' => null, 'spread_eurusd' => null, 'platforms' => array('MT4', 'MT5'), 'other_reg' => array('ASIC'), 'other_reg_count' => 1, 'instruments' => null, 'blurb' => 'ETO Markets claims a presence in 120+ countries as a retail and institutional multi-asset broker. Worth knowing: multiple reports from late 2024 describe an ASIC investigation after a client allegedly lost over $350,000 on an abnormal silver (XAG/USD) quote, alongside accusations of withdrawal denial -- one report suggested ASIC could potentially act on the AFSL. This appears to be an open controversy rather than a settled matter as of this research; verify ETO\'s current ASIC status directly before relying on it.', 'scores' => array( 'regulation' => 1.8, 'cost' => null, 'platforms' => 2.6, 'track_record' => 1.81, 'overall' => 2.03 ), 'rank' => 105 ),
        array( 'slug' => 'tentrade', 'name' => 'TenTrade', 'entity' => 'Evalanch Ltd', 'cysec' => null, 'seychelles' => 'SD082', 'seychelles_note' => 'Single-source figure from independent research, not the primary register export; recommend confirming directly against the FSA Seychelles register.', 'founded' => 2019, 'hq' => 'Mahé, Seychelles (registered); day-to-day operations reported to be largely based in Cyprus', 'min_deposit_usd' => null, 'min_deposit_display' => null, 'spread_eurusd' => null, 'platforms' => array('MT5'), 'other_reg' => array(), 'other_reg_count' => 0, 'instruments' => null, 'blurb' => 'A newer multi-asset broker (CFDs, forex, crypto, stocks) offering 170+ instruments, copy trading, and a prop-trading challenge program; it has hired several known industry executives from INGOT Brokers, BDSwiss, and Exinity. Worth knowing: TenTrade advertises leverage up to 1:2000, far above what EU/UK regulators permit for retail clients -- a leverage level that size alone is a real risk factor independent of the broker\'s legitimacy.', 'scores' => array( 'regulation' => 1.0, 'cost' => null, 'platforms' => 1.8, 'track_record' => 1.32, 'overall' => 1.32 ), 'rank' => 125 ),
        array( 'slug' => 'foracon', 'name' => 'Foracon', 'entity' => 'Foracon Markets Ltd', 'cysec' => null, 'seychelles' => null, 'seychelles_note' => 'FSA Seychelles-licensed, per the official FSA Capital Markets register; licence number not independently confirmed.', 'founded' => null, 'hq' => null, 'min_deposit_usd' => null, 'min_deposit_display' => null, 'spread_eurusd' => null, 'platforms' => array(), 'other_reg' => array(), 'other_reg_count' => 0, 'instruments' => null, 'blurb' => 'No independently verifiable public information was found for this broker beyond its listing in the official Seychelles FSA Capital Markets register -- no review-site profile, forum discussion, or news coverage turned up in research. Treat this as a broker with an essentially undocumented public track record, and verify directly before relying on anything beyond its registration status.', 'scores' => array( 'regulation' => 1.0, 'cost' => null, 'platforms' => 1.0, 'track_record' => null, 'overall' => 1.0 ), 'rank' => 135 ),
        array( 'slug' => 'go4rex', 'name' => 'GO4REX', 'entity' => 'FX Capital Ltd', 'cysec' => null, 'seychelles' => 'SD023', 'seychelles_note' => 'Single-source figure from independent research, not the primary register export; recommend confirming directly against the FSA Seychelles register.', 'founded' => null, 'hq' => 'Claimed address in Seychelles -- an independent WikiFX investigation reportedly found no physical presence there, so this is disputed rather than confirmed.', 'min_deposit_usd' => null, 'min_deposit_display' => null, 'spread_eurusd' => null, 'platforms' => array(), 'other_reg' => array(), 'other_reg_count' => 0, 'instruments' => null, 'blurb' => 'Significant red flags were found for this broker: it reportedly charges a "profit clearance fee" on winning trades, offers no demo account or educational materials, and doesn\'t use MT4 or MT5 (an unnamed proprietary platform instead). Multiple independent complaint threads describe alleged fund manipulation, pressure to deposit more, and withdrawal refusals or surprise fees demanded before payout -- one reviewer explicitly lists it as "not recommended." This is the most consistently red-flagged broker identified in this research pass; exercise significant caution.', 'scores' => array( 'regulation' => 1.0, 'cost' => null, 'platforms' => 1.0, 'track_record' => null, 'overall' => 1.0 ), 'rank' => 136 ),
        array( 'slug' => 'prime-markets-sc', 'name' => 'Prime Markets', 'entity' => 'Prime Markets Limited', 'cysec' => null, 'seychelles' => null, 'seychelles_note' => 'FSA Seychelles-licensed, per the official FSA Capital Markets register; licence number not independently confirmed.', 'founded' => null, 'hq' => null, 'min_deposit_usd' => null, 'min_deposit_display' => null, 'spread_eurusd' => null, 'platforms' => array(), 'other_reg' => array(), 'other_reg_count' => 0, 'instruments' => null, 'blurb' => 'Important disambiguation: the name "Prime Markets" is shared by several unrelated firms, including one on the UK FCA\'s warning list for unauthorized activity (primemarkets.com) and others ("Hola Prime Markets," "Core Prime Markets") with no connection to this entity. No evidence was found linking this specific Seychelles-registered broker (goprimemarkets.com) to the FCA-warned entity, but given the name-collision risk, always verify you\'re on goprimemarkets.com specifically. Beyond its FSA registration, essentially no independently verifiable public information exists for this entity.', 'scores' => array( 'regulation' => 1.0, 'cost' => null, 'platforms' => 1.0, 'track_record' => null, 'overall' => 1.0 ), 'rank' => 137 ),
        array( 'slug' => 'traders-trust', 'name' => 'Traders Trust', 'entity' => 'TTCM Traders Trust Capital Markets Ltd (CySEC entity); Traders Trust Ltd (Seychelles entity)', 'cysec' => '107/09', 'cysec_note' => 'Held by TTCM Traders Trust Capital Markets Ltd, a separate legal entity from Traders Trust Ltd (the Seychelles-licensed entity reviewed here) within the same group. Also operates TTCM Traders Capital Ltd under the Bermuda Monetary Authority, not Tier-1 and excluded here.', 'seychelles' => null, 'seychelles_note' => 'FSA Seychelles-licensed, per the official FSA Capital Markets register; licence number not independently confirmed.', 'founded' => 2009, 'hq' => 'Limassol, Cyprus', 'min_deposit_usd' => null, 'min_deposit_display' => null, 'spread_eurusd' => null, 'platforms' => array('MT4', 'cTrader'), 'other_reg' => array(), 'other_reg_count' => 0, 'instruments' => null, 'blurb' => 'Traders Trust operates a genuinely multi-jurisdictional structure spanning CySEC (Cyprus, with Investor Compensation Fund coverage up to €20,000 per client), the Seychelles FSA, and Bermuda. Of the brokers added in this update, this is one of only three with a direct, confirmed EU/MiFID licence. Multi-asset offering across forex, indices, stocks, crypto, and metals; notably doesn\'t offer MetaTrader 5, running MT4 and cTrader instead.', 'scores' => array( 'regulation' => 1.0, 'cost' => null, 'platforms' => 2.6, 'track_record' => 2.14, 'overall' => 1.78 ), 'rank' => 112 ),
        array( 'slug' => 'icm-capital', 'name' => 'ICM Capital', 'entity' => 'ICM Capital Limited', 'cysec' => null, 'seychelles' => 'SD201', 'seychelles_note' => 'Single-source figure from independent research, not the primary register export; recommend confirming directly against the FSA Seychelles register.', 'founded' => 2009, 'hq' => 'London, UK (legacy -- see regulatory note)', 'min_deposit_usd' => null, 'min_deposit_display' => null, 'spread_eurusd' => null, 'platforms' => array('MT4', 'MT5', 'cTrader', 'TradingView'), 'other_reg' => array('FSCA'), 'other_reg_count' => 1, 'instruments' => null, 'account_types' => 'ICM Direct (commission-free, wider spread) and ICM Zero (tighter/raw spreads plus around $7 commission per trade), with the same instruments and leverage across both. An Islamic account is available on request via customer support rather than as a self-service option. One reviewer notes ICM reportedly serves professional traders only, not retail clients -- a positioning claim worth confirming given the FCA licence surrender noted above.', 'execution_model' => 'No formal ECN account tier exists, but its proprietary "ICM Direct" platform is described as using ECN-style technology and direct market access with Tier-1 bank liquidity -- effectively an STP/ECN hybrid rather than a classic dealing-desk model.', 'withdrawal_deposit_note' => 'Minimum deposit around $200/£200. Deposit fees apply on all funding methods except bank transfer, ranging from around 1.9% (Skrill) up to 3.75% (PayPal). Withdrawal fees are reported as starting from $0 depending on method; minimum withdrawal $1.', 'overnight_financing' => 'Swap/rollover is applied at 20:00 GMT on open positions; the benchmark-plus-markup methodology wasn\'t disclosed.', 'currency_conversion_fee' => 'Not found specific to ICM Capital; general industry practice (auto-converting USD-denominated charges to the account\'s base currency) was noted but not confirmed as ICM\'s specific policy.', 'inactivity_fee' => 'Not found.', 'customer_service_note' => 'Mixed and somewhat contradictory Trustpilot data: one listing ("ICM.com") shows 3/5 from 34 reviews with both high five-star and high one-star clusters, while a separately listed "ICM Capital" profile shows a much weaker 2.4/5 from 9 reviews (78% one-star) -- given the UK entity\'s ongoing exit from retail, some of this may reflect exit-related frustration. It\'s not confirmed which profile maps precisely to ICM Capital Limited versus the wider ICM.com group.', 'mobile_note' => 'An "ICM.com Card" app was found with a 5.0 rating from just 1 review -- too small a sample to be meaningful. No reliable app rating was found.', 'education_note' => 'Described by one source as offering educational webinars for beginners and experienced traders plus daily market news, with no further independent assessment of depth found.', 'blurb' => 'Rebranded from ICM Capital to ICM.com in 2018. Worth knowing: ICM fully surrendered its FCA (UK) licence as of April 2026 after exiting UK retail around 2023 -- a meaningful regulatory downgrade, not merely a historical footnote. Its remaining FSCA (South Africa) licence has also been flagged by WikiFX as showing an "exceeded business scope" caution. Platform choice is genuinely broad (MT4, MT5, cTrader, TradingView).', 'scores' => array( 'regulation' => 1.8, 'cost' => null, 'platforms' => 4.2, 'track_record' => 2.14, 'overall' => 2.58 ), 'rank' => 72 ),
        array( 'slug' => 'baxia-markets', 'name' => 'Baxia Markets', 'entity' => 'Baxia Global Ltd', 'cysec' => null, 'seychelles' => 'SD104', 'seychelles_note' => 'Single-source figure from independent research, not the primary register export; recommend confirming directly against the FSA Seychelles register.', 'founded' => 2020, 'hq' => null, 'min_deposit_usd' => null, 'min_deposit_display' => null, 'spread_eurusd' => null, 'platforms' => array('MT4', 'MT5'), 'other_reg' => array(), 'other_reg_count' => 0, 'instruments' => null, 'blurb' => 'Founded by a former FXCM and Pepperstone executive. Worth knowing: multiple independent reviews describe a recurring complaint pattern -- withdrawal refusals or delays, accounts blocked and profits annulled after successful trades, and demands for extra fees before withdrawal -- and one source alleges its MetaTrader terminals are registered under unrelated third-party companies, raising doubts about platform legitimacy. It has been a member of The Financial Commission (external dispute resolution, up to €20,000 per complaint) since January 2023, which is a mitigating factor but doesn\'t resolve the underlying complaint pattern.', 'scores' => array( 'regulation' => 1.0, 'cost' => null, 'platforms' => 2.6, 'track_record' => 1.24, 'overall' => 1.53 ), 'rank' => 124 ),
        array( 'slug' => 'cxm-direct', 'name' => 'CXM Direct', 'entity' => 'CXM Group (SC) Ltd', 'cysec' => null, 'seychelles' => 'SD231', 'seychelles_note' => 'Granted October 2025, very recently -- single-source figure from independent research, not the primary register export; recommend confirming directly against the FSA Seychelles register.', 'founded' => 2015, 'hq' => null, 'min_deposit_usd' => null, 'min_deposit_display' => null, 'spread_eurusd' => null, 'platforms' => array('MT4', 'MT5'), 'other_reg' => array(), 'other_reg_count' => 0, 'instruments' => null, 'blurb' => 'CXM Group describes itself as an institutional/liquidity-first firm (~136 employees) expanding into retail, and won "Best Gold Trading Broker 2026" at iFX EXPO Dubai. A separate group entity, CXM Prime, holds an FCA (UK) licence for institutional liquidity provision -- that\'s a different legal entity and business line from the retail CXM Direct brand reviewed here, so it isn\'t counted as CXM Direct\'s own regulation. Worth knowing: Malaysia\'s Securities Commission has flagged CXM Direct for unlicensed capital-markets activity in that jurisdiction.', 'scores' => array( 'regulation' => 1.0, 'cost' => null, 'platforms' => 2.6, 'track_record' => 1.65, 'overall' => 1.64 ), 'rank' => 120 ),
        array( 'slug' => 'tradeultra', 'name' => 'TradeUltra', 'entity' => 'TradeUltra Limited', 'cysec' => null, 'seychelles' => null, 'seychelles_note' => 'FSA Seychelles-licensed, per the official FSA Capital Markets register; licence number not independently confirmed.', 'founded' => 2013, 'hq' => null, 'min_deposit_usd' => null, 'min_deposit_display' => null, 'spread_eurusd' => null, 'platforms' => array('MT4', 'MT5'), 'other_reg' => array(), 'other_reg_count' => 0, 'instruments' => null, 'blurb' => 'TradeUltra previously held a Mauritius FSC licence, which was terminated/surrendered effective June 2024, ahead of its current Seychelles registration -- a real regulatory downgrade worth knowing about. Reviewers have also flagged multiple offshore company registrations (St. Vincent & the Grenadines, Anguilla) as a transparency concern. A new CEO was installed recently, suggesting a management overhaul; Trustpilot reviews are mixed.', 'scores' => array( 'regulation' => 1.0, 'cost' => null, 'platforms' => 2.6, 'track_record' => 1.81, 'overall' => 1.69 ), 'rank' => 116 ),
        array( 'slug' => 'trinota-markets', 'name' => 'Trinota Markets', 'entity' => 'Trinota Markets (Global) Limited', 'cysec' => null, 'cysec_note' => 'Reported to hold a direct CySEC (Cyprus) licence via a 2022 acquisition (formerly Axiance/EverFX, now Harindale Ltd), but the specific licence number could not be independently confirmed in this research pass -- treat as EU-regulated only once that\'s verified.', 'seychelles' => null, 'seychelles_note' => 'FSA Seychelles-licensed, per the official FSA Capital Markets register; licence number not independently confirmed.', 'founded' => 2019, 'hq' => 'Mahé, Seychelles (registered); operations reported to be largely run from Cyprus', 'min_deposit_usd' => null, 'min_deposit_display' => null, 'spread_eurusd' => null, 'platforms' => array('MT4', 'MT5', 'cTrader'), 'other_reg' => array('DFSA'), 'other_reg_count' => 1, 'instruments' => null, 'blurb' => 'Trades under the brand M4Markets, founded by former HSBC/KPMG/UBS and industry executives, and has been acquiring other brokers\' client books (including Tixee\'s). Holds a DFSA (Dubai) licence alongside its reported but unconfirmed CySEC one. Note: an unrelated, similarly named domain ("tritonmarkets.com") appears on France\'s AMF blacklist -- that\'s a different operation, not connected to Trinota/M4Markets as far as this research could establish.', 'scores' => array( 'regulation' => 1.8, 'cost' => null, 'platforms' => 3.4, 'track_record' => 1.32, 'overall' => 2.12 ), 'rank' => 100 ),
        array( 'slug' => 'eurotrade', 'name' => 'Eurotrade', 'entity' => 'Eurotrade Investments RGB Ltd (CySEC entity); Eurotrade RGB (Seychelles) Ltd (Seychelles entity)', 'cysec' => '279/15', 'cysec_note' => 'Important: the FCA (UK), CNMV (Spain), and FSMA (Belgium) have each issued public warnings about a firm called "Eurotrade" -- but per regulatory/trade-press reporting, those target an unauthorized clone site impersonating this brand, not the CySEC-licensed Eurotrader Group itself. The brand name is actively being spoofed by scammers, so always verify you\'re on the genuine eurotrader.com domain before depositing.', 'seychelles' => null, 'seychelles_note' => 'FSA Seychelles-licensed, per the official FSA Capital Markets register; licence number not independently confirmed.', 'founded' => 2015, 'hq' => 'Limassol, Cyprus (also a London corporate office)', 'min_deposit_usd' => null, 'min_deposit_display' => null, 'spread_eurusd' => null, 'platforms' => array('MT4', 'MT5'), 'other_reg' => array('FSCA'), 'other_reg_count' => 1, 'instruments' => null, 'blurb' => 'Trades as Eurotrader. Directly CySEC-regulated (licence 279/15) with an additional FSCA (South Africa) licence -- one of only three brokers added in this update with a confirmed, direct EU/MiFID licence. A proprietary copy-trading app is also offered alongside MT4/MT5. See the regulatory note above for an important brand-impersonation warning unrelated to the licensed entity\'s own standing.', 'scores' => array( 'regulation' => 1.8, 'cost' => null, 'platforms' => 2.6, 'track_record' => 1.65, 'overall' => 1.99 ), 'rank' => 106 ),
        array( 'slug' => 'forexvox', 'name' => 'ForexVox', 'entity' => 'ForexVox (Seychelles) Ltd', 'cysec' => null, 'fca' => '586541', 'seychelles' => 'SD142', 'seychelles_note' => 'Single-source figure from independent research, not the primary register export; recommend confirming directly against the FSA Seychelles register.', 'founded' => 2019, 'hq' => 'London, UK', 'min_deposit_usd' => null, 'min_deposit_display' => null, 'spread_eurusd' => null, 'platforms' => array('MT4', 'MT5'), 'other_reg' => array(), 'other_reg_count' => 0, 'instruments' => null, 'blurb' => 'Founded by former GKFX executives. Its FCA (UK) authorisation (firm reference 586541) is held via ValuTrades Limited -- the same FCA entity behind Valutrades, also reviewed on this site, making the two sister brands under shared corporate ownership. The retail brand rebranded from ForexVox to "MarketsVox" in January 2024; forexvox.com may now operate as a legacy site or redirect, so confirm current live status before relying on this specific domain.', 'scores' => array( 'regulation' => 1.8, 'cost' => null, 'platforms' => 2.6, 'track_record' => 1.32, 'overall' => 1.89 ), 'rank' => 110 ),
        array( 'slug' => 'daman-markets', 'name' => 'Daman Markets', 'entity' => 'Daman Markets Financial Services (Seychelles) Limited', 'cysec' => null, 'seychelles' => null, 'seychelles_note' => 'FSA Seychelles-licensed, per the official FSA Capital Markets register; licence number not independently confirmed.', 'founded' => 2023, 'hq' => 'Dubai, UAE (parent: Daman Securities, a UAE brokerage established in 1998)', 'min_deposit_usd' => null, 'min_deposit_display' => null, 'spread_eurusd' => null, 'platforms' => array('MT5'), 'other_reg' => array(), 'other_reg_count' => 0, 'instruments' => null, 'blurb' => 'Launched in late 2023 as a spin-off of the long-established Daman Securities group. Its differentiator is AED-denominated accounts with direct access to DFM- and ADX-listed UAE equities alongside standard forex/CFD/MT5 trading. Online claims of CySEC, FSCA, or Mauritius FSC regulation for Daman Markets could not be traced to any primary source in this research pass and should not be assumed accurate. WikiFX flags its newer offshore brand with a caution-level risk score.', 'scores' => array( 'regulation' => 1.0, 'cost' => null, 'platforms' => 1.8, 'track_record' => 1.0, 'overall' => 1.23 ), 'rank' => 129 ),
        array( 'slug' => 'pipbull', 'name' => 'Pipbull', 'entity' => 'Pipbull Limited', 'cysec' => null, 'seychelles' => null, 'seychelles_note' => 'FSA Seychelles-licensed, per the official FSA Capital Markets register; licence number not independently confirmed.', 'founded' => null, 'hq' => 'Mahé, Seychelles (registered office)', 'min_deposit_usd' => null, 'min_deposit_display' => null, 'spread_eurusd' => null, 'platforms' => array(), 'other_reg' => array(), 'other_reg_count' => 0, 'instruments' => null, 'blurb' => 'An extremely thin public footprint was found for this broker -- no review-site profile, forum discussion, or news coverage. One unverified lead suggests a possible connection to a now-discontinued broker\'s old Seychelles shell entity, but this could not be confirmed as the same company and shouldn\'t be treated as fact. Verify directly before relying on anything beyond its FSA registration.', 'scores' => array( 'regulation' => 1.0, 'cost' => null, 'platforms' => 1.0, 'track_record' => null, 'overall' => 1.0 ), 'rank' => 138 ),
        array( 'slug' => 'vantage-markets', 'name' => 'Vantage Markets', 'entity' => 'Trademax Global Markets (SE) Limited', 'cysec' => null, 'fca' => '590299', 'seychelles' => null, 'seychelles_note' => 'FSA Seychelles-licensed, per the official FSA Capital Markets register; licence number not independently confirmed.', 'founded' => 2009, 'hq' => 'Sydney, Australia', 'min_deposit_usd' => null, 'min_deposit_display' => null, 'spread_eurusd' => null, 'platforms' => array('MT4', 'MT5', 'Proprietary (ProTrader)'), 'other_reg' => array('ASIC', 'FSCA', 'DFSA'), 'other_reg_count' => 3, 'instruments' => null, 'account_types' => 'Standard STP (spreads from about 1.0 pip, commission-free), Raw ECN (spreads from 0.0, commission from $3/lot/side), and Pro ECN (for high-volume traders, $10,000 minimum deposit, commission around $1.50/lot/side), plus Cent and Copy Trading accounts. Swap-Free variants exist for Standard STP and Raw ECN specifically.', 'execution_model' => 'STP on the Standard account; ECN on the Raw and Pro accounts.', 'withdrawal_deposit_note' => 'Minimum withdrawal $50. No internal Vantage fee for domestic/local bank withdrawals, though overseas bank transfers may incur bank-side fees; withdrawals must use the same method as the original deposit. Card withdrawals take 1-3 business days, bank wire 1-4 business days, Skrill within 1 business day.', 'overnight_financing' => 'Standard interest-rate-differential swap applied to positions held past 22:00 server time (GMT+2/+3 in summer), with Wednesday a triple-swap day for weekend rollover. Swap-free accounts instead pay an "administration fee," reported to pass through the broker\'s liquidity-provider cost plus roughly a 10% internal processing markup.', 'currency_conversion_fee' => 'A fee applies when converting realized profit/loss or other charges into a currency different from the account\'s base currency, but no specific percentage was found in this research pass.', 'inactivity_fee' => 'Up to $10, charged annually (not monthly) after 12 months with no transactions, deducted directly from the account balance -- this annual structure differs from brokers that charge monthly, so it\'s worth confirming the exact wording in Vantage\'s own terms.', 'customer_service_note' => 'Trustpilot figures vary by source (4.3-4.5/5, from roughly 14,000 reviews in one snapshot), with 24/7 support claimed and many reviewers noting prompt, helpful responses. Recurring complaints include delayed or rejected withdrawals, account-verification friction, and in some cases aggressive sales tactics. A "Best Customer Support" industry award it cites is a vendor/trade-publication award, not independent user research.', 'mobile_note' => 'Figures conflict: the Apple App Store shows around 3.3/5 but from only about 60 reviews (too small a sample to be reliable), while other aggregators rate the app notably higher, around 4.3-4/5.', 'education_note' => '"Vantage Academy" courses cover forex, stock and index trading basics with interactive quizzes and videos, alongside regular live webinars, e-books and a podcast. One independent reviewer calls it a strong all-in-one broker for serious retail traders while also noting support can be sluggish during peak hours.', 'blurb' => 'Originally launched as Vantage FX, rebranded to Vantage in 2021. One of the larger, more established brokers in this update, with a genuinely wide, real Tier-1 regulatory footprint (ASIC, FCA, FSCA, DFSA) and 1,000+ tradable instruments. Worth knowing: independent reports also describe real complaints -- an introducing broker alleging pressure to remove a negative review, criticism over onboarding an IB with a prior scam-broker history, and trader complaints about large profit "clawbacks" under a vaguely worded suspicious-activity clause.', 'scores' => array( 'regulation' => 4.2, 'cost' => null, 'platforms' => 3.4, 'track_record' => 2.14, 'overall' => 3.38 ), 'rank' => 21 ),
        array( 'slug' => 'ventezo', 'name' => 'Ventezo', 'entity' => 'Ventezo Global Ltd', 'cysec' => null, 'seychelles' => 'SD197', 'seychelles_note' => 'Single-source figure from independent research, not the primary register export; recommend confirming directly against the FSA Seychelles register.', 'founded' => null, 'hq' => null, 'min_deposit_usd' => null, 'min_deposit_display' => null, 'spread_eurusd' => null, 'platforms' => array('MT4'), 'other_reg' => array(), 'other_reg_count' => 0, 'instruments' => null, 'blurb' => 'Independent research found a real pattern of concern: a Trustpilot score around 2/5 with no company replies to negative reviews, a WikiFX rating citing over a dozen complaints in a three-month window including reported withdrawal blocking, and -- most significantly -- reports that the broker\'s website was apparently down or out of business as of around January 2026. A separate, unconfirmed report describes a Malaysian regulatory warning against a similarly named entity. Given these signals, treat Ventezo\'s current operational status as genuinely uncertain rather than assuming it\'s active.', 'scores' => array( 'regulation' => 1.0, 'cost' => null, 'platforms' => 1.8, 'track_record' => null, 'overall' => 1.32 ), 'rank' => 126 ),
        array( 'slug' => 'taurex', 'name' => 'Taurex', 'entity' => 'Zenfinex Global Limited', 'cysec' => null, 'fca' => null, 'fca_note' => 'FCA-licensed; firm reference number not independently confirmed.', 'seychelles' => null, 'seychelles_note' => 'FSA Seychelles-licensed, per the official FSA Capital Markets register; licence number not independently confirmed.', 'founded' => 2017, 'hq' => 'London, UK (also a Seychelles office)', 'min_deposit_usd' => null, 'min_deposit_display' => null, 'spread_eurusd' => null, 'platforms' => array('MT4', 'MT5', 'cTrader'), 'other_reg' => array(), 'other_reg_count' => 0, 'instruments' => null, 'blurb' => 'Founded by a former FXCM and London Capital Group executive. The retail brand rebranded from Zenfinex to Taurex in September 2023 (Zenfinex is retained as the group/B2B name), and recently launched a prop-trading product. Offers 1,500+ instruments with a client base concentrated in Africa, Asia, the Middle East, and South America. A disclosed financial detail: the group posted a £1.9 million loss in 2022 shortly before the rebrand. No major scam warnings were found -- a comparatively cleaner record than several other brokers in this update.', 'scores' => array( 'regulation' => 1.8, 'cost' => null, 'platforms' => 3.4, 'track_record' => 1.49, 'overall' => 2.17 ), 'rank' => 97 ),
        array( 'slug' => 'plotio', 'name' => 'Plotio', 'entity' => 'Plotio FX SC Limited', 'cysec' => null, 'seychelles' => null, 'seychelles_note' => 'FSA Seychelles-licensed, per the official FSA Capital Markets register; licence number not independently confirmed.', 'founded' => null, 'hq' => null, 'min_deposit_usd' => null, 'min_deposit_display' => null, 'spread_eurusd' => null, 'platforms' => array('MT5'), 'other_reg' => array(), 'other_reg_count' => 0, 'instruments' => null, 'blurb' => 'Important caution: numerous 2025-2026 consumer-warning reports describe a platform called "PLOTIO" targeting victims in Singapore via social-media ads, with alleged fund-withdrawal blocking reported to Singapore\'s Anti-Scam Centre. It could not be confirmed whether these reports refer to this same regulated Seychelles entity or an unrelated clone site using the same brand name -- cloning of licensed brokers\' names by scammers is common in this industry. Separately, legitimate review sites that do appear to cover the regulated broker itself describe it only as mediocre (high spreads, limited product range), not as fraudulent. Verify carefully before relying on anything here.', 'scores' => array( 'regulation' => 1.0, 'cost' => null, 'platforms' => 1.8, 'track_record' => null, 'overall' => 1.32 ), 'rank' => 127 ),
        array( 'slug' => 'fxcentrum', 'name' => 'FXCentrum', 'entity' => 'WTG Ltd', 'cysec' => null, 'seychelles' => null, 'seychelles_note' => 'FSA Seychelles-licensed, per the official FSA Capital Markets register; licence number not independently confirmed.', 'founded' => 2019, 'hq' => 'Seychelles (no separate brand headquarters found)', 'min_deposit_usd' => null, 'min_deposit_display' => null, 'spread_eurusd' => null, 'platforms' => array('MT5', 'Proprietary (FXC)'), 'other_reg' => array(), 'other_reg_count' => 0, 'instruments' => null, 'blurb' => 'Significant regulatory warning: both the UK\'s FCA and Spain\'s CNMV have publicly stated that FXCentrum provides financial services without proper authorisation in their jurisdictions -- a concrete, well-sourced red flag from two separate Tier-1 regulators. WikiFX gives it a very low score, and its Trustpilot listing is currently marked unavailable for breaching platform guidelines. It also advertises leverage up to 1000:1 alongside a $10 minimum deposit, a combination typical of higher-risk, retail-targeting offshore brokers.', 'scores' => array( 'regulation' => 1.0, 'cost' => null, 'platforms' => 2.6, 'track_record' => 1.32, 'overall' => 1.55 ), 'rank' => 123 ),
        array( 'slug' => 'exquire', 'name' => 'Exquire', 'entity' => 'Zecra Trading Ltd', 'cysec' => null, 'seychelles' => null, 'seychelles_note' => 'FSA Seychelles-licensed, per the official FSA Capital Markets register; licence number not independently confirmed.', 'founded' => null, 'hq' => null, 'min_deposit_usd' => null, 'min_deposit_display' => null, 'spread_eurusd' => null, 'platforms' => array(), 'other_reg' => array(), 'other_reg_count' => 0, 'instruments' => null, 'blurb' => 'No independently verifiable public information was found for this broker beyond its listing in the official Seychelles FSA Capital Markets register -- repeated targeted searches under its brand and legal entity name returned no results on review sites, forums, or news coverage. Treat this as a broker with an essentially undocumented public track record, and verify directly before relying on anything beyond its registration status.', 'scores' => array( 'regulation' => 1.0, 'cost' => null, 'platforms' => 1.0, 'track_record' => null, 'overall' => 1.0 ), 'rank' => 139 ),
        array( 'slug' => 'oanda', 'name' => 'OANDA', 'entity' => 'OANDA Europe Limited', 'cysec' => null, 'fca' => '542574', 'fca_note' => 'OANDA was acquired by FTMO (the Czech "funded trader" prop-trading firm) from CVC Capital Partners effective 1 December 2025; FTMO says it will run OANDA as a standalone business -- a very recent ownership change worth confirming hasn\'t affected service before relying on it.', 'founded' => 1996, 'hq' => 'New York, USA (deep Canadian roots -- co-founded by a University of Toronto professor, with a long-standing Toronto presence)', 'min_deposit_usd' => null, 'min_deposit_display' => null, 'spread_eurusd' => null, 'platforms' => array('MT4', 'MT5', 'Proprietary (OANDA Trade / fxTrade)'), 'other_reg' => array('ASIC', 'NFA/CFTC (US)', 'CIRO', 'MAS'), 'other_reg_count' => 4, 'instruments' => null, 'account_types' => 'A single Standard account plus a Premium/high-volume tier (volume rebates, discounted financing, relationship management). Sources conflict on Islamic/swap-free account availability -- some comparison sites imply it\'s offered, while a UK-specific source states OANDA Europe Limited does not offer one. This is an unresolved contradiction worth confirming directly before publishing either claim.', 'execution_model' => 'Described by multiple sources as a market-maker model, which can mean wider spreads than STP/ECN peers but guarantees fills.', 'withdrawal_deposit_note' => 'No OANDA-side deposit fee and no minimum deposit; card deposits may incur a processor fee of 1-3%, not charged by OANDA itself. Withdrawals are free via PayPal, debit or credit card; bank wire and international transfers can be costlier, with typical processing of 1-3 business days (up to 5 for some methods).', 'overnight_financing' => 'For most FX and metals, financing is based on blended tom-next swap rates from liquidity providers plus an instrument-specific admin fee, annualized. For indices, OANDA applies a roughly 2.5% admin fee plus the relevant alternative reference rate (e.g. SOFR, ESTR, a SONIA-style rate, depending on currency) -- it moved from interbank rates to these reference rates in November 2021.', 'currency_conversion_fee' => 'A conversion fee applies when depositing or trading in a currency other than the account\'s base currency, but no specific percentage was independently confirmed in this research pass.', 'inactivity_fee' => '$10/month if the account has no transactions for 12 consecutive months; no minimum deposit is required to open an account.', 'customer_service_note' => 'Trustpilot ratings vary sharply by entity: OANDA Europe Limited (the entity reviewed here) scores a strong 4.8/5 (around 340 reviews), notably higher than OANDA Corporation in the US (3.0/5) or OANDA Canada (2.5/5). Praise centers on responsiveness and reliable execution; complaints mention onboarding delays and rigid withdrawal-dispute handling.', 'mobile_note' => 'Reported in the 4.6-4.7 range on both the App Store (around 23,000 ratings) and Google Play per most aggregators, though at least one source cites a notably lower figure -- treat the high-4s range as the better-supported estimate.', 'education_note' => 'Offers a dedicated education portal (videos, eBooks, webinars) from beginner to technical/fundamental analysis, plus an in-house MarketPulse research and news feed that\'s well regarded; at least one independent review describes the broader educational material itself as comparatively limited, supplemented by third-party Autochartist tools.', 'blurb' => 'One of the earliest internet-era FX data/trading firms, OANDA began as an online FX-rate service in 1996 before becoming a retail broker. Large multi-jurisdiction footprint across the US, Canada, UK, Australia and Singapore.', 'scores' => array( 'regulation' => 5.0, 'cost' => null, 'platforms' => 3.4, 'track_record' => 3.2, 'overall' => 4.03 ), 'rank' => 5 ),
        array( 'slug' => 'interactive-brokers', 'name' => 'Interactive Brokers', 'entity' => 'Interactive Brokers (U.K.) Limited', 'cysec' => null, 'fca' => '208159', 'founded' => 1978, 'hq' => 'Greenwich, Connecticut, USA', 'min_deposit_usd' => null, 'min_deposit_display' => null, 'spread_eurusd' => null, 'platforms' => array('TWS (Trader Workstation)', 'IBKR Desktop', 'IBKR Mobile', 'Client Portal (WebTrader)'), 'other_reg' => array('NFA/CFTC (US)', 'ASIC', 'CIRO', 'MAS', 'DFSA'), 'other_reg_count' => 5, 'instruments' => null, 'account_types' => 'Not a dedicated FX/CFD account structure -- individual, joint, trust, advisor, family-office and hedge-fund master-client accounts, plus IBKR Lite/Pro tiers (primarily US-focused). No Islamic/swap-free account was found; Muslim clients would need a cash (non-margin) account instead.', 'execution_model' => 'Agency/non-dealing-desk -- Interactive Brokers does not take the other side of client trades. Forex orders route to interbank liquidity via its IdealPro/IDEALFX system; stocks and options use its own "Smart Routing" DMA-style order routing.', 'withdrawal_deposit_note' => 'Not independently confirmed from an authoritative current fee page in this research pass -- Interactive Brokers is widely reported industry-wide to offer one free withdrawal per month with a fee after that, but we could not confirm the UK entity\'s exact current figure. Verify directly on interactivebrokers.co.uk\'s fee schedule.', 'overnight_financing' => 'Margin financing is tiered: a benchmark rate plus a markup that narrows at higher balances (roughly benchmark +1.5% at the lowest tier, down to about benchmark +0.5% at the highest), floored at 0%, accrued daily and posted monthly. No Islamic/swap-free account exists to avoid this.', 'currency_conversion_fee' => 'Its IdealFX auto-conversion service adds or subtracts roughly 0.03% from the interbank rate, with no separate commission; orders below about $25,000 may be rerouted to a smaller, potentially costlier conversion venue.', 'inactivity_fee' => 'None for individual, joint, trust or organization accounts, per Interactive Brokers\' own published minimums page. A separate $1/month fee applies only to introducing-broker client sub-accounts with very low balances and commissions -- not relevant to retail clients.', 'customer_service_note' => 'Phone and ticket-based support. Reviews are mixed: praise for platform depth and account security sits alongside recurring complaints (ConsumerAffairs, Trustpilot, Forex Peace Army) about frozen-account support loops, outsourced call centers and slow (reportedly up to 48-hour) ticket responses. Interactive Brokers UK also publishes FCA-mandated complaints-volume reports.', 'mobile_note' => 'Roughly 4.5 on the App Store (about 10,000 ratings) and a similar or slightly higher rating on Google Play per third-party aggregators, though exact figures vary by source and date -- treat the high-4s range as approximate rather than exact.', 'education_note' => 'IBKR Campus (including Traders\' Academy) provides free courses, video tutorials, and analytical tools (PortfolioAnalyst, Probability Lab/Options Strategy Lab); independently reviewed as one of the stronger educational offerings among brokers of this type.', 'blurb' => 'Publicly listed on Nasdaq (IBKR) and an S&P 500 constituent, Interactive Brokers is one of the largest electronic brokers globally by client equity, with access to 150+ markets worldwide. Founder Thomas Peterffy remains Chairman. Widely regarded as a low-controversy, Category-A-regulator-only broker relative to CFD-focused peers.', 'scores' => array( 'regulation' => 5.0, 'cost' => null, 'platforms' => 4.2, 'track_record' => 4.67, 'overall' => 4.68 ), 'rank' => 1 ),
        array( 'slug' => 'cmc-markets', 'name' => 'CMC Markets', 'entity' => 'CMC Markets UK plc', 'cysec' => null, 'fca' => '173730', 'founded' => 1989, 'hq' => 'London, UK', 'min_deposit_usd' => null, 'min_deposit_display' => null, 'spread_eurusd' => null, 'platforms' => array('Next Generation (proprietary)', 'MT4'), 'other_reg' => array('ASIC', 'FMA', 'MAS'), 'other_reg_count' => 3, 'instruments' => null, 'account_types' => 'A retail spread-betting or CFD account (parallel retail products), a Corporate account, a semi-professional "Alpha" account, and a Professional account. One lower-confidence source states no Islamic/swap-free option is offered, though this wasn\'t confirmed directly from CMC\'s own materials.', 'execution_model' => 'Market maker -- CMC\'s own Order Execution Policy states that orders execute bilaterally against CMC Markets\' own platform rather than being routed to an external venue or exchange.', 'withdrawal_deposit_note' => 'No CMC-side fees; third-party card processing of roughly 1-3% is possible. Card withdrawal timing varies by issuer (from about 1 hour up to 5 business days); UK domestic bank withdrawals take 1-2 days, international 3-5 days. Minimum deposit is $0 and minimum withdrawal $1.', 'overnight_financing' => 'Calculated as (units x level-1 mid price x holding rate) / 365 x CMC\'s currency-conversion rate where relevant. For FX, the holding rate is the tom-next rate plus or minus about 1%; for shares and indices, it\'s the underlying interbank rate plus or minus about 2.5%. Applied at 5pm New York time, per CMC\'s own published methodology.', 'currency_conversion_fee' => 'CMC\'s separate share-investing arm (CMC Invest, not the CFD/spread-betting product) discloses an FX conversion spread of up to about 0.99% on its entry-level tier, down to 0.39% on its top tier -- it\'s not confirmed whether the same figures apply identically to CFD/spread-betting currency conversion specifically.', 'inactivity_fee' => '£10/month (or currency equivalent, e.g. around $15 USD/CAD) on accounts with no open positions or trading activity for 12 continuous months; deducted in the first two UK working days of the month, cannot push the account negative, and up to 3 months of previously charged fees (max £30) are refunded on reactivation -- confirmed via CMC\'s own published FAQ.', 'customer_service_note' => 'Trustpilot rates it around 4.2-4.3/5 from 3,000+ reviews. Praise centers on platform ease-of-use, charting/research tools, and fast execution and funding; a recurring complaint is slow or unhelpful support, including criticism of chatbot-style first-line support.', 'mobile_note' => 'No numeric App Store or Google Play rating was found in this research pass.', 'education_note' => 'One independent review site gives it a Trust Score of 99/99 ("Highly Trusted"), with a 9.5/10 research score and 8.5/10 education score (noting it lacks progress-tracking or interactive features). Its Next Generation platform includes Reuters news, pattern recognition and sentiment data, and is regarded as strong for beginners by that source.', 'blurb' => 'Founded by Peter Cruddas in 1989 (originally as Currency Management Corporation; rebranded CMC Markets in 2005). Publicly listed on the London Stock Exchange, FTSE 250 constituent (CMCX), operating in 70+ countries from roughly a dozen offices.', 'scores' => array( 'regulation' => 4.2, 'cost' => null, 'platforms' => 2.6, 'track_record' => 3.77, 'overall' => 3.62 ), 'rank' => 12 ),
        array( 'slug' => 'saxo', 'name' => 'Saxo', 'entity' => 'Saxo Capital Markets UK Ltd', 'cysec' => null, 'fca' => '551422', 'founded' => 1992, 'hq' => 'Copenhagen, Denmark', 'min_deposit_usd' => null, 'min_deposit_display' => null, 'spread_eurusd' => null, 'platforms' => array('SaxoTraderGO', 'SaxoTraderPRO'), 'other_reg' => array('MAS'), 'other_reg_count' => 1, 'instruments' => null, 'account_types' => 'Classic (no minimum deposit under current UK policy, per recent sources -- older sources cite a $10,000 minimum, which appears outdated for the UK entity), Platinum (£200,000 deposit or 120,000 loyalty points), and VIP (£1,000,000+).', 'execution_model' => 'As a licensed bank, Saxo generally acts as principal/market-maker for most retail CFD and FX flow with institutional-grade pricing, rather than operating as a pure ECN broker.', 'withdrawal_deposit_note' => 'No withdrawal fee except when transferring a position to a competing broker; card deposits may carry a fee depending on country. The UK entity\'s previous £7.95 custody and platform fees have reportedly been removed.', 'overnight_financing' => 'Two components: tom/next swap points derived from Tier-1 bank quotes with a client-specific markup, and financing on unrealized profit/loss at a daily benchmark overnight rate plus or minus a markup (reported around 2.00%). Saxo uses Alternative Reference Rates as the benchmark input, falling back to a money-market or policy rate where none exists.', 'currency_conversion_fee' => '0.25% on the FX spot mid-price at the time of conversion, applied across account types -- reportedly cut down from a higher legacy rate in a January 2024 fee restructuring.', 'inactivity_fee' => 'Sources conflict: more recent material suggests no inactivity fee currently applies, while an older source cites a fee around $100-equivalent -- this may reflect a genuine policy change (Saxo announced a broad fee cut in January 2024) rather than an ongoing disagreement.', 'customer_service_note' => '24/5 support via phone, chat and support tickets. Trustpilot rates it around 3.7/5 from roughly 9,000 reviews -- notably more mixed than most other brokers researched so far.', 'mobile_note' => 'SaxoTraderGO ratings vary by region -- around 4.0/5 (roughly 6,250 reviews) on one country\'s App Store versus 4.5/5 (435 reviews) on another\'s, with no single global figure found.', 'education_note' => 'Offers beginner-to-advanced video content covering FX and CFDs, generally regarded as comprehensive given Saxo\'s institutional positioning, though independent commentary on depth relative to education-focused brokers wasn\'t found in detail.', 'blurb' => 'Saxo Bank A/S is a licensed Danish bank, not just a broker, reporting roughly USD 118bn in client assets. Ownership changed hands in 2024 when J. Safra Sarasin Group acquired a majority stake from Geely and Mandatum. Worth knowing: Saxo has been actively retrenching from APAC since mid-2024 -- it stopped onboarding new clients in Australia, Hong Kong and Japan, closed its Hong Kong/Shanghai offices, and agreed to sell the majority of its Australian business -- so its regulatory footprint outside the UK and Singapore should be reconfirmed rather than assumed current.', 'scores' => array( 'regulation' => 2.6, 'cost' => null, 'platforms' => 2.6, 'track_record' => 3.53, 'overall' => 2.87 ), 'rank' => 53 ),
        array( 'slug' => 'axi', 'name' => 'Axi', 'entity' => 'Axi Financial Services (UK) Limited', 'cysec' => null, 'fca' => '466201', 'fca_note' => 'The FCA has published a warning about a clone firm ("AXI Corp Limited") impersonating this genuine authorised UK firm -- verify you are dealing with Axi Financial Services (UK) Limited specifically.', 'founded' => 2007, 'hq' => 'Sydney, Australia', 'min_deposit_usd' => null, 'min_deposit_display' => null, 'spread_eurusd' => null, 'platforms' => array('MT4'), 'other_reg' => array('ASIC', 'DFSA', 'FMA'), 'other_reg_count' => 3, 'instruments' => null, 'account_types' => 'Standard (minimum $5, spreads from 0.4 pips, no commission), Pro (minimum $500, spreads from 0.0 pips, $7 commission), and Elite (minimum $25,000), with a swap-free/Islamic option available.', 'execution_model' => 'Standard is STP; Pro is described by one aggregator as a "modified ECN" routed to select liquidity providers -- a single-source characterization not independently corroborated elsewhere.', 'withdrawal_deposit_note' => 'No Axi-side withdrawal fee (third-party bank/card fees may apply). Minimum withdrawal ranges from $5 (card) to $50 (bank transfer), with processing from instant (card) to 1-3 days (bank/PayPal). Deposits are fee-free up to $50,000/month via card or Neteller.', 'overnight_financing' => 'Standard swap rates apply overnight; Islamic/swap-free accounts avoid these. The markup over the benchmark rate wasn\'t found.', 'currency_conversion_fee' => 'Per Axi\'s own FAQ, conversions use the FX spot mid-price at position close plus or minus up to 0.45%; this also applies to transfers between sub-accounts but not to margin collateral itself.', 'inactivity_fee' => 'Confirmed via Axi\'s own FAQ: no fee on active accounts; an account becomes inactive after 12 months with no open trades, after which a monthly fee applies equal to the lesser of 10 units of the account currency (e.g. $10) or the remaining balance.', 'customer_service_note' => 'Trustpilot TrustScore around 4/5 from 6,000+ reviews. Reviews are mixed: praise for staff professionalism and responsiveness alongside recurring complaints about withdrawal delays and unresolved account-access issues.', 'mobile_note' => 'Ratings are inconsistent across sources -- Google Play shows around 3.3/5 (1,300 reviews, with some reviewers reporting crashes during deposit/withdrawal), while the App Store is cited at around 3.6-3.7/5 in different sources. Reviewers generally praise beginner-friendliness despite the technical complaints.', 'education_note' => 'Reviewers note Axi provides educational resources and webinars, but no independently detailed course catalogue was found.', 'blurb' => 'Launched as AxiTrader/AxiCorp in 2007. Unlike most peers on this list, Axi currently offers only MT4 (enhanced with its own "NextGen" plugin) -- no MT5, cTrader or TradingView. Disclosed regulatory history: ASIC suspended AxiCorp\'s AFS licence for 4 months in January 2020 over client-money segregation and compliance failures (later reinstated with conditions on appeal), and New Zealand\'s FMA also suspended its derivatives licence in 2019.', 'scores' => array( 'regulation' => 4.2, 'cost' => null, 'platforms' => 1.8, 'track_record' => 2.3, 'overall' => 2.97 ), 'rank' => 43 ),
        array( 'slug' => 'spreadex', 'name' => 'Spreadex', 'entity' => 'Spreadex Ltd', 'cysec' => null, 'fca' => '190941', 'founded' => 1999, 'hq' => 'St Albans, Hertfordshire, UK', 'min_deposit_usd' => null, 'min_deposit_display' => null, 'spread_eurusd' => null, 'platforms' => array('Proprietary (Spreadex)'), 'other_reg' => array(), 'other_reg_count' => 0, 'instruments' => null, 'blurb' => 'Privately held UK company combining financial spread betting/CFDs with sports spread betting and a fixed-odds sportsbook -- an unusual dual business model. Long-established (25+ years) but relies solely on its FCA authorisation; no ASIC, FSCA, DFSA or other Tier-1 licence was found, so its international regulatory footprint is narrower than most brokers on this list.', 'scores' => array( 'regulation' => 1.8, 'cost' => null, 'platforms' => 1.8, 'track_record' => 2.96, 'overall' => 2.13 ), 'rank' => 99 ),
        array( 'slug' => 'hycm', 'name' => 'HYCM', 'entity' => 'HYCM Capital Markets (UK) Limited', 'cysec' => null, 'fca' => '186171', 'fca_note' => 'HYCM voluntarily renounced its CySEC licence (259/14, held via HYCM (Europe) Ltd) per a June 2024 CySEC decision, narrowing its direct EU/Tier-1 footprint -- do not assume current CySEC coverage without checking directly.', 'founded' => 1977, 'hq' => 'London, UK (parent Henyep Capital Markets Group originated in Hong Kong, with further entities in Cyprus and Dubai)', 'min_deposit_usd' => null, 'min_deposit_display' => null, 'spread_eurusd' => null, 'platforms' => array('MT4', 'MT5', 'Proprietary (HYCM Trader)'), 'other_reg' => array('DFSA'), 'other_reg_count' => 1, 'instruments' => null, 'account_types' => 'Fixed (minimum $20, fixed spreads from 1.8 pips, commission-free, automated trading/EAs not available), Classic (minimum $20, floating spreads from 1.2 pips, commission-free, EAs allowed), and Raw (STP/ECN-style, spreads from 0.2 pips, around $4 commission per round turn, minimum $20). An Islamic account is available across all three: swap-free for the first 14 days of a position, after which a reported $5-per-night storage fee per contract applies.', 'execution_model' => 'Generally STP; the Raw account is specifically described as STP/ECN-style.', 'withdrawal_deposit_note' => 'No HYCM-side deposit fees (card processing typically carries a 1-3% charge industry-wide). Withdrawals are fee-free above $300; below that, card withdrawals cost 1-4%, bank wire $20-50 per transaction, and e-wallets roughly 0.5-4% (often including currency conversion). Processing: card 1-3 business days, wire 1-4 business days, Skrill within 1 business day. Minimum deposit is reported as $20 generally, though card/wire may require $100 per some sources -- figures conflict slightly.', 'overnight_financing' => 'Standard floating swap (positive or negative depending on instrument) for non-Islamic accounts; no specific benchmark/markup breakdown was found. Islamic accounts are swap-free for the first 14 days, after which a flat $5-per-night storage fee replaces the swap.', 'currency_conversion_fee' => 'One source cites a "$10 currency conversion fee," but it\'s unclear whether this is per-transaction, flat, or percentage-based -- treat as unverified.', 'inactivity_fee' => 'One source cites $10/month after 90 days of dormancy; this wasn\'t cross-confirmed on a second independent page, so treat as provisional.', 'customer_service_note' => 'One source cites a Trustpilot Net Promoter Score of 88; another independent review site rates it 4.3/5 overall. Reviews are mixed, with some account-closure/payment-issue complaints. Worth disclosing: HYCM (Europe) Ltd voluntarily surrendered its CySEC licence effective 10 June 2024, and now operates in Europe only via its FCA (UK) and DFSA (Dubai) authorizations.', 'mobile_note' => 'Not independently confirmed -- no numeric App Store or Google Play rating was found for HYCM\'s app specifically.', 'education_note' => 'Offers video courses and webinars aimed at beginners; one reviewer specifically notes it lacks advanced educational content for experienced traders. Trading Central research tools (Analyst Views, economic calendar) are provided. One independent review site scores its education 7.5/10, research 7.0/10, and overall 7.8/10.', 'blurb' => 'Group traces to 1977 (Henyep Capital Markets Group); the "HYCM" brand itself was only adopted in 2016. A mid-sized broker relative to the largest names on this list, with its regulatory footprint recently reduced by the 2024 voluntary surrender of its CySEC licence.', 'scores' => array( 'regulation' => 2.6, 'cost' => null, 'platforms' => 3.4, 'track_record' => 4.75, 'overall' => 3.44 ), 'rank' => 20 ),
        array( 'slug' => 'activtrades', 'name' => 'ActivTrades', 'entity' => 'ActivTrades Plc', 'cysec' => null, 'fca' => '434413', 'fca_note' => 'The FCA has warned about clone/impersonation schemes copying ActivTrades\' branding (e.g. "activefinancial.trade", flagged February 2024) and an industry-reported lookalike ("RealFactorFX") -- these are scams impersonating the firm, not findings against the genuine, FCA-authorised ActivTrades Plc (FRN 434413).', 'founded' => 2001, 'hq' => 'London, UK', 'min_deposit_usd' => null, 'min_deposit_display' => null, 'spread_eurusd' => null, 'platforms' => array('ActivTrader (proprietary)', 'MT4', 'MT5', 'TradingView'), 'other_reg' => array(), 'other_reg_count' => 0, 'instruments' => null, 'account_types' => 'Individual (retail), Professional, and Islamic (swap-free) accounts, plus demo and (per some sources) managed accounts. No stated minimum deposit on the Individual, Professional or Islamic tiers under current information, though older sources cite $100.', 'execution_model' => 'Advertises a spread-only model with roughly 4ms execution and is generally classed by reviewers as an STP broker, though sources don\'t use that exact label verbatim.', 'withdrawal_deposit_note' => 'Methods include bank transfer, cards, Neteller, Skrill, AstroPay and Sofort. Card deposits carry a 1.5% fee (the first deposit is free); e-wallet deposits are free. Withdrawals are generally free except bank wire, which carries a flat £9 fee. Processing is around 30 minutes same-day for most methods, 1-5 business days for bank transfer.', 'overnight_financing' => 'Islamic accounts carry no rollover interest or commission, though cash indices are excluded from swap-free terms and crypto/stock positions may still incur charges. The standard-account swap calculation methodology wasn\'t found.', 'currency_conversion_fee' => 'Reported at 0.30% currently (down from a previously cited 0.5%) on deposits or withdrawals in a currency other than the account\'s base currency.', 'inactivity_fee' => 'Sources differ slightly on the exact trigger wording, but generally agree on £10/€10 per month after 12 consecutive months of no activity.', 'customer_service_note' => 'One independent review site rates its customer support 4.8/5 and overall 4.3/5. Its Trustpilot rating is currently listed as unavailable due to a guideline breach, though individual reviews remain visible.', 'mobile_note' => 'Reported around 4.9 on iOS and 3.8 on Android; one review site gives it 4 stars, ranking it 19th among mobile trading apps compared.', 'education_note' => 'Weekly insights, daily news, webinars and tutorials are praised by some reviewers, though independent commentary suggests it lags competitors like XTB and CMC Markets on course depth and interactive quizzes, and its research hub lacks Trading Central or Autochartist integration.', 'blurb' => 'Founded in 2001 as a Swiss stockbrokerage, relocating to London in 2005. Client base concentrated in Europe (notably Italy and Germany), the Middle East, Latin America and South-East Asia. Also holds EU regulation via CMVM Portugal and apparent CSSF Luxembourg passporting, plus offshore licences (Bahamas, Mauritius) -- none of which are on this site\'s Tier-1 list, so they aren\'t counted toward its regulation score here.', 'scores' => array( 'regulation' => 1.8, 'cost' => null, 'platforms' => 4.2, 'track_record' => 2.79, 'overall' => 2.77 ), 'rank' => 59 ),
        array( 'slug' => 'atc-brokers', 'name' => 'ATC Brokers', 'entity' => 'ATC Brokers Limited', 'cysec' => null, 'fca' => '591361', 'fca_note' => 'NFA/CFTC registration is held by a separate US affiliate entity (ATC Brokers, NFA ID 358522), not by this FCA-authorised UK firm directly -- treat it as group-level coverage, not a direct licence on this entity.', 'founded' => 2005, 'hq' => 'London, UK (also offices in Glendale, California, US and the Cayman Islands)', 'min_deposit_usd' => null, 'min_deposit_display' => null, 'spread_eurusd' => null, 'platforms' => array('MT4', 'MT Pro (proprietary MT4 enhancement)'), 'other_reg' => array('NFA/CFTC (US)'), 'other_reg_count' => 1, 'instruments' => null, 'blurb' => 'Operates an ECN/STP (agency) model explicitly positioned for professional and institutional/high-volume traders rather than mass retail. Also holds Cayman Islands Monetary Authority (CIMA) licensing for offshore clients, which is not on this site\'s Tier-1 list and so isn\'t counted toward its regulation score.', 'scores' => array( 'regulation' => 2.6, 'cost' => null, 'platforms' => 2.6, 'track_record' => 2.47, 'overall' => 2.56 ), 'rank' => 77 ),
        array( 'slug' => 'vantos-markets', 'name' => 'Vantos Markets', 'entity' => 'Vantos Markets (UK) Limited', 'cysec' => null, 'fca' => '709693', 'fca_note' => 'Renamed from Capital Index to Vantos Markets in February 2026 following a change in ownership. The firm reported a 31% revenue decline and a GBP154,000 net loss for FY2025 -- a small, recently rebranded shop with a thinner regulatory and financial profile than most peers on this list. Its related Cyprus entity (Capital Index Europe) surrendered its CySEC licence in 2018 and is not currently authorised there.', 'founded' => 2014, 'hq' => 'London, UK', 'min_deposit_usd' => null, 'min_deposit_display' => null, 'spread_eurusd' => null, 'platforms' => array('MT4'), 'other_reg' => array(), 'other_reg_count' => 0, 'instruments' => null, 'blurb' => 'Founded as Capital Index by Robert Woolfe in 2014; renamed Vantos Markets in 2026 after new ownership took over. The new owners have indicated unspecified future platform enhancements, but only MT4 is confirmed live as of this research.', 'scores' => array( 'regulation' => 1.8, 'cost' => null, 'platforms' => 1.8, 'track_record' => 1.73, 'overall' => 1.78 ), 'rank' => 113 ),
        array( 'slug' => 'ultima-markets', 'name' => 'Ultima Markets', 'entity' => 'Ultima Markets UK Limited', 'cysec' => '426/23', 'cysec_note' => 'CySEC licence 426/23 is held by a separate group entity, Ultima Markets Cyprus Ltd, serving EU clients -- a different legal entity from the UK FCA firm reviewed here.', 'fca' => '470325', 'fca_note' => 'The UK entity only obtained FCA authorisation in 2025 and was still in the process of onboarding UK retail clients as of this research (2026) -- confirm current live UK status before relying on it. Non-EU/global clients are onboarded via separate Mauritius FSC and St Vincent & Grenadines SVGFSA entities, neither of which is on this site\'s Tier-1 list.', 'founded' => 2016, 'hq' => null, 'min_deposit_usd' => null, 'min_deposit_display' => null, 'spread_eurusd' => null, 'platforms' => array('MT4', 'MT5', 'Proprietary (UM Terminal)'), 'other_reg' => array('FSCA'), 'other_reg_count' => 1, 'instruments' => null, 'blurb' => 'A large multi-entity global CFD group (1,000+ instruments, presence claimed in 170+ countries, an FC Internazionale Milano sponsorship deal) marking its 10th anniversary in 2026; its UK FCA entity, however, is brand new and not yet fully live for UK retail as of this research.', 'scores' => array( 'regulation' => 2.6, 'cost' => null, 'platforms' => 3.4, 'track_record' => 1.57, 'overall' => 2.53 ), 'rank' => 81 ),
        array( 'slug' => 'gildencrest-capital', 'name' => 'Gildencrest Capital', 'entity' => 'Gildencrest Capital Limited', 'cysec' => null, 'fca' => '564741', 'fca_note' => 'The FCA has published a clone-firm warning for "gildencrestcap.com" (note: missing "ital") impersonating this firm via fake emails -- the genuine firm is Gildencrest Capital Limited, FRN 564741, Canary Wharf, London. Rebranded from TeraFX on 1 February 2024; parent is Turkish investment group Tera Yatirim.', 'founded' => 2011, 'hq' => 'London, UK (Canary Wharf); also an office in Warsaw, Poland', 'min_deposit_usd' => null, 'min_deposit_display' => null, 'spread_eurusd' => null, 'platforms' => array('MT4', 'MT5 (spread-betting clients only)'), 'other_reg' => array(), 'other_reg_count' => 0, 'instruments' => null, 'blurb' => 'FCA-authorised since 2011 as Tera Europe Ltd, trading as TeraFX, before rebranding to Gildencrest Capital in February 2024. Reported revenue grew 52% to GBP7.55m in 2023.', 'scores' => array( 'regulation' => 1.8, 'cost' => null, 'platforms' => 2.6, 'track_record' => 1.98, 'overall' => 2.08 ), 'rank' => 102 ),
        array( 'slug' => 'ogm', 'name' => 'OGM', 'entity' => 'One Global Market Limited', 'cysec' => null, 'fca' => '769481', 'fca_note' => 'OGM voluntarily paused client trading from September 2024 through the end of 2025 (roughly 13 months) during a platform migration and is only now (2026) relaunching, targeting "UK-based sophisticated traders" rather than mass retail -- a material, disclosed gap in its operating history. Separately, the FCA has warned about a clone ("OGM Markets" at ogm.markets, plural domain) impersonating the genuine firm at ogm.market (singular) -- verify the domain before using this broker.', 'founded' => 2016, 'hq' => 'London, UK', 'min_deposit_usd' => null, 'min_deposit_display' => null, 'spread_eurusd' => null, 'platforms' => array('MT4'), 'other_reg' => array(), 'other_reg_count' => 0, 'instruments' => null, 'blurb' => 'FCA-authorised since 2017, controlled by Israeli entrepreneur Roei Feinberg and run by CEO Naji Karak (ex-FXCM). Acts primarily as an agency broker/API provider for OTC CFDs rather than a platform-first retail broker.', 'scores' => array( 'regulation' => 1.8, 'cost' => null, 'platforms' => 1.8, 'track_record' => 1.57, 'overall' => 1.73 ), 'rank' => 114 ),
        array( 'slug' => 'noor-capital-uk', 'name' => 'Noor Capital UK', 'entity' => 'Noor Capital UK Limited', 'cysec' => null, 'fca' => '631382', 'fca_note' => 'Formerly House of Borse; acquired by Noor Capital (Abu Dhabi) in 2023 and renamed. Its founding date and current UK office address are disputed/unconfirmed across sources, so neither is stated here. Reported turnover fell 83% in 2025 with the firm swinging to an annual loss -- a notable financial red flag. Historically served professional/institutional clients rather than mass retail.', 'founded' => null, 'hq' => null, 'min_deposit_usd' => null, 'min_deposit_display' => null, 'spread_eurusd' => null, 'platforms' => array('MT4', 'MT5'), 'other_reg' => array(), 'other_reg_count' => 0, 'instruments' => null, 'blurb' => 'UK entity of Noor Capital, part of Abu Dhabi\'s Al Sayegh Brothers Group. Parent Noor Capital (UAE) is regulated by Abu Dhabi\'s Department of Economic Development and the UAE Securities and Commodities Authority -- neither of which is on this site\'s Tier-1 list, so neither is counted toward this broker\'s regulation score.', 'scores' => array( 'regulation' => 1.8, 'cost' => null, 'platforms' => 2.6, 'track_record' => null, 'overall' => 2.12 ), 'rank' => 101 ),
        array( 'slug' => 'stonex-trading', 'name' => 'StoneX Trading', 'entity' => 'StoneX Financial Ltd', 'cysec' => null, 'fca' => '446717', 'fca_note' => 'StoneX Trading is the direct successor to the City Index retail brand, renamed 9-12 September 2026 (same FCA entity, StoneX Financial Ltd, same accounts and platforms carried over -- not a new company). This entity is UK-retail-focused; the wider StoneX Group\'s other Tier-1 licences (NFA/CFTC in the US, ASIC in Australia, CIRO in Canada, MAS in Singapore, and CySEC in Cyprus via a separate entity trading as FOREX.com, also reviewed on this site) are held by separate sister entities within StoneX Group Inc. (Nasdaq: SNEX), not by this UK entity directly, so they are not counted toward this broker\'s regulation score. As a brand name, "StoneX Trading" is only weeks old at the time of this review, so independent public track record and reviews under this specific name are minimal.', 'founded' => 1983, 'hq' => 'London, UK (parent StoneX Group Inc. headquartered in New York, USA; Nasdaq: SNEX)', 'min_deposit_usd' => null, 'min_deposit_display' => null, 'spread_eurusd' => null, 'platforms' => array('MT4', 'Web Trader (proprietary)', 'TradingView charting'), 'other_reg' => array(), 'other_reg_count' => 0, 'instruments' => null, 'account_types' => 'A Standard CFD/spread-betting account, an MT4 account, and an Elective Professional tier for qualifying high-volume clients.', 'execution_model' => 'Independent reviewers (published under the former City Index name, before the September 2026 rebrand) describe it as operating an internal dealing desk/market-maker model, which they flag as a potential conflict of interest versus pure STP/ECN brokers.', 'withdrawal_deposit_note' => 'Card minimum 100 units of the base currency, PayPal minimum 50 units, and no stated minimum for bank wire. All deposits and withdrawals are free of charge from the broker\'s side. Online withdrawals are capped at £20,000 per transaction, with processing taking 3-5 business days.', 'overnight_financing' => 'Published formula: daily fee = position value times rate, divided by a 365- or 360-day basis depending on currency. The rate is a regional benchmark (e.g. SONIA for GBP, SOFR for USD, EUR short-term rate for EUR) plus or minus a 2.5% markup; FX pairs instead use standard swap points.', 'currency_conversion_fee' => 'The broker states that "commercially reasonable rates" apply to currency conversions, disclosed on contract notes and statements, but no flat percentage is published.', 'inactivity_fee' => 'Sources disagree on the exact amount -- one cites £12/month after 12 months of no trading, another £10/month -- though both agree the fee is waived if the client trades during that period, and both describe it as a recurring source of user complaints.', 'customer_service_note' => 'Trustpilot (under the former City Index name) rates it 4.3/5 from around 390 reviews, with 24/5 live chat support; the inactivity fee is the most commonly cited complaint.', 'mobile_note' => 'One independent review site rates the app 4.5/5, ranking it 9th of 63 brokers reviewed for mobile trading -- though this and the reviews above predate the September 2026 rename and may not yet reflect the StoneX Trading brand specifically.', 'education_note' => 'Historically ran a structured "Trading Academy" course series; current offering includes beginner and advanced videos, positioned as beginner-friendly.', 'blurb' => 'One of the UK\'s oldest spread-betting/CFD brands (founded 1983 by Chris Hales and Jonathan Sparke as City Index), acquired by GAIN Capital in 2014, which was in turn acquired by Nasdaq-listed StoneX Group in 2020. The City Index brand was formally retired in the UK on 12 September 2026 and replaced by StoneX Trading, with existing clients migrated and no change to accounts or platforms.', 'scores' => array( 'regulation' => 1.8, 'cost' => null, 'platforms' => 3.4, 'track_record' => 4.26, 'overall' => 2.96 ), 'rank' => 45 ),
    );
